وش ارئح المجتمع من خالل نظام التكنولجيا المالية hceTniF الحديثة والمبتكرة، باإلضافة إلى زيادة التوعية والتعليم
المالي استهداًف ا لتحقيق رفاهية مالية مستدامة للمجتمع.
وبعبارة أخرى يشير الشمول المالي إلى تلبية احتياجات األف ارد والشركات - من المعامالت المالية والمدفوعات
والمدخ ارت واالئتمان والتأمين والمعاشات ..الخ - من أجل تحقيق رفاهية مالية مستدامة للمجتمع.
