ٌ
درجة نمو التكنولجيا المالية المبتكرة بشكل مكثف.
األمر الذي يتطلب توفير سياسات ونظم رقابية فعالة لضمان تقديم منتجات وخدمات مالية مناسبة لجميع األف ارد،
خاصة للفئات األكثر احتياج ا، وأيض ا لتشجيع استخدام التكنولوجيا المالية لتعزيز الشمولية.
ً ً
ويسهم وجود نظم فعالة وقوية - لحماية المتعاملين في القطاع المالي - في تعزيز المصداقية والثقة في القطاع المالي،
والتقليل بشكل كبير من حدوث أية إض ارر بمصالح المتعاملين.
ويدعم التثقيف المالي الشمول المالي عن طريق ت زويد المتعاملين األف ارد بمعلومات كافية، والد ارية بالمنتجات أو الخدمات
المالية المقدمة لهم، وكيفية االستفادة منها، وزيادة توعيتهم بحقوقهم وتفهمهم لمسئولياتهم عند التعامل في األسواق المالية.
ومن المتعارف عليه أن المتعاملين - خاصة األف ارد - سوف يتخذون ق ارارت مالية مهمة طوال حياتهم مثل استثمار
أموالهم، أو االقت ارض بغية ش ارء عقار، أو ش ارء بوالص تأمين على الحياة، أو اختيار نظام للمعاشات...الخ.
ونتيجة التقدم التكنولوجي واالبتكار في مجال الخدمات المالية ت ازيدت االختيا ارت المتاحة لألف ارد، وازدت معها في نفس
الوقت التحديات التى تواجه األف ارد؛ ألن العديد منهم ليس لديه الخبرة أو الوعي المالي أو المعلومات الكافية عن الخدمات
المالية المتاحة من قبل المؤسسات المالية.
ومن هنا تظهر أهمية الدور الذي تلعبه الجهات الرقابية والتنظيمية في حماية المتعاملين لتجنب وتقليل المخاطر التي قد
يتعرض لها األف ارد والتي قد تؤثر أيض ا بالسلب على االقتصاد الكلي.
