وقد تنامى االهتمام الدولي خالل العقد الماضي بموضوع حماية المتعاملين في األسواق المالية، على أثر تداعيات
األزمة المالية العالمية (7002/ 8002)، باإلضافة إلى ما شهدته األسواق من ابتكار في الخدمات واألدوات المالية
المتاحة، بسبب تطور ونمو التكنولوجيا المالية، والذي ازد من فرص نقل المخاطر إلى المتعاملين، بسبب قلة المعرفة
والوعي المالي لديهم.
ويعد طرح العديد من المنتجات المالية المبتكرة والمعقدة - والتي احتوت على نسب مخاطر عالية، وعدم تمكن األف ارد
من إد اركها وتعرضهم لخسائر مالية جسيمة - أحد أهم أسباب األزمة المالية العالمية.
ويشكل التوسع في التكنولوجيا المالية - مثل المعامالت والخدمات المالية عن طريق هواتف المحمول، وكذا الخدمات
المالية من خالل اإلنترنت، والبنوك الرقميةgniknaB latigiD ..الخ - ظاهرة عالمية واسعة االنتشار خاصة في
الدول النامية.
وقد قدرت مؤسسة النظام العالمي لالتصاالت المتنقلة snoitacinummoC eliboM rof metsyS labolG أن
أكثر من 06% من سكان العالم استخدموا التكنولوجيا المالية في تعامالتهم عام 6102؛ وقد أدى ذلك إلى زيادة
الفرص لدمج الفق ارء والمهمشين وتحولهم من النظام المالي غير الرسمي إلى النظام المالي الرسمي، عن طريق التغلب
على العقبات المادية وخفض التكاليف؛ وبالتالي توسيع فرص الحصول على أنواع جديدة من المنتجات والخدمات
المالية بطرق أسرع وأكثر أمن ا، وعليه أصبح التمويل أيسر وفي متناول جميع األف ارد.
ً
وقد ازمن ذلك ب ر وز عدة مخاطر نتيجة النتشار التكنولوجيا المالية مثل: عدم اإلفصاح الكافي والواضح ألهم البيانات
واإلج ارءات، أو المعامالت غير العادلة، أو مخاطر سالمة وسرية البيانات، باإلضافة لظهور عروض رقمية وهمية قد
تكون موضع ا للشك ومجهولة الهوية، وقد ازدت تلك المخاطر نتيجة لغياب الوعي والثقافة لدى األف ارد بالتكنولوجيا المالية.
ً
باإلضافة إلى ذلك، ظهرت بعض اآلثار الضارة بالتكنولوجيا المالية مثل تهميش بعض الفئات التي ليس لديها معرفة
وإد ارك كافيان بالخدمات المالية مثل النساء أوكبار السن أو ساكني المناطق الريفية؛ مما يحرم هؤالء من فرصة
استخ ارج البطاقات االئتمانية أو الوثائق التأمينية المتناهية الصغر من خالل التكنولوجيا المالية، أو يعرضهم لخطورة
فرط االستدانة بسبب كثرة استخدام البطاقات االئتمانية، خاصة بالنسبة للطلبة أو األف ارد من ذوي الدخول المنخفضة؛
نتيجة لقلة ثقافتهم المالية.
