وي برز ذلك ضرورة أن تكون المنتجات والخدمات المالية غير المصرفية مصممًة ومناسبًة وفًق ا لمتطلبات المتعاملين
-خاصة األف ارد- وفي أطر واضحة لما تنطوي عليه من مخاطر؛ وبسبب التطوارت المالية ازدت أهمية حماية األف ارد
ودمجهم بالشمول المالي وسياسات التثقيف والتوعية المالية ضمن األطر القانونية التي توفر للمتعاملين حماية حقوقهم
عن طريق حصولهم على معامالت عادلة وإفصاحات مناسبة، وتحسين ثقافتهم المالية وتزويدهم بالنصائح الالزمة مع
تقديم الخدمات المالية لهم ضمن أطر عمل تنافسية وفي إطار سلوك مهني، مع م ارعاة حماية خصوصية وسرية
بيانات العمالء من أي انتهاك لسريتها أو تعرضها للتزوير واستغاللها بأي شكل من األشكال، وكذا الحد من المخاطر
التي قد يتعرض لها األف ارد من خالل توفير سبل الضمانات والتعويضات المناسبة لهم، والعمل على تسوية أي ن ازعات
أو شكاوى قد تنشأ بينهم والمؤسسات المالية التي تقدم لهم المنتجات والخدمات المالية.
وفى إطار ما تقدم، أصبح موضوع حماية المتعاملين يشكل توجه ا عالمي ا ذا أهمية كبرى ضمن السياسات العامة
ً ً
لمختلف الدول؛ للحفاظ على مصالح المتعاملين، خاصًة في ظل صعوبة اتخاذ ق ارارت مالية في األسواق المالية التي
تتسم حالي ا بالمنتجات المالية المعقدة، والتي ليس من السهل على المتعاملين األف ارد إد ارك مخاطرها.
ً
ومن أهم وسائل حماية المتعاملين في السواق المالية:
- الشفافية: بحيث يتم رفع مستوى الشفافية بغية تمكين وإحاطة المتعاملين في األس واق المالية بكل األحكام المتعلقة
بالمنتجات والخدمات المالية مثل أسعار المنتجات والخدمات المقدمة، وشروطها، والمخاطر المتوقعة..الخ.
- المعاملة العادلة: وذلك بتعزيز ممارسات الخدمات المالية العادلة والمنصفة، عن طريق وضع الحد األدنى من
المعايير للمؤسسات المالية أثناء تعاملهم مع العمالء؛ ليطمئن المتعامل ون بأن المنتجات والخدمات المالية
المعروضة عليهم آمنًة وغير مضللة، وكذا لضمان سلوكيات مقدمي الخدمات المالية ووكالئهم والعاملين لديهم
بأنها غير عدوانية أو تعسفية، األمر الذي يضمن حرفية مقدمي الخدمات المالية واحت ارمهم لحقوق المتعاملين.
- الحد من المخاطر: باتخاذ التدابير الالزمة والمناسبة من قبل مقدمي الخدمات المالية التى تكفل وتحدد وترصد
وتخفف من وطأة المخاطر التي يواجهها المتعامل ون كالنصب واالحتيال، أو تناول بيانات العمالء بشكل غير
مالئم، والتي تزداد درجة خطورتها تباع ا مع نمو الخدمات المالية المبتكرة.
ً
- تسوية المنازعات وحل شكاوى المتعاملين: من خالل توفير آليات تتسم بالكفاءة والفعالية والسرعة لتسوية وحل
المنازعات أو شكاوى العمالء المتعلقة بتوفير الخدمات المالية. وينبغي على مقدمي الخدمات المالية أن تكون
لديهم اإلمكانيات والنظم الفعالة لمعالجة أي استفسا ارت أو شكاوى مقدمة من المتعاملين.
- تعزيز الثقة: إن توفير حماية للمتعاملين يعد ضرو رة وأساس ا لضمان الثقة في النظام المالي الكلي، ويسهم في
ً
تعزيز كفاءة واستق ارر األسواق المالية، والحصول على نتائج مرضية لكل من المؤسسات المالية والمتعاملين.
5

ا
ثاني ا: نبذة عن دور اهليئة العامة للرقابة املالية اإلشرايف والرقابي على األنشطة املالية غري املصرفية
ومن بينها: سوق املال، والتأمني، وصناديق التأمني اخلاصة، والتمويل العقاري، والتأجري التمويلي،
والتخصيم، والتمويل متناهي الصغر، وملخص القوانني التي ختتص بتلك األنشطة:
حرص القانون رقم 01 لسنة 9002 بتنظيم الرقابة على األسواق واألدوات المالية غير المصرفية على تأكيد
االختصاصات الرئيسية والمحورية للهيئة العامة للرقابة المالية في مجال تنظيم األنشطة المالية غير المصرفية وضبط
أسواقها وم ارقبة سالمة أدائها، بعد أن حلت الهيئة العامة للرقابة المالية محل ك ل من الهيئة العامة لسوق المال، والهيئة
العامة للرقابة على التأمين، والهيئة العامة لشئون التمويل العقاري .
كما أسند إلى هيئة الرقابة المالية االختصاص بتنظيم وم ارقبة نشاطي التأجير التمويلي والتخصيم؛ وفي عام 4102
اختصت الهيئة باإلش ارف والرقابة على نشاط التمويل متناهي الصغر.
وقد أناط القانون بالهيئة العمل على سالمة واستق ارر األسواق المالية غير المصرفية وتنظيمها وتنميتها، وتوازن وحماية
حقوق المتعاملين فيها من شركات وأف ارد طبيعيين، وكذا إصدار القواعد التي تضمن كفاءة هذه األسواق وشفافية
األنشطة التي تمارس فيها، وعلى األخص: الترخيص بم ازولة األنشطة المالية غير المصرفية، والتفتيش على الشركات
العاملة، وحماية حقوق المتعاملين، والمساهمة في نشر الثقافة والتوعية المالية.
كما أوجب القانون أن يتم إنشاء مركز للتحكيم والتسوية في المنازعات التي تنشأ بسبب تطبيق أحكام القوانين التي تباشر
الهيئة إنفاذها؛ وفي هذا المجال، قامت الهيئة بإعداد مشروع ق ارر إنشاء مركز التحكيم المشار إليه، والذي تمثلت أهم
مالمحه في استقالليته، فضالً عن ترسيخ دور التحكيم والوساطة والتوفيق كأحد الوسائل الودية البديلة والناجزة.
واستحدث القانون إنشاء معهد الخدمات المالية، والذي يتميز باستقالليته، وي ازول العديد من االختصاصات، والتي
يأتي في مقدمتها تنمية مها ارت العاملين في مجال الخدمات المالية، ونشر الثقافة والتوعية المالية واالستثما رية.
وقد أصدرت الهيئة العامة للرقابة المالية ق ارارت وقواعد ولوائح متكاملة إلرساء المنافسة العادلة، والشفافية واإلفصاح،
ومظلة حماية فعالة ومتوازنة للمتعاملين في مجال الخدمات المالية غير المصرفية.
وفيما يلي نلقي الضوء على القوانين التي تختص الهيئة بتطبيقها أو تسهم بإنفاذها.
6

1. قانون سوق أرس المال رقم 59 لسنة 2991 والئحته التنفيذية:
صدر قانون سوق أرس المال رقم 59 لسنة 2991 والئحته التنفيذية؛ بهدف تنظيم وتطوير األسوق المالية، ووضع
األسس والمبادئ والمعايير التي تضمن توفير المناخ المالئم لالستثمار وتدعم الثقة به.
وفيما يلي نستعرض أهم المحاور التي تناولها القانون:
أ. الوارق والدوات المالية:
عمل القانون على تنظيم األوارق واألدوات المالية التي يجوز التعامل عليها من أسهم وسندات وصكوك وسندات
توريق وغيرها من األدوات المالية، وتنظيم إصدارها وتداولها، والضوابط التي يجب م ارعاتها عند طرح أي من
تلك األدوات في اكتتاب أو طرح عام أو طرح خاص، فضالً عن تنظيم قواعد قيد وشطب وإيقاف التعامل على
هذه األوارق المالية كل بحسب طبيعته. و روعى في هذا التنظيم العديد من المتطلبات مثل: نشر نشرة االكتتاب
ٌ َ
والطرح العام ومذك ارت المعلومات للطرح الخاص، وكذا نشر ملخص القوائم المالية واإليضاحات المتممة وتقارير
م ارقبي الحسابات.
وإدارك ا لمدى أهمية وجود أدوات دين قصيرة األجل، فقد استحدث القانون تنظيم ا خاص ا لهذه األدوات، يتناسب
ً
ً ً
مع طبيعة أعمال الشركات؛ بما يستهدفه من تمويل أرس المال العامل.
كما تضمن القان ون أحكام ا خاصة بعروض الش ارء وعمليات االستحواذ على األدوات المالية؛ بما يسمح بتنظيمها
ً
على نحو أفضل، وكذا حماية المتعاملين والحفاظ على حقوق األقلية.
ب. النشطة التي يجوز للشركات والجهات مازولتها
كفلت أحكام القانون وضع تنظيم كامل بشأن التعامل على األوارق واألدوات المالية المشار إليها، ابتداء من
ً
إيضاح األنشطة التي يمكن م ازولتها، ومرو ار بالشركات والجهات التي يسمح لها بمباشرة تلك األنشطة، انتهاء
ً
ببيان اآلليات المتفرعة عن هذه األنشطة الرئيسية. ويشمل ذلك: ترويج وتغطية االكتتاب في األوارق المالية،
واالشت ارك في تأسيس الشركات التي تصدر أوارًق ا مالية أو في زيادة رؤوس أموالها وبنوك االستثمار، وأرس المال
المخاطر، والمقاصة والتسوية في معامالت األوارق المالية، وتكوين وإدارة محافظ األوارق المالية وصناديق
االستثمار، والسمسرة في األوارق المالية، والتوريق، واالستشا ارت المالية، ونشاط صانع السوق، وشركات خدمات
اإلدارة في مجال صناديق االستثمار، ونشاط أمناء الحفظ، والسمسرة في السندات، وشركات الوساطة في بورصات
العقود اآلجلة، وشركات االستثمار المباشر وشركات التصكيك وإصدار الصكوك.
7

وقد حدد القانون متطلبات وإج ارءات التأسيس والترخيص لتلك الشركات، مشدد ا على عدم جواز م ازولة أ ي من
ً
األنشطة المشار إليها إال بعد الحصول على ترخيص بذلك من الهيئة.
ومن أهم المتطلبات، أن تتخذ الشركة طالبة الترخيص شكل ش ركة مساهمة أو توصية باألسهم، وااللت ازم بالحد
األدنى ل أرس المال، والذي يتحدد بشكل دقيق بناء على متطلبات السوق ووفًق ا لحجم األنشطة التي تباشرها
ً
الشركة، فضالً عن عدم صدور أحكام جنائية أو متعلقة بشهر اإلفالس ضد أ ي من مؤسسي الشركة وعامليها.
ّ
وإ ازء ما توليه الهيئة من اهتمام بشأن كفاءة الشركات والقائمين عليها، وضمان م ازولة تلك الكيانات لألنشطة
المشار إليها بما يخدم كافة األط ارف ذات الصلة، أصدرت الهيئة قواعد حوكمة الشركات العاملة في مجال
األوارق المالية في عام 6102، والتي ألقت على الشركات العديد من االلت ازمات، من بينها: اإلفصاح لدى الهيئة
عن أية أحداث جوهرية تتعرض لها الشركة: كرفع دعوى من الغير على أحد مساهميها الرئيسيين، أو أعضاء
مجلس إدارتها، أو تعرض الشركة للعجز المالي؛ كما ألزمت هذه القواعد الشركات بتوفير لجان منبثقة عن مجلس
ّ
اإلدارة (لجنة الم ارجعة- لجنة المخاطر.. الخ)، وأوضح الق ارر األحوال التي يتعين على الشركات االلت ازم بهذه
اللجان، كالتناسب مع حجم نشاط الشركة وعمالئها.
وتحقيًق ا لتمثيل األقلية في مجالس إدا ارت الشركات، صدر ق ارر مجلس إدارة الهيئة الق ارر رقم 551
لسنة 8102 ملزم ا الشركات ال ارغبة في الحصول على موافقة الهيئة المبدئية على التأسيس أو الحصول على
ً
ترخيص، أن ينص نظامها األساسي على استخدام نظام التصويت الت اركمي في انتخاب أعضاء مجلس اإلدارة،
بما يسمح بالتمثيل النسبي ل أرس المال في عضوية مجلس اإلدارة.
كما نظم القانون أحكام التعامل على آليات الش ارء بالهامش، والش ارء والبيع في ذات الجلسة، واقت ارض األوارق
المالية بغرض البيع، مؤكد ا على المتطلبات اإلضافية الواجب توافرها بما يتالءم مع ما تسهم به هذه اآلليات من
ً
مخاطر، ومن أهمها توافر المالءة المالية.
ج. تنظيم العالقة بين العمالء والشركات أو الجهات
وضع القانون إطا ار يكفل احت ارم وتنفيذ االلت ازمات المتبادلة بين الشركات والجهات العاملة في األوارق واألدوات
ً
المالية وعمالئهم، وتتباين هذه االلت ازمات بحسب ما إذا كانت العمليات خارج المقصورة، أم داخلها. ومن أهم
المتطلبات الخاصة بالعمليات خارج المقصورة، التأكد من سندات الملكية، والمخالصات المالية، واستيفاء اإلق ارارت
التي تضمن هذه العمليات من األط ارف ذات الصلة.
8

أما العمليات التي يتم إج ارؤها داخل المقصورة، فيمكن تقسيمها إلى: الت ازمات تسري أثناء تنفيذ عمليات التداول،
والت ازمات عامة، ومن أبرز االلت ازمات األولى: إل ازم الم ارقب الداخلي بالتأكد من تنفيذ أوامر العمالء قبل تنفيذ أية
أوامر على األوارق المالية التي تخص المديرين أو العاملين بالشركة، وإل ازم شركة السمسرة بتسجيل أوامر العمالء
فور ورودها وتنفيذها في الحدود الصادرة بها.
كما ألزم القانون شركة السمسرة - التى نفذت عملية على خالف أوامر العميل أو على ورقة مالية غير جائز
تداولها - بتسليمه ورقة غيرها.
وأرست المادة 412 من الالئحة التنفيذية للقانون مبدأ ً عام ا، بمقتضاه تلتزم الشركات بم ارعاة األع ارف التجارية
ً
ومبادئ األمانة والعدالة والمساواة والحرص على مصالح العمالء، وبذل عناية الرجل الحريص.
كما ألزم القانون الم ارقب الداخلي بالشركة بأن يحتفظ بملف لجميع شكاوى العمالء؛ ولضمان إثبات الحقوق
أوجب القانون على الشركات االحتفاظ بالدفاتر التى توضح مركزها المالي والحسابات والسجالت والمستندات
د ا على عدم التعامل المفرط
ً
واإلخطا ارت، فضالً عن الت ازمها بإرسال أية مستندات لعمالئها حال طلبهم لها، مشد
أو اختالق عمليات بهدف زيادة عموالت السمسرة أو غير ذلك من المصروفات واألتعاب.
د. الجهات ذات الصلة في إنفاذ القانون
عمل القانون على وضع تنظيم للجهات واألجهزة التي تختص بتنفيذ قانون سوق أرس المال تحت إش ارف ورقابة
الهيئة وأهمها:
•
البورصة المصرية
أرسى القانون دور البورصة المصرية كمنصة رئيسية لقيد وتداول األوارق المالية للشركات في السوق -ومن بينها
الشركات المتوسطة والصغيرة فى بورصة النيل- لمساعدتها على االنطالق والنمو.
كما تعمل البورصة على المساهمة في حصول الشركات على التمويل من خالل إصدا ارت األوارق واألدوات
المالية، وتسهم في العمل على ضمان كفاءة التسعير، وعدالة التعامل في السوق واستم ارريته، وتضع نظم العمل
والقواعد التي من شأنها ضمان سالمة عمليات التداول وحسن أداء البورصة لوظائفها، فضال ً عن م ارقبة عمليات
التداول اليومي والتحقق من تطبيق القوانين والق ارارت.
كما أن للبورصة إلغاء أثر العمليات المخالفة واتخاذ التدابير التنفيذية التي تكفل حماية السوق من الغش
والتالعب، ومن أبرزها إلغاء العمليات وإيقاف أكواد العمالء المخالفين.
وتلتزم البورصة بتطبيق أفضل الممارسات الدولية، وخاصة فيما يتعلق بالشفافية والن ازهة والرقابة على التداول
وحماية حقوق المستثمرين، باإلضافة للعمل باستم ارر على تدعيم البنية التنظيمية والتكنولوجية للسوق.
9

• شركة مصر للمقاصة واإليداع والقيد المركزي
أ نشئت شركة مصر للمقاصة واإليداع والقيد المركزي استناد ا إلى قانون اإليداع والقيد المركزي ؛ بغرض القيام
ً
بالعديد من المهام، في مقدمتها، مباشرة نشاط المقاصة وتسوية المعامالت التي تتم بالبورصة المصرية، وتطبيق
نظام الحفظ المركزي لألوارق المالية، وذلك وفًق ا ألحدث األنظمة والتطبيقات الدولية المعمول بها في مجاالت
اإليداع والمقاصة والتسوية. فضالً عن انتهاج أفضل الممارسات التكنولوجية المتطورة والمعايير الدولية في حفظ
وتسجيل ملكية األوارق المالية.
وقد صدر القانون رقم 39 لسنة 0002 والئحته التنفيذية منظ ما كافة المسائل المتعلقة بشركات اإليداع والقيد
ً
المركزي، من حيث األنشطة التي تمارسها، وإج ارءات التأسيس والترخيص لهذه الشركات، ومعايير الكفاءة المالية
والمهنية الواجب توافرها في تلك الشركات، كما نظم عمل أمناء الحفظ، واالشت ارطات الواجب توافرها في تلك
الجهات للترخيص لها بم ازولة النشاط والمتمثل في حفظ األوارق المالية والتعامل عليها وإدارتها لصالح المالك
أو غيره، على النحو المشار إليه بالقانون، وأنشطة بنوك اإليداع والمالك المسجل.
فضالً عن تنظيم دور الهيئة الرقابي على تلك الجهات من تفتيش على أعمالها، وكذا ما عهد به القانون إلى
م ارقبي الحسابات المقيدين لدى الهيئة بم ارجعة حسابات تلك الشركات. وأ فرد الباب العاشر من القانون للعقوبات
التي توّقع على المخالفين ألحكامه، وتتنوع بين الغ ارمة والحبس وحظر م ازولة المهنة.
• صندوق حماية المستثمر من المخاطر غير التجارية لنشطة الشركات العاملة في مجال الوارق المالية
يعد صندوق حماية المستثمر نقلة هامة في مجال األسواق المالية، إذ يقوم بدور محوري يكمن في تعويض
المتعاملين عن األض ارر غير التجارية "كإفالس الشركات" بما يرمي إلى وضع مظلة تبعث على طمأنينة
المتعاملين، بشأن ضمان وجود آلية سريعة وعادلة تعمل على ضمان استم اررية واستق ارر السوق .
•
بورصة العقود اآلجلة
ب ا مستقالً ينظم دور بورصة العقود اآلجلة لألوارق المالية
ً
وفًق ا للتعديالت األخيرة، أفرد قانون سوق أرس المال با
والسلع، وينظم التعامل على العقود المستقبلية وعقود الخيا ارت والمبادلة، فضالً عن تنظيم األجهزة والشركات
الالزمة لتسيير عملها، باإلضافة لوحدة اإلش ارف والرقابة على المخازن المعتمدة للسلع. كما أجاز القانون
للبورصة المصرية تأسيس شركة مساهمة لم ازولة نشاط بورصات العقود اآلجلة، أو م ازولة هذا النشاط بنفسها
إذا كانت العقود تتعلق باألوارق المالية المقيدة في البورصة.
01

ويتداول داخل بورصة العقود اآلجلة، العقود المرتبطة بش ارء كميات محددة من السلع أو األدوات المالية بسعر
محدد مع تحديد التسليم في وقت محدد في المستقبل؛ ويتم تسعير هذه العقود حسب حركة األصل الرئيسي
(السهم، السلعة األساسية المادية.. الخ). ويطلق على الفئة المذكورة أعاله اسم "المشتقات" ألن قيمة هذه العقود
تكون مشتقة من فئة أصول أخرى.
• اال تحاد المصري لألوارق المالية
استحدث القانون إنشاء االتحاد المصري لألوارق المالية، وعهد إليه بتقديم التوصيات بشأن تنمية نشاط سوق
أرس المال، وتوسيع قاعدة العمالء المسجلين فى بورصات األوارق المالية، ورفع كفاءة أداء كافة الجهات التي
تمارس هذا النشاط، وكذا وضع وتنفيذ ميثاق شرف للشركات العاملة في المجال.
ه. ترسيخ آليات حماية حقوق القلية
ع نى القانون بوضع العديد من األحكام التي تكفل حماية حقوق األقلية، إذ تضمن النص على أحقية المساهمين
َ
المالكين لنسبة 5% في طلب وقف ق ارارت الجمعية العامة للشركات التي تصدر لصالح فئة معينة من المساهمين
أو لإلض ارر بهم، ونظم عروض الش ارء واالستحواذ على األوارق المالية استهداًف ا لحماية حقوق األقلية.
وتتعدد آليات حماية حقوق األقلية وفًقا ألحكام القانون، ومنها النص على وجود جماعة حملة الصكوك،
والسندات.. الخ، والتي تعمل على تحقيق حماية المصالح المشتركة لحملة أ ي من األدوات أو األوارق المالية
المعنية بها، وال يجوز لها أن تتخذ أية إج ارءات من شأنها زيادة أعباء أعضائها أو عدم المساواة بينهم.
وبهدف تعزيز حماية األقلية، أصدر مجلس إدارة الهيئة الق ارر رقم 451 لسنة 8102، حيث ألزم الشركات المقيد
لها أوارق مالية ببورصة األوارق المالية بأن يتضمن نظامها األساسي النص على استخدام نظام التصويت
الت اركمي في انتخاب أعضاء مجلس اإلدارة، بما يسمح بالتمثيل النسبي ل أرس المال في عضوية مجلس اإلدارة
كلما أمكن ذلك.
و. آليات لحل المنازعات
وضع التشريع العديد من الوسائل البديلة لحل المنازعات المتعلقة بنشاط سوق أرس المال قبل اللجوء إلى القضاء،
وتتنوع هذه الطرق بين (تقديم الشكاوى، والتظلم من الق ارارت اإلدارية)، فضالً عن التحكيم كأحد الوسائل الناجزة
والمستقلة، والمنصوص عليه في القانون رقم 01 لسنة 9002، والتي تعمل الهيئة على تفعيل العمل بمقتضاه.
11

ز. ضمان التازم الشركات بأحكام القانون وتوقيع العقوبات
إحكام ا لد ور الهيئة الرقابي واإلش ارفي، فقد خصص القانون الباب ال اربع لبيان الدور واالختصاصات التي تضطلع
ً
الهيئة بالقيام بها، ومن أهمها م ارقبة األسواق للتأكد من أن التعامل يج ري على أوارق وأدوات مالية سليمة، وأنه
غير مشوب بالغش أو المضاربات الوهمية، وإج ارء التفتيش على الشركات الخاضعة ألحكام القانون .. إلخ.
وأناط القانون بالهيئة اتخاذ اإلج ارءات والتدابير حيال الشركات المخالفة ألحكام القانون ، والتي تتدرج ابتداء من
ً
توجيه تنبيه للشركات وحل مجلس اإلدارة ووقف النشاط، انتهاء بمنع الشركات من م ازولة كل أو بعض األنشطة
ً
التي رخص لها بم ازولتها.
ّ
رمة
ّ
ن ا بالعقوبات التي توّقع على من يخالف أحكام القانون ويرتكب األفعال المج
ً
كما أفرد القانون في بابه السادس بيا
بمقتضاه، وذلك بين الحبس والغ ارمة، ومعاقبة المدير الفعلي متى ثبت علمه بها.
وفي حكم هام يعزز من ضمان حقوق األقلية، نص القانون على معاقبة كل من استحوذ على أدوات مالية دون
تقديم عرض ش ارء إجبارى في الحاالت التي تستوجب ذلك، بغ ارمة ال تقل عن مائة ألف جنيه، وحظر القانون
التصالح إال بعد تقديم عرض الش ارء اإلجبارى.
21

2. القوانين الحاكمة لنشطة شركات التأمين وإعادة التأمين وأنشطة صناديق التأمين الخاصة:
أ. قانون رقم 01 لسنة 1891 والئحته التنفيذية لإلشارف والرقابة على التأمين
يأتي صدور القانون رقم 01 لسنة 1891 لإلش ارف والرقابة على التأمين والئحته التنفيذية، لتوفير األنظمة
التأمينية التي تناسب األف ارد والشركات؛ للتأمين على حياتهم وممتلكاتهم ومسئولياتهم، من خالل إيجاد إطار
قانوني وتنظيمي لحقوق والت ازمات كافة األط ارف المتعاملة داخل المنظومة التأمينية.
وتأتي أهمية القانون، فيما وضعه من العديد من األحكام التي ارعت – باإلضافة لما سبق- ضوابط واشت ارطات
الممارسة التأمينية واالستثما رية واإلدارية، وكذا معايير المالءة المالية لشركات التأمين، بما يحافظ على حقوق
حملة الوثائق والمستفيدين منها؛ بل ذهب القانون ألبعد من ذلك حينما اشترط - في مادته الثالثة واألربعين -
إنشاء صندوق لضمان حقوق حملة وثائق التأمين والمستفيدين منها لدى شركات التأمين، باإلضافة إلى تنظيم
األمور التالية:
• فروع التأمين التي يشملها القانون
عمل القانون على إيضاح أنواع األخطار التي يغطيها التأمين بكافة فروعه؛ لتندرج تحت تأمينات األشخاص
وعمليات تكوين األموال بكافة فروعها وهي: (تأمينات الحياة بجميع أنواعها، وتأمينات الحوادث الشخصية،
والعالج الطبي طويل األجل، وعمليات تكوين األموال)، وكذا تأمينات الممتلكات والمسئوليات بجميع فروعها:
(التأمين ضد أخطار الحريق، والتأمين ضد أخطار النقل الب ري والنه ري والبح ري والج وي ، وتأمينات المسئوليات
المتعلقة بها، والتأمين على أجسام السفن وآالتها ومهماتها وتأمينات المسئوليات المتعلقة بها، والتأمين على
أجسام الطائ ارت وآالتها ومهماتها وتأمينات المسئوليات المتعلقة بها، والتأمين على السيا ارت وتأمينات المسئوليات
المتعلقة بها، والتأمين الهندسي وتأمينات المسئوليات المتعلقة بها، وتأمينات البترول، فضالً عن التأمين ضد
أخطار الحوادث المتنوعة والمسئوليات، باإلضافة إلى التأمين الطبي قصير األجل).
ولضمان االنتشار السليم لوثائق التأمين بما يحقق الهدف المرجو من إصدارها، صدر ق ارر مجلس إدارة الهيئة
رقم 63 لسنة 3102، منظم ا نشاط تسويق منتجات شركات التأمين، واضع ا الشروط والمعايير والضوابط التي
ً ً
تكفل تواجد مكاتب لتسويق وثائق التأمين بالبنوك ومكاتب البريد، على نحو يحقق الشفافية ودقة األداء.
•
الجهات المسموح لها بمازولة أنشطة التأمين
حدد القانون الجهات المسموح لها بم ازولة أنشطة التأمين، وهي شركات التأمين وإعادة التأمين، فضالً عن
جمعيات التأمين التعاوني، وصناديق التأمين الحكومية.
ويقصد بالصناديق الحكومية للتأمين: الصناديق التى تتولى عمليات التأمين ضد األخطار التى ال تقبلها عادة
شركات التأمين، أو تلك التي ترى الحكومة م ازولتها بنفسها.
31

•
شروط ومتطلبات الترخيص
وضع القانون العديد من الشروط والض وابط لم ازولة أنشطة التأمين، محدد ا الشركات والجهات التي يجوز لها
ً
مباشرة تلك األنشطة، وقد روعي في هذا الشأن ما تقوم به من دو ر بارز في التوسع في التأمين ضد كافة
َ ّ
المخاطر، وما يستتبع ذلك من زيادة حجم وقيمة النشاط ووثائق التأمين.
ويعد أهم المتطلبات الالزمة لم ازولة النشاط، هو ضرورة الحصول على موافقة مبدئية من الهيئة قبل السير في
إج ارءات التأسيس، وأن تتخذ الش ركة شكل شركة مساهمة مصرية، واضع ا حد ا أدنى ل أرس المال.
ً ً
كما نظم الباب الثامن من القانون والسادس من الئحته التنفيذية مستندات وإج ارءات القيد بالسجل الذي تعده
الهيئة والترخيص لها بم ازولة النشاط، وتتمثل أبرز هذه المستندات في: نسخة معتمدة من النظام األساسى
للشركة، وشهادة من أحد البنوك تثبت قيام الشركة بإيداع األموال المتطلبة بالقانون عن كل فرع من فروع التأمين،
ونماذج الوثائق التي تصدرها الشركة، والم ازيا والقيود والشروط واألسعار الخاصة بهذه الوثائق، وشهادة من أحد
الخب ارء االكتواريين المقيدين لدى الهيئة بأن أسس أسعار هذه العمليات والم ازيا والقيود التي تخولها الوثائق سليمة
وصالحة للتنفيذ.
ويصدر بتسجيل الشركة والترخيص لها بم ازولة نشاطها ق ارر من رئيس الهيئة، وال يجوز للشركة أن تبدأ في
م ازولة أعمالها إال بعد تسجيلها والترخيص لها بم ازولة النشاط.
وإد ارك ا من المشرع أن الكفاءة والمالءة المالية للشركات يجب أن تصاح ب بكفاءة ون ازهة لدى العاملين والمسئولين
ً َ
بها، لذا فقد تطلب القانون أن يضم مجلس إدارة الشركة عضوين من ذ وي الخبرة في مجال التأمين، وأن يكون
المدير المسئول عن كل عمليات االكتتاب والتعويضات وإعادة التأمين واالستثمار من ذ وي الخبرة في مجال
التأمين وإعادة التأمين واالستثمار حسب األحوال، كما ألزم الشركة بإبالغ الهيئة بأي تعيين ألعضاء مجلس
اإلدارة، وأجاز للهيئة االعت ارض على ترشيح أي منهم بناء على أسباب جدية دون اإلخالل بأحقية صاحب
ً
الشأن في التظلم من ق ارر الهيئة.
فضالً عما تطلبه القانون فيمن يؤسس أو يدير الشركات، من عدم صدور أي أحكام ضده بعقوبة مقيدة للحرية
في جريمة تمس األمانة أو الشرف، أو أن يكون قد ح كم بإفالسه، ما لم يكن قد ر د إليه اعتباره.
ومن قبيل الشفافية في التعامل، ألزم القانون الشركات أن تثبت فيما يصدر عنها من أوارق أنه مرخص لها
بم ازولة عمليات التأمين أو إعادة التأمين، ورقم وتاريخ تسجيلها في سجل الشركات بالهيئة.
كما تطلب القانون - من قبيل متطلبات االستم ار رية - أن تقوم الشركة بإخطار الهيئة بكل تعديل أو تغيير يط أر
على بيانات طلب التسجيل والترخيص بالم ازولة أو الوثائق والمستندات الم ارفقة له.
41

•
أموال شركات التأمين وإعادة التأمين والتازماتها
أوجب القانون على الشركات بتكوين المخصصات الفنية الالزمة لمقابلة الت ازماتها ق بل حملة الوثائق والمستفيدين
منها، بأن ألزم شركات تأمينات األشخاص وتكوين األموال بتكوين "احتياطي حسابي" للوثائق السارية، ومخصص
"المطالبات تحت التسديد" بقيمة المطالبات التي لم يتم تسويتها حتى تاريخ إعداد القوائم المالية.
وبالنسبة لتأمينات الممتلكات والمسئوليات، فقد ألزم القانون الشركات بتكوين مخصص "األخطار السارية" حيث
يتم تكوينه لمقابلة الت ازمات الشركة عن عمليات التأمين المصدرة قبل انتهاء السنة المالية وما ازلت سارية بعد
انتهائها، وحدد لها نسب ا على النحو الوارد بالقانون والئحته التنفيذية.
ً
كما ألزم القانون الشركات بتكوين مخصص التع ويضات تحت التسوية عن الحوادث التي تم اإلبالغ عنها،
ومخصص لمقابلة حوادث وقعت ولم يبلغ عنها، فضالً عن مخصص للتقلبات العكسية كضمانة إضافية لحقوق
حملة الوثائق والمستفيدين منها. وقد نص القانون على امتياز تلك المخصصات، بحيث ال يجوز الحجز عليها
إال بعد الرجوع على أموال الشركة األخرى.
•
السجالت التي يتعين على الشركات إمساكها
أوجب القانون على كل شركة تأمين أن تمسك السجالت المتعلقة بكل فرع من فروع التأمين التي تباشرها، ومن
أهم تلك السجالت: سجل الوثائق التي تبرمها الشركة، وسجل التعويضات، وسجل الوسطاء بما فيها أسما ؤهم
وبياناتهم وأرقام تسجيلهم في سجل الوسطاء بالهيئة، وسجالت األموال المخصصة.
كما ألزم القانون الشركات بإمساك حسابات خاصة لكل فرع، وأن تشتمل على البيانات التي توضح مركزها المالي،
وأهمها: القوائم المالية، وحساب األرباح والخسائر، فضالً عن تقديم تقارير ربع سنوية عن نشاطها ونتائج أعمالها.
وشدد القانون والق ارارت الصادرة نفاًذا له على أن يتولى م ارجعة حسابات الشركة م ارقب حسابات من بين المقيدين
بسجالت الهيئة، وااللت ازم في أداء مهامهم بمعايير الم ارجعة المصرية.
ومن ذات المنطلق السابق، أوجب القانون على الشركات أن تقدم تقري ار من خبير اكتوا ري من بين المقيدين في
ً
سجالت الهيئة، لتوضيح ما إذا كان تقدير المخصصات الفنية واالحتياطيات الحسابية تم استناد ا إلى األسس
ً
الفنية المعتمدة من الهيئة، ومدى كفايتها لمقابلة حقوق حملة الوثائق والمستفيدين منها.
•
قواعد وضوابط تعامل شركات التأمين وإعادة التأمين
أفرد المشرع فصالً مستقال ً من الالئحة التنفيذية تناول فيه قواعد وضوابط تعامل شركات التأمين وإعادة التأمين،
سواء فيما بينها أو فيما بينها وعمالئها، وكذا المتعامل ون المرتقب ون، حيث ألزم الشركات بتجنب كل ما من شأنه
أن يؤدي إلى ظهور نمط احتكا ري .
51

كما وضع شرو ًط ا لإلعالن الصادر عن الشركات، بأن يتصف بدايًة بالصدق في شكله ومضمونه، كإظهار
البيانات بطريقة صحيحة وواضحة بوثائق التأمين.
كما أوجب االبتعاد عن المبالغة في مز ية تتعدى شروط الوثيقة أو إصدار بيانات مضللة.
وقد ألزم المشرع الشركات باالحتفاظ بملف كامل لجميع اإلعالنات التي قامت بإصدارها لفترة ال تقل عن خمس
سنوات، بجانب إل ازمها بمبادئ األمانة والحرص على مصالح العمالء. وحظر التمييز بين العمالء في خصوص
َ
أسعار الوثائق أو شروطها أو م ازياها بسبب اللغة أو الدين أو الجنس أو الحالة االجتماعية، إال إذا كان ذلك
مبنيا على أسس اكتوارية أو فنية.
ً
كما حظر رفض شركة التأمين تجديد الوثيقة، ما لم يكن ذلك تطبيًق ا ألسس اكتوارية تتعلق بالخسائر المتوقعة
أو لسبب إخالل المؤمن لهم بالت ازماتهم.
وفي إطار السعي وارء التسعير العادل لوثائق التأمين، ألزم القانون الشركات بم ارعاة األسس الفنية السليمة عند
تسعير الوثائق؛ ومن جانب آخر حظر التدني في األسعار إلى الحد الذي يضر بصناعة التأمين بقصد الحصول
على العمليات.
كما تضمن القانون الضوابط الحاكمة لتعامل الشركات مع عمالئها حال وقوع الخطر للمؤمن له، أبرزها وجوب
قيام المؤمن له أو المستفيد بأن يخطر جهة التأمين، ويعقبه بطلب للتعويض، ويكون على شركة التأمين في
هذه الحالة - وبناء على د ارسة - أن تؤدي له التع ويض العادل، أو أن ترفض ذلك بق ارر مسبب.
ً
•
تحويل وثائق التأمين
عمل القانون على تنظيم عملية تحويل وثائق التأمين من شركة إلى أخرى، س واء كان ذلك ناتج ا عن وقف نشاط
ً
الشركة لمخالفتها ألحكام القان ون، أم كان بسبب رغبتها في عدم االستم ارر؛ إذ أولى في هذا المقام اهتمامه
لضمان استم ارر واستق ارر السوق ؛ ولذا اشترط في هذا الشأن عدة أمور: أهمها أن تقدم الشركة للهيئة صورة من
عقد التحويل، وصورة من التقارير التى ب ني عليها العقد، وتقديم تقرير من أحد الخب ارء االكتواريين المقيدين في
َ
سجالت الهيئة، فضالً عن دعوة حملة الوثائق والمستفيدين منها وغيرهم من أصحاب الشأن إلى تقديم اعت ارضاتهم
إلى الهيئة، وللهيئة رفض الطلب إذا تبين أنه يضر بمصلحة حملة الوثائق والمستفيدين منها.
61

• الجهزة والمهن ذات الصلة بسوق التأمين
لم تقتصر أحكام القانون على تنظيم مهام الشركات والجهات الم ازولة ألنشطة التأمين؛ بل تضمنت تنظيم ا بشأن
ً
األعمال المهنية األخرى، والتي أوجب االستعانة بها في مواطن كثيرة من أحكامه، كاألجهزة المعاونة، والتي تهدف
إلى العمل على تقليل الخسائر، وكذا خب ارء التأمين االستشاريين الممارسين ألعمال الخبرة االستشارية في مجال
التأمين، وعلى األخص إدارة وتقييم األخطار وتقييم حقوق والت ازمات المؤمن لهم كأساس للتحكيم في المنازعات
الخاصة، فضالً عن خب ارء المعاينة وتقدير األض ارر، وكذا وسيط التأمين والذي يتولى ترويج وعقد عمليات التأمين
أو إعادة التأمين لحساب تلك الشركات مقابل مرتب أو مكافأة أو عمولة. وقد تطلب القانون في ك ل من هذه المهن
العديد من متطلبات الكفاءة والمهنية والحصول على ترخيص مسبق من الهيئة قبل م ازولة المهنة.
كما تطلب في جميع ما سبق، القيد والتسجيل لدى سجالت الهيئة، مشدد ا على الشركات بعدم االستعانة سوى
ً
بهؤالء المقيدين بالسجالت المشار إليها، موجب ا على تلك المهن االلت ازم بقواعد السلوك المهني وعدم اإلساءة إلى
ً
غيرهم، واإلفصاح في حالة تعارض المصالح مع العمالء ..الخ.
• االتحاد المصرى للتأمين
تأسس في جمهورية مصر العربية عام 7791 كاتحاد لشركات التأمين وإعادة التأمين وجمعيات التأمين التعاوني
المرخص لها بالعمل في مصر، وال يهدف االتحاد للربح، وله شخصية اعتبارية مستقلة.
ويعمل االتحاد على رفع صناعة التأمين والمهن التأمينية المرتبطة بها وتحديثهما، وترسيخ مفاهيم وأع ارف العمل
التأميني الصحيح والتنسيق فى المسائل المشتركة لتنظيم المنافسة ومنع التضارب، وتسوية المنازعات بين
األعضاء في مناخ اقتصاد السوق ، وتوثيق التعاون والتنسيق بين االتحاد والهيئة العامة للرقابة المالية بما يحقق
صالح س وق التأمين واالقتصاد القومي، وتوثيق الصالت بين االتحاد وسائر الهيئات واألجهزة الحكومية وغير
الحكومية المعنية بنشاط التأمين في مصر والخارج.
• حماية خاصة لحملة وثائق التأمين (صندوق ضمان حملة الوثائق والمستفيدين منها)
وافق مجلس إدارة الهيئة على مشروع ق ارر رئيس مجلس الوزارء بالنظام األساسي لصندوق ضمان حملة الوثائق
والمستفيدين منها، تفعيالً لنص المادة 34 من القانون رقم 01 لسنة 1891، بشأن اإلش ارف والرقابة على التأمين
في مصر، واضع ا في االعتبار أن الصندوق سيسهم في ضمان حق وق حملة الوثائق والمستفيدين منها لدى
ً
شركات التأمين.
وقد تمثلت أهم مالمح الصندوق في: استقالليته المالية واإلدارية عن شركات التأمين، وخضوعه إلش ارف ورقابة
الهيئة العامة للرقابة المالية، وتعزيزه لمفهوم الحماية والضمانة الشاملة لحقوق حملة الوثائق والمستفيدين منها
حال تعثر أو شطب شركات التأمين المتعاملين معه. كما تضمن مشروع النظام األساسي تنظيم ا إلمساك
ً
السجالت أهمها، الفصل التام بين حسابات التأمينات على الحياة، والتأمينات على الممتلكات.
71

•
آليات لحل المنازعات المتعلقة بنشاط التأمين
نظم التشريع العديد من الوسائل البديلة لحل المنازعات المتعلقة بنشاط التأمين قبل اللجوء للطرق القضائية
التقليدية، وتتنوع هذه الطرق بين: (تقديم الشكاوى، والتظلم من الق ارارت اإلدارية)؛ إذ وضع نظام ا يضمن المعالجة
ً
الفعالة للشكاوى، بأن ألزم الشركات بتوفير ملفات لفحص أي شكاوى ترد إليها، والفصل فيها خالل ثالثين يوم ا،
ّ ً
وإخطار الهيئة بما يتنهي إليه ال أري، باإلضافة إلى أحقية العمالء في التظلم من ق ارارت الشركة بالتقدم بشكواهم
إلى الهيئة للفصل فيها، وكذا التظلم من ق ارارت الهيئة عن طريق لجنة فض المنازعات، والتي تتضمن في
تشكيلها أعضاء مستقلين من خارج الهيئة والشركات.
ً
فضالً عن النص على التحكيم كأحد الوسائل الناجزة والمستقلة والمنصوص عليه في القانون رقم 01 لسنة
9002، والتي تعمل الهيئة على تفعيل العمل بمقتضاه.
• ضمان التازم شركات التأمين بأحكام القانون وتوقيع التدابير والعقوبات
إحكام ا لدور الهيئة الرقابي واإلش ارفي، فقد أفرد القانون فصوالً مستقلة، تناول فيها شطب التسجيل وإلغاء الترخيص
ً
بم ازولة النشاط حال وقوع مخالفات جسيمة تضر بمصالح حملة وثائق التأمين، وشمل ذلك المالءة المالية
للشركات والمهن األخ رى ذات الصلة. كما خصص الباب ال اربع عشر بشأن العقوبات التي توّقع على أ ي ممن
يخالف أحكام القانون ويرتكب األفعال المجرمة به، وذلك بين الحبس والغ ارمة.
