ب. القانون رقم 45 لسنة 5791 الحاكم لنشاط صناديق التأمين الخاصة
يسري على صناديق التأمين الخاصة أحكام القانون رقم 45 لسنة 5791، ويقصد بتلك الصناديق: كل نظام في
أي كيان مكون من أف ار د طبيعيين تربطهم أي صلة (اجتماعية/ مهنية/ أوغي رها) يتكون بغير أرسمال، ويمول
ّ
باشت اركات أو موارد أخرى من الجهة المنشأ بها الصندوق، بغرض أن يؤدي أو يرتب ألعضائه أو المستفيدين
منه حقوًق ا تأمينية في شكل تع ويضات أو معاشات دورية أو م ازيا مالية محددة.
ويكون الغرض منها وفًق ا لنظمها الساسية أن تؤدي إلى أعضائها أو المستفيدين منها تعويضات أو مازيا مالية
أو مرتبات دورية ومعاشات محددة، وذلك في إحدى الحاالت اآلتية:
•
زواج العضو وذريته أو بلوغه سن ا معينة أو وفاة العضو أو من يعوله.
ً
• التقاعد عن العمل أو ضياع مورد الرزق.
•
عدم القدرة على العمل بسبب المرض أو الحوادث.
•
أية أغ ارض أخرى توافق عليها الهيئة العامة للرقابة المالية.
وتخضع صناديق التأمين الخاصة إلشارف ورقابة الهيئة فيما يلي (وذلك على سبيل الحصر(:
• عند التسجيل وإنشاء كيان الصندوق ، وكذا عند تعديل األنظمة األساسية لها.
•
أثناء الم ازولة أو ممارسة األعمال لتلك الصناديق من خالل الفحص الدو ري لها.
•
عند إنهاء نشاط تلك الصناديق (وذلك عند التصفية سواء االختيا رية أو الوجوبية أو دمج تلك الصناديق)،
وذلك بغرض كفالة سالمة م اركزها المالية، وقدرتها على الوفاء بالت ازماتها، وحماية حقوق ومكتسبات
األعضاء والمستفيدين، والتأكد من االلت ازم بأحكام القانون والئحته التنفيذية.
91

وفي عام 5102 أصدرت الهيئة عدة ق ارارت من أهمها القــ ارر رقــم (101) لـســــنـة 5102 بشأن حوكمة صناديق
التأمين الخاصة، والذي جاء في ضوء التطوارت التشريعية على مست وى العالم في مجال حوكمة صناديق التأمين
الخاصة والتي لم تكن معنية فقط بمجلس اإلدارة أو الجمعية العامة، وإنما كانت معنية أيض ا بتعديل نظام االشت اركات
ً
لتغطية العدد األكبر للمنتفعين وتطوير سياسات االستثمار للمحافظة على قيمة أصول الصناديق، وخلق وابتكار أدوات
مالية جديدة تساهم في تعظيم ث روة األعضاء المنتفعين من الصندوق ، ومعالجة بعض نواحي القصور والسلبيات في
ممارسة سلطات اإلدارة الرشيدة ببعض الصناديق؛ نظ ار لعدم توافر الخب ارت واألساليب المهنية لرفع مستوى وكفاءة
ً
اإلدارة بهذه الصناديق.
وقد صدر ق ارر مجلس إدارة الهيئة المذكور متضمن ا "دليل حوكمة صناديق التأمين الخاصة".
ً
كما تحرص الهيئة على متابعة تطبيق قواعد حوكمة صناديق التأمين الخاصة وضوابط استثمار أموالها؛ حماية لحقوق
ومكتسبات األعضاء والمستفيدين.
وتجدر اإلشارة إلى أن الهيئة تعكف حالي ا على إعداد قانون شامل للتأمين ينظم أنشطة شركات التأمين ونشاط
ً ُ
التأمين التكافلي والرعاية الصحية وصناديق التأمين الخاصة والحكومية.
