3. قانون التمويل العقاري رقم 841 لسنة 1002 والئحته التنفيذية:
يعد التمويل العقاري أحد اآلليات البارزة إلتاحة التمويل بغرض توفير مسكن مناسب بنظام دفع ميسر يتناسب مع معدل
دخل العميل، في مقابل تقديمه لضمان يختلف بحسب طبيعة العملية التي يتطلبها (سكن/ أغارض اقتصادية/ ترميم/ بناء).
وفي هذا اإلطار، صدر قانون التمويل العقاري رقم 841 لسنة 1002 منظم ا كافة المسائل واألمور المتعلقة بالتمويل
ً
العقاري، ابتداء من إيضاح أنشطة التمويل العقاري التي يسري عليها القانون، مرو ار بتحديد الجهات التي يجوز لها
ً ً
م ازولة تلك األنشطة، والضوابط والقواعد الواجب توافرها في تلك الجهات وعامليها وخب ارئها الداخليين، والكفاءة والخبرة
الواجب توافرهما في القائمين على إدارة النشاط بتلك الجهات، واضع ا تنظيم ا متكامالً للمهن الحرة األخرى .
ً ً
وقد نظم القانون والئحته التنفيذية الشروط الواجب توافرها في مهني ي التمويل العقاري (وسطاء تمويل عقاري/خب ارء تمويل
ّ
عقاري/وكالء تمويل عقاري) والالزمة إلتمام عمليات التمويل العقاري، كخب ارء التقييم وفًق ا لمعايير التقييم العقاري الصادرة
عن مجلس إدارة الهيئة، مبين ا القواعد والمعايير التي تتبع في هذا الشأن بغرض القيد في السجالت التي تعدها الهيئة
ً
لتلك المهن، موجب ا على كافة الجهات واألشخاص المعنية االلت ازم باالستعانة بهؤالء المهنيين المقيدة أسماؤهم لدى الهيئة.
ً
وتتويج ا لكافة األحكام المنظمة للتمويل العقاري، وترسيخ ا لمبدأ الشفافية واإلفصاح، حرص القانون على وضع العديد
ً ً
من صيغ ونماذج االتفاقات التي تغطي كافة األنشطة الخاضعة لمظلته؛ بهدف ضمان معرفة كل طرف بالبنود
الجوهرية وبيان ما له من حقوق وما يقابلها من الت ازمات، أبرزها، أحقية الممول السير في إج ارءات بيع العقار حال
إخالل المستفيد ببنود االتفاق، ولذا عنيت كافة النماذج ببيان األحوال التي يجوز فيها اتخاذ هذا اإلج ارء، والقائمين
على تقييم العقار قبل بيعه ... الخ.
ويهدف إحكام الرقابة على تلك الجهات والتأكد من مدى سالمة أدائها، شمل القانون العديد من اإلج ارءات والضوابط التي
تضمن متابعة الهيئة –على النحو األمثل- للوضع المالي للشركات ومدى جدارتها المالية، والتدابير التي يمكن اتخاذها
ضد الشركة حال مخالفتها ألي من أحكام القانون والعقوبات التي يمكن توقيعها، وتد رجها لتتناسب مع حجم الفعل المجرم.
ّ
وقد عمل القانون على تحقيق أهدافه، وتنظيم كافة المور السابقة من خالل المحاور اآلتية:
أ. أنشطة التمويل العقاري
عمل القانون على تحديد النشطة التي يسري عليها نطاقه وهي: تمويل ش ارء أو بناء أو ترميم أو تحسين العقا ارت
ألغ ارض السكن والوحدات اإلدارية والمنشآت الخدمية ومباني المحال المخصصة للنشاط التجاري، واإلجارة، وتمويل
ش ارء حق االنتفاع بالعقا ارت، وتمويل ش ارء العقا ارت بنظامي المشاركة والم اربحة، وإعادة التمويل العقاري، ومن خالل
تلك األنشطة كفل توسيع قاعدة عمالء التمويل العقاري ؛ حيث وضع صيغ ا للتمويل التي تتوافق مع أحكام الشريعة،
ً
وكذا أفرد نظام ا خاص ا بذوي الدخول المنخفضة، فضالً عن األنظمة األخرى، كما أوضح االستثناءات الضريبية
ً ً
والرسوم والمصاريف المساحية التي تتمتع بها اتفاقات التمويل العقاري، وقيد الضمان وتجديده وشطبه وحوالته.
كما شمل القانون تنظيم نشاط شركات إعادة التمويل العقاري لتوفير التمويل لتلك الشركات.
12

ب. الجهات القائمة على شئون التمويل العقاري
عهد القانون إلى صندوق ضمان ودعم نشاط التمويل العقاري القيام بالعديد من االختصاصات التي تخدم ذوي
َ
الدخول المنخفضة، ويأتي أهمها، سداد أقساط المتعثرين منهم وفًق ا للقواعد والنسب التي يحددها النظام األساسي
للصندوق في هذا الشأن. وفي هذا اإلطار خصص الباب السادس من القانون لبيان قواعد االستفادة من هذا
الصندوق، ومالمح إنشائه، والتي يأتي أبرزها في استقالليته المالية واإلدارية، وتبعيته للوزير المختص في هذا الشأن.
ج. الجهات المسموح لها بمازولة أنشطة التمويل العقاري
عمل القانون على تحديد الجهات المسموح لها -وفًق ا ألحكامه- بم ازولة أنشطة التمويل العقاري ، وتتمثل في األشخاص
االعتبارية العامة التي يدخل نشاط التمويل العقاري ضمن أغ ارضها، وشركات التمويل وإعادة التمويل العقاري.
كما ع ني القانون بوضع المتطلبات واألسس والمعايير المهنية والمالية بما يضمن استم ارر قدرة هذه المؤسسات على
َ
تقديم خدمات التمويل العقاري، لتكون أبرز هذه المتطلبات - فيما يتعلق باألشخاص االعتبارية - أن يكون نشاط
التمويل العقاري من ضمن األغ ارض الثابتة بسند إنشاء األشخاص االعتبارية، وأن يتوافر في المدير المسئول خبرة
ال تقل عن عشرة أعوام، إلى جانب تعهد الشخص االعتباري بتعيين م ارقبي الحسابات المقيدة أسما ؤهم لدى الهيئة.
فيما تطلب القانون في شركات التمويل وإعادة التمويل العديد من الضوابط، أهمها: أال يقل أرس مالها المصدر
عن 05 مليون جنيه، وال يقل أرس المال المدفوع عن الربع عند التأسيس شريطة استكماله خالل سنة.
وفيما يتعلق بشركات إعادة التمويل اشترط أال يقل أرس مالها المصدر عن 052 مليون جنيه، وال يقل أرس المال
المدفوع عن النصف عند التأسيس، وأن تلتزم الشركة خالل ثالث سنوات على األكثر من تاريخ تسجيلها بالسجل
التجاري باستكمال أرس مالها المدفوع.
كما تطلب العديد من االشت ارطات األخرى التي تتعلق بالكفاءة المهنية الواجب توافرها في العاملين والمديرين
بالشركة، كعدم صدور أية أحكام ضدهم، وتوافر الخبرة، واستقالل عضوين من أعضاء مجلس اإلدارة، وكذا
اشت ارطات تضمن قدرة الشركة المالية على الوفاء بالت ازماتها، كمساهمة األشخاص االعتبارية والمؤسسات المالية
وأال تقل نسبة األموال السائلة نقد ا وما في حكمها عن 01% من االلت ازمات الجارية.
ً
كما حظر القانون على الشركات التوقف عن نشاطها أو تصفية أصولها إال بعد الحصول على موافقة كتابية من
الهيئة على ذلك، مجي از للهيئة أن ترفض اإلج ارء ألسباب جدية تتعلق بمصالح المستثمرين وغيرها من االعتبا ارت
ً
األخرى.
22

د. ضوابط تعامل الجهات مع عمالئها
وضع القانون العديد من االلت ازمات على عاتق الجهات الم ازولة لنشاط التمويل العقاري، بما يضمن الكفاءة المهنية،
والحفاظ على المستندات واألوارق المالية، وخصوصية معلومات العمالء، والمعاملة العادلة، فضالً عن االلت ازم
بتوعية وحماية المستثمر، والتمويل المتناسب مع القدرة المالية للعمالء، تالفي ا لتعثر العمالء في الوفاء بالت ازماتهم
ً
المادية، ومن أخص هذه اال لتازمات ما يلي:
•
المحافظة على سرية بيانات العمالء وعدم إفشاء أية معلومات عنهم للغير، وااللت ازم بوضع الئحة داخلية
تتضمن نظام العمل بالشركة وآليات إدارة المخاطر والتعامل مع شكاوى العمالء.
•
توعية وحماية المستثمر، وإعماالً لهذا المبدأ فقد صدر ق ارر مجلس إدارة الهيئة رقم 111 لسنة 5102، ليلزم
الشركات بأن تكون إج ارءات التمويل واضحة على نحو يكفل للمستثمر مع رفة جميع حقوقه والت ازماته، بما
فيها مخاطر عدم السداد، وأن يتضمن اتفاق التمويل إق ارر المستثمر باطالعه على نموذج الشروط األساسية
للتمويل العقاري واستالمه نسخة من هذا النموذج، وكذا اإلفصاح عن كافة المصروفات والعموالت ومقابل
الخدمات التي يقدمها الممول للمستثمر، فضال ً عن إخطار المستثمر مرتين سنوي ا على األقل بجميع البيانات
ً
المتعلقة باتفاق التمويل وكذلك عند حدوث أي تعديل في هذه البيانات.
• كما اشترط القانون أن ُتقدر قيمة (العقار) بمعرفة خبارء التقييم العقاري المقيدة أسما ؤهم في الجداول التي
تعدها الهيئة لهذا الغرض، وأن يتضمن عمله وصًف ا للعقار وموقعه وحدوده ومساحته وتاريخ إنشائه.
فضالً عن االلت ازم في أداء مهامه بمعايير التقييم العقاري الصادرة عن مجلس إدارة الهيئة.
وحرص ا على ضمان معرفة أط ارف العملية التمويلية بحقوقهم والت ازماتهم، فقد أتاح القانون العديد من نماذج االتفاقات
ً
المدرج بها البنود الجوهرية، كتحديد العقار وثمنه، ومقدار المبلغ المعجل الذي يتم سداده من ثمن العقار، وعدد وقيمة
ّ
أقساط باقي الثمن، وقبول البائع حوالة حقوقه في أقساط الثمن والضمانات المرتبطة بها إلى الممول.
كما نظم القانون الحاالت التي يجوز فيها للعميل التصرف في العقار الضامن أو تأجيره أو تمكين الغير من األف ارد
بشغله، مشترًط ا في هذه الحاالت ضرورة إخطار الممول أوالً بذلك، كما أجاز للممول رفض الموافقة على تلك
اإلج ارءات حال ما إذا كانت هناك أسباب جدية تتعارض معها مصالح وحقوق الممول.
32

ه. المهن المتصلة بعملية التمويل العقاري
أوكل القانون لك ل من خبارء التقييم والوكالء والوسطاء العقاريين أعماال ً جوهرية تتصل بشكل مباشر بالعملية
التمويلية، سواء عند تقييم العقار لتحديد قيمته قبل إج ارء عملية التمويل (خبير التقييم)، أو المختص بمباشرة
إج ارءات بيع العقار بالم ازد العلني حال إخالل المستثمر بالسداد (الوكيل العقاري)، وأخي ار مهام (الوسيط العقاري)
ً
كمقدم لمشوارت فنية للمستثمر وتعريفه بمخاطر التمويل، ولذا فقد تطلب القانون في كل من يرغب في مباشرة
األعمال السابقة القيد بسجالت الهيئة، وكذا االلت ازم بالشروط التي وضعها القانون ومن أهمها، الحظر على خب ارء
التقييم أن يكون لديهم أية مصالح في تقييم العقا ارت، كأن يكون العقار (محل طلب التقييم) مملوك ا لهم أو ألقاربهم.
ً
و. اال تحاد المصري للتمويل العقاري
يختص االتحاد بتوحيد جهود شركات التمويل العقاري والتنسيق فيما بينها للنهوض بمجال التمويل العقاري، وله
على األخص، اقت ارح األسس الفنية االسترشادية الخاصة بإدارة عمليات التمويل العقاري وتقييم المخاطر، والدفاع
عن مصالح الجهات العاملة في نشاط التمويل العقاري، وإبداء ال أري في مشروعات القوانين واللوائح والق ارارت التي
تعرض عليه، ونشر اإلحصاءات والتحليالت دوري ا، وتبني مباد ارت التوعية، وعقد ورعاية الندوات، واقت ارح ميثاق
ً
شرف ألخالقيات المهنة.
ز. آليات لحل المنازعات
كما وضع التشريع العديد من الوسائل البديلة قبل اللجوء للقضاء لحل المنازعات المتعلقة بنشاط التمويل العقاري
قبل الطرق القضائية التقليدية، وتتنوع هذه الطرق بين (تقديم شكاوى ، والتظلم من الق ارارت اإلدارية)، فضالً عن
التحكيم كأحد الوسائل الناجزة والمستقلة والتي نص عليها القانون رقم 01 لسنة 9002، والتي تعمل الهيئة على
تفعيل العمل بمقتضاه.
ح. ضمان التازم شركات التمويل وإعادة التمويل العقا ري بأحكام القانون وتوقيع التدابير والعقوبات
إحكام ا لدور الهيئة الرقابي واإلش ارفي، فقد خصص القانون الباب السابع إلب ارز التدابير واإلج ارءات التي تختص
ً
الهيئة باتخاذها حيال المخالفين ألحكام القان ون، والتي تنقسم بدورها إلى شقين:
الول: تدابير تتخذ ضد الشركات،
وثانيهما: تدابير تتخذ ضد أ ي من م ازولي المهن الحرة (وكالء، وخب ارء، ووسطاء التمويل العقاري).
ّ
وتتميز هذه التدابير بتدرجها وتنوعها لتتناسب مع المخالفات المرتكبة، ومن أخصها، حل مجلس إدارة الشركة أو
تعيين مفوض إلدارتها، أو المنع من م ازولة كل أو بعض األنشطة، كما أن هناك وجه ا آخر لتلك التدابير، كإل ازم
ً َ
الشركة بزيادة أرس مالها المدفوع تحقيًق ا الستق ارر السوق وحماية المتعاملين به.
42

وفيما يتعلق بالمهن الحرة، فقد أجاز القانون للهيئة التدرج في اتخاذ التدابير، ابتداء من توجيه إنذار إل ازلة المخالفة،
ً
ثم وقف م ازولة النشاط، وانتهاء بالشطب من سجالت الهيئة.
رمة
ّ
ن ا بالعقوبات التي توّقع على من يخالف أحكام القانون ويرتكب األفعال المج
ً
كما أفرد القانون في بابه الثامن بيا
به، وذلك بين الحبس والغ ارمة، ومعاقبة المدير الفعلي متى ثبت علمه بها، وغيرها من العقوبات.
وفي حكم هام بشأن المسائل التي يجوز فيها الصلح، نص قانون التمويل العقاري على تطبيق أحكام القانون رقم
01 لسنة 9002 بشأن التصالح، والتي منحت الحق لرئيس الهيئة في التصالح عن الج ارئم المنصوص عليها في
القانون في أي حالة كانت عليها الدعوى ، ويترتب على التصالح انقضاء الدعوى الجنائية للجريمة التي تم التصالح
بشأنها ولو بعد صيرورة الحكم باتا.
ً
52

4. قانون تنظيم نشاطي التأجير التمويلي والتخصيم رقم 671 لسنة 8102:
يعد كل من نشاطي التأجير التمويلي والتخصيم - الصادر بتنظيمها القانون رقم 671 لسنة 8102 - من أدوات
ٌ
التمويل المالي غير المصرفي، ويهدفان إلى إتاحة التمويل للمشروعات االقتصادية، سواء كان ذلك من خالل توفير
التمويل الالزم لحصول تلك المشروعات على التمويل متوسط أو طويل األجل لتمويل حيازة األصول ال أرسمالية الالزمة
لم ازولة النشاط من خالل التأجير التمويلي، أو من خالل إتاحة تمويل أرس المال العامل لهذه المشروعات، من خالل
تخصيم الحقوق المالية قصيرة األجل.
وقد سمح القانون للشركات والجمعيات والمؤسسات األهلية المرخص لها بممارسة نشاط التمويل متناهي الصغر وفًق ا
ألحكام القانون 141 لسنة 4102 بتقديم خدمات التأجير التمويلي متناهي الصغر، جنب ا إلى جنب مع الشركات
ً
المخاطبة بأحكامه، وذلك وفًق ا للضوابط التى يحددها مجلس إدارة الهيئة. وقد انفرد نشاط التأجير التمويلي ببعض
الضوابط، التي تختلف عن نشاط التخصيم، نوضحهم تباع ا من خالل ما يلي:
ً
أ. التأجير التمويلي:
يقصد بنشاط التأجير التمويلي: قيام المؤجر بتمويل الحصول على األصول ال أرسمالية، من خالل عقود تستهدف
ّ
تأجي ار تمويلي ا ألنشطة اقتصادية إنتاجية أو خدمية تتضمن خيار تمّلك تلك األصول، وذلك في مقابل قيام المستأجر
ً ً
بسداد دفعات التأجير.
ويتميز هذا النشاط بتمكين المستأجر (سواء الشخص الطبيعي أو المعنوي) من حيازة استخدام األصول الالزمة
عوض ا عن امتالكها؛ للحصول على التمويل الالزم إلنجاز مشروعه دون الحاجة إلى استثمار جزء من أمواله في
ً
ش ارء تلك األصول أو اللجوء إلى التمويل المباشر من البنوك. ومن أهم سمات عقود التأجير التمويلي إتاحة خيار
امتالك المستأجر لألصل المؤجر في نهاية المدة.
وقد وضع القانون تنظيم ا كامالً لهذا النشاط تتمثل أهم مالمحه فيما يلي:
ً
•
أطارف عملية التأجير التمويلي والعقود المرتبطة بها
عمل القانون على إيضاح أط ارف عملية التأجير التمويلي، وهم: المؤجر، والمستأجر، والطارف الخرى كالمورد،
أو المقاول.
واستلزم القانون إلتمام عملية التأجير التمويلي ضرورة قيام األط ارف المعنية بإب ارم عقد لتلك العملية، يشتمل على
العديد من المسائل أهمها، البيانات التفصيلية ألط ارف العقد، والوصف الدقيق ألصل المال المؤجر، والغرض
المخصص الستخدامه، والقيمة اإليجا رية، ومدة العقد، فضالً عن حق المستأجر في خيار ش ارء األصل المؤجر
..الخ.
62

وأتاح القانون ألول مرة م ازولة نشاط التأجير التشغيلي وإمساك حسابات مستقلة لهذا النشاط، مع التأكيد على
خروجها عن نطاق التأجير التمويلي الخاضع إلش ارف ورقابة الهيئة، كما نظم القانون االلت ازمات الملقاة على عاتق
كل من طرفي العقد، محدد ا آليات حماية األصل المؤجر، وكيفية استخدامه وصيانته والتأمين عليه وتحديد المسئولية
ً
المدنية والجنائية لمستغل األصل المؤجر. ومن أهم ما تضمنه القانون السماح لمالكي األصول ببيعها إلى شركات
التأجير التمويلي شريطة إعادة استئجارها مرة أخرى ، ويطلق على هذه المعاملة التمويلية البيع مع إعادة التأجير.
•
أحكام ممارسة نشاط التأجير التمويلي
وضع القانون إطا ار شامالً لعمليات التأجير التمويلي، ابتداء من اشت ارطه أن يقيد المؤجر لدى السجالت التي
ً ً ّ
تعدها الهيئة في هذا الشأن، والعقود التي تبرم في هذا الشأن، ومرو ار باألحوال التي أجاز فيها القانون التنازل
ً
عن العقد سواء للمؤجر أو المستأجر، انتهاء ببيان األحوال التي ينقضي فيها عقد التأجير التمويلي، أبرزها حالة
الوفاة، مبين ا في هذا الخصوص كيفية الحصول على المستحقات المالية، وما يكون لعقد التأجير التمويلي المقيد
ً
لدى الهيئة من قوة السند التنفيذي.
وقد تضمن القانون العديد من اإلعفاءات الضريبية لتشجيع م ازولة نشاط التأجير التمويلي من أبرزها، إعفاء عقود
البيع بغرض إعادة االستئجار من ضريبة التصرفات العقارية أو ضريبة القيمة المضافة.
ب. التخصيم:
يعمل نشاط التخصيم على توفير التدفق النقدي ل أرس المال العامل الالزم للمشروعات، إلعادة استخدامه في
النشاط، وذلك بأن تقوم تلك المشروعات العاملة سواء في األسواق المحلية أو الدولية ببيع مستحقاتها المالية
اآلجلة قصيرة األجل في مقابل الحصول على التمويل الالزم لها؛ إلتاحة ما يزيد من دورة اإلنتاج لتمويل أرس
المال العامل والتشغيل للمشروعات.
وقد تناول الباب الثالث من مشروع القانون تنظيم نشاط التخصيم على حدة، ومحاور هذا التنظيم ما يلي:
•
أطارف عمليات التخصيم والعقود المنظمة لهذه التعامالت
ُ
وضع القانون تعاريف لكل من أط ارف عملية التخصيم، والتي يتضح من خاللها دور كل منهم في عمليات
التخصيم، وما ينعكس على وضع تلك األط ارف في العقود.
صم: هو كل جهة مرخص لها بممارسة نشاط التخصيم وفًق ا ألحكام القانون.
ّ
مخ
ُ
فال
كما أن هناك أط ارًف ا أخرى تتمثل في الدائن: وهو بائع السلع أو مقدم الخدمات التي ينشأ عنها حقوق مالية،
والمدين: وهو مشت ري السلع أو متلقي الخدمات.
أما عقد التخصيم: فهو عقد تمويلي نشأ بين المخصم والبائع، بمقتضاه يقوم المخصم بش ارء الحقوق المالية
الحالية والمستقبلية الناشئة عن بيع السلع وتقديم الخدمات وفًق ا ألحكام هذا القانون .
72

وعلى ضوء ذلك، يتم إب ارم عقد بين البائع والمخصم تنتقل بمقتضاه الحقوق المالية الخاصة بالبائع، منه إلى
ّ
المخصم، وفًق ا ألحكام القانون المدني، شريطة م ارعاة إخطار المدين بحوالة الحقوق على النحو المشار إليه، وأن
ّ
يقدم له ما يضمن صحة هذه الحوالة.
كما وضع القانون العديد من الضوابط الخاصة بالحق المبيع، وأهمها: أن يكون ناشئ ا عن معامالت تجارية
ً
مرتبطة بنشاط كل من البائع والمدين وليست ناشئة عن عمليات إق ارض نقدي، وأن يكون خالي ا من أي حقوق حالية
ً
يا، وفًقا للضوابط التي يضعها
ً
كا نهائ
ً
ء من األصل سمح القانون أن يكون المدين مستهل
ً
أومستقبلية للغير، واستثنا
مجلس إدارة الهيئة.
ومن أهم آليات التخصيم التي نظمها القانون ، التخصيم الدولي إل تاحة التمويل لنشطة التصدير من خالل
الحقوق المالية المستقبلية للمستورد في الخارج.
كما وضع القانون إطا ار كامالً للعقود والبيانات التي يجب أن تتضمنها أهمها، مدة سريان العقد وشروط تجديده
ً
وحاالت انقضائه، وقواعد تسوية الحسابات المرتبطة به، وكذا حق المخصم في الرجوع على البائع في حالة عدم
قيام المدين بالسداد، وقواعد تسوية المنازعات التي تنشأعن هذا العقد.
كما ألقى القانون بالعديد من االلت ازمات األخرى على عاتق البائع، أهمها اإلفصاح للمخصم بكل وضوح وأمانة
ّ
بما لديه من بيانات ومعلومات حول العمليات التي نشأت عنها ديونه وكافة البيانات المتعلقة بالحقوق المبيعة
وضماناتها، والمخاطر أو العقبات إن وجدت.
وأوضح القانون الحاالت التي يكون فيها للمخصم الحق في الرجوع على البائع، أهمها إذا كان امتناع المدين عن
ّ
الوفاء بالحقوق للمخصم ارجع ا إلى إخالل البائع فى الوفاء بالت ازماته، ما لم يتضمن العقد بين البائع والمخصم
ً ّ
عدم الحق في الرجوع على البائع، بما تعكسه قواعد القانون في هذا الشأن من الحث على سريان التعاقدات فيما
بين كافة األط ارف على نحو عادل وناجز.
ومن جهة أخرى، ولضمان حقوق المدين، أجاز القانون االتفاق على التأمين ضد مخاطر عدم السداد لدى أي
ي ا.
ً
من شركات التأمين أو الجهات التي تقبلها الهيئة، خاصًة أنه من الممكن أن يكون التخصيم دول
82

•
متطلبات الترخيص بنشاطي التأجير التمويلي والتخصيم
وضع القانون العديد من المتطلبات والشروط التي يجب أن تتوافر في الجهة طالبة م ازولة أحد النشاطين أو
كليهما، وذلك بأن تكون شركات مساهمة مصرية، وأال يقل أرسمالها المصدر والمدفوع عن عشرة ماليين جنيه
أو ما يعادلها بالعمالت األجنبية، وأن يقتصر غرضها على ممارسة أي من نشاطي التأجير التمويلي أو التخصيم
أو كليهما.
كما أجاز القانون إضافة أحد األنشطة التمويلية غير المصرفية األخرى بعد الحصول على موافقة الهيئة، مشترًط ا
العديد من الضوابط التي تضمن حسن سير العمل بالشركة وتحقيق الهدف من إنشائها، مثل وضع حد أدنى لمدة
الخبرة الالزمة في القائمين على الشركة، وأن تتناسب مؤهالتهم مع طبيعة الدور الذي يقومون به فى الشركة،
وتمتعهم بالسمعة الحسنة من خالل عدم صدور أحكام جنائية أو الحكم بشهر اإلفالس ألي منهم خالل الخمس
سنوات السابقة.
ونص القانون على أن تسجل كل من الشركات أو الجهات الم ازولة لتلك األنشطة في السجل المعد لهذا الغرض
بالهيئة، وال يجوز ألي من تلك الجهات م ازولة النشاط إال بعد القيد لدى الهيئة.
ومن أجل تعزيز الشمول المالي والمساهمة فى انتشار أدوات التمويل غير المصرفي ووصولها لشارئح المجتمع
المختلفة، سمح القانون للشركات والجمعيات والمؤسسات الهلية المرخص لها بممارسة نشاط التمويل متناهي
الصغر - وفًق ا لحكام القانون 141 لسنة 4102 - بتقديم خدمات التأجير التمويلي متناهي الصغر، في
ضوء الضوابط التى يحددها مجلس إدارة الهيئة.
•
اتحاد الشركات العاملة في مجالي التأجير التمويلي والتخصيم
تضمن القانون النص على إنشاء اتحاد للشركات العاملة في نشاط التأجير التمويلي وآخر لتلك العاملة في نشاط
التخصيم؛ إذ عهد إليه القانون بتقديم التوصيات بشأن تنمية النشاط الذي أنشئ من أجله، وزيادة الوعي، وتبني
المباد ارت الداعمة لتلك األنشطة، وإبداء ال أري بشأن التشريعات المنظمة لعمل الجهات المنضمة إليه.
وفي هذا اإلطار ألزم كافة الشركات العاملة في نشاط التأجير التمويلي أو التخصيم باالنضمام إلى االتحاد.
•
آليات لحل المنازعات
وضع التشريع العديد من الوسائل البديلة لحل المنازعات المتعلقة بنشاطي التأجير التمويلي والتخصيم، قبل اللجوء
للطرق القضائية التقليدية، وتتنوع هذه الطرق بين (تقديم الشكاوى ، والتظلم من الق ارارت اإلدارية)، فضالً عن
التحكيم كأحد الوسائل الناجزة والمستقلة والتي نص عليها القانون رقم 01 لسنة 9002، والتي تعمل الهيئة على
تفعيل العمل بمقتضاه.
92

• ضمان اال لتازم بأحكام القانون وتوقيع التدابير والعقوبات
وضع القانون إطا ار قانوني ا يعمل على ضمان الت ازم الشركات والجهات الم ازولة لنشاطي التأجير التمويلي والتخصيم
ً ً
بتطبيق أحكامه، بدء ا من وضع أحكام إل ازمية على الجهات، حتى ال تتعرض أل ي من التدابير أو العقوبات،
ً ّ
مرو ار بما أناط به الهيئة من العمل على التحقق من إنفاذ تلك القواعد، وصوالً لتوقيع الج ازءات في الحاالت التي
ً
حددها القانون ؛
إذ أفرد القانون الباب السادس منه لألحكام الخاصة بالرقابة وحماية المتعاملين، مؤكد ا على دور الهيئة في إج ارء
ً
التفتيش على كافة الجهات والشركات الم ازولة لألنشطة المشار إليها، فضالً عن اختصاص الهيئة في البت في
كافة الشكاوى التي ت قدم لها من المتعاملين، انتهاء بما للهيئة من سلطة في اتخاذ أ ي من التدابير التي تتناسب
ً
مع حجم المخالفة، وفي مقدمتها توجيه تنبيه إلى الشركة بإ ازلة المخالفة، أو المنع من م ازولة النشاط، وحل مجلس
إدارة الشركة، وإلغاء الترخيص...الخ.
أما الباب التال ى، فقد تضمن العقوبات التي يمكن أن توّقع على المخالفين ألحكام القانون والتي تت اروح بين الحبس
والغ ارمة، والحرمان من م ازولة المهنة، مخوالً رئيس الهيئة السلطة في تحريك الدعوى الجنائية والتصالح عنها.
03

5. قانون تنظيم التمويل متناهي الصغر رقم 141 لسنة 4102:
ي عد التمويل متناهي الصغر من أبرز اآلليات الرئيسية والفعالة في إتاحة التمويل والخدمات واألدوات المالية للمشروعات
والمنشآت متناهية الصغر؛ إذ يتيح وسائل تمويلية مختلفة ومتنوعة بما يسهم في مساعدتها على توسيع أو تطوير
األنشطة االقتصادية متناهية الصغر، فضالً عن الدور البارز لنشاط التمويل متناهي الصغر في الشمول المالي من
خالل إتاحة الخدمات المالية لفئات لم تكن تتعامل مع القطاع المالي من قبل.
وفي هذا السياق صدر القانون رقم 141 لسنة 4102 بشأن تنظيم التمويل متناهي الصغر؛ سعي ا وارء تحقيق الهيئة
ً
للشمول المالي؛ إذ يهدف إلى العمل على توسيع وزيادة قاعدة المساهمين في حجم االستثمار مما يلقي بصداه على
االقتصاد القومي، على نح و يتناسب مع قدرة هذه الفئات من جهة، ويؤمن للمنشآت الممولة حقوقها من جهة أخرى،
كما حدد الجهات الخاضعة إلش ارف ورقابة الهيئة.
وقد وضع القانون إطا ار عام ا منظم ا للنشاط، محيالً للهيئة إصدار الق ارارت المنظمة لكل األمور المتعلقة بالتمويل
ً ً ً
المتناهي الصغر على وجه التفصيل.
ومن خالل العرض التالي نلقي الضوء على محاور القانون:
أ. مجاالت التمويل متناهي الصغر والجهات التي يجوز لها مازولته
حدد القانون الجهات التي يجوز لها مازولة نشاط التمويل متناهي الصغر وفًق ا لحكامه، شريطة أن يتوافر فيها
بعض المتطلبات، أهمها: أن تتخذ شكل شركة مساهمة مصرية، وأن يقتصر نشاطها على م ازولة نشاط التمويل
متناهي الصغر والخدمات المرتبطة به، وتوافر الحد األدنى ل أرس المال، وإدارة المخاطر، ومتابعة عمليات التمويل
ونظام فحص شكاوى العمالء، وأن تتوافر الخبرة المناسبة وحسن السمعة في كل من أعضاء مجلس اإلدارة
والمسئولين عن التمويل والمخاطر، فضالً عن عدم صدور أي أحكام بعقوبة جناية أو جنحة في جريمة مخلة
بالشرف أو حكم بشهر اإلفالس ضد أي من أعضاء مجلس اإلدارة، ما لم يكن قد رد االعتبار إليه، وكذا أن يكون
للشركات م ارقب حسابات واحد على األقل من بين المقيدين بسجالت الهيئة لهذا الغرض.
كما أجاز القانون للجمعيات والمؤسسات األهلية م ازولة النشاط؛ شريطة أن يكون نظامها األساسي متضمن ا تقديم
ً
التمويل متناهي الصغر للغير. وقد أكد القانون على عدم سريان أحكامه على البنوك الخاضعة لرقابة البنك المركزي
المصري ، وجهاز تنمية المشروعات الصغيرة والمتوسطة ومتناهية الصغر (الصندوق االجتماعي للتنمية سابًقا).
13

وأناط القانون بالهيئة دون غيرها منح تارخيص مازولة النشاط، وحظر على الشركات في هذا الشأن أن تقوم
بتصفية أصولها أو التوقف عن النشاط إال بعد الحصول على موافقة الهيئة.
وفي إطار ضبط األسواق وضمان استق ارره وسالمة األداء، أجاز القانون للهيئة أن ت لزم الشركة بزيادة أرسمالها
وفًق ا لجدول زمني محدد.
أما فيما يتعلق بمجاالت النشاط، فقد صدر ق ارر مجلس إدارة الهيئة رقم 851 لسنة 4102 مؤكد ا على أن يقتصر
ً
تقديم التمويل على األغ ارض االقتصادية دون االستهالكية في المجاالت اإلنتاجية أو الخدمية أو التجارية الموّلدة
للدخل، وذلك كالمجاالت الزارعية واألنشطة المرتبطة بها، كتربية الحيوانات والطيور والم ازرع السمكية وصيد
األسماك، وأيضا المجاالت اإلنتاجية والصناعية والحرفية، وتشمل كافة مجاالت اإلنتاج والتصنيع في مجال
ً
المنسوجات والحياكة.. الخ، أما المجاالت الخدمية فتشمل أعمال المقاوالت والتشطيب والنقل والتعبئة والتخزين
والصيانة.. الخ.
ب. قواعد وضوابط تعامل الشركات والجمعيات والمؤسسات الهلية لنشاط التمويل متناهي الصغر
حرص ق ار ار مجلس إدارة الهيئة رقما (271) لسنة 4102، (13) لسنة 5102 على أن يتناوال بالتفصيل العديد
من األمور المتعلقة بم ازولة النشاط، ويأتي في مقدمتها متطلبات حوكمة جهة التمويل، ومنها وجود وحدة داخلية
تختص بالم ارجعة الداخلية، والضوابط المصاحبة إلعداد القوائم المالية الدورية السنوية والربع سنوية مع إخطار
الهيئة بها، فضالً عن قواعد منح التمويل للعمالء، وأبرزها عدم تمويل العميل تمويالً يفوق طاقته على السداد،
واالستعالم عن العمالء.
كما وضع الق ارر ضوابط تحكم العالقة التعاقدية فيما بين العمالء والشركات المانحة للتمويل، يتضمن مدة التمويل
ومبالغه، ومقابل التأخير، والضمانات التي يقدمها العميل إن وجدت ..الخ.
كما أفرد الق ارر تنظيم ا بشأن معالجة شكاوى العمالء، ابتداء من إل ازم الشركات بإنشاء سجل قيد شكاوى العمالء،
ً ً
والبيانات التي يجب تضمينها في هذا السجل من تاريخ ورقم القيد واسم مقدمها وما انتهى إليه ال أري، منتهي ا بإل ازم
ً
الشركات بفحص الشكاوى خالل فترة وجيزة ال تتعدى األسبوع.
وفي هذا المجال، وفي ظل الجهود المتواصلة من جانب الهيئة للعمل على تعزيز نشاط التمويل متناهي الصغر،
فقد قام مجلس إدارتها بإصدار الق ارر رقم 209 لسنة 6102، والذي أتاح توزيع وثائق التأمين متناهي الصغر في
فروع تأمينات الحياة، والحوادث الشخصية، والتأمين الطبي طويل األجل، والممتلكات في جميع فروع الشركات
والجمعيات والمؤسسات األهلية (فئتي أ، ب) المرخص لها بم ازولة نشاط التمويل متناهي الصغر، وفًق ا ألحكامه.
23

ج. وحدة الرقابة على نشاط التمويل متناهي الصغر للجمعيات والمؤسسات الهلية
أ نشئت بموجب أحكام القانون رقم 141 لسنة 4102 وحدة مستقلة بالهيئة للرقابة على نشاط التمويل متناهي
الصغر للجمعيات والمؤسسات األهلية، وتختص بتنظيم ورقابة ومتابعة نشاط التمويل متناهي الصغر، من حيث
متابعة أداء الجمعيات والمؤسسات األهلية، ووضع قواعد التفتيش والرقابة على تلك الجهات، فضالً عن التنسيق
مع الجهات المعنية بما يسهم في تطوير نشاط التمويل متناهي الصغر وإدارة المخاطر المرتبطة به والعمل على
تماثل قواعد وضوابط ممارسة النشاط بين الشركات والجمعيات والمؤسسات األهلية الممارسة للنشاط.
د. االتحاد المصري للتمويل متناهي الصغر
نص القانون في مادته رقم 81 على إنشاء االتحاد المصري للتمويل متناهي الصغر، وجعل له شخصية اعتبارية
مستقلة، وعهد إليه بتقديم التوصيات بشأن تنمية نشاط التمويل متناهي الصغر وزيادة الوعي به وتبني المباد ارت
الداعمة للنشاط، كما ألزم جميع الجهات العاملة في نشاط التمويل متناهي الصغر باالنضمام إلى االتحاد.
ه. آليات ودية ومرنة لحل المنازعات
وضع التشريع العديد من الوسائل الودية البديلة لحل المنازعات المتعلقة بنشاط التمويل متناهي الصغر، بخالف
الطرق القضائية التقليدية، وتتنوع هذه الوسائل بين (تقديم الشكاوى ، ولجان التظلم من الق ارارت اإلدارية)، فضالً
عن التحكيم كأحد الوسائل الناجزة والمستقلة والتي نص عليها القانون رقم 01 لسنة 9002، والتي تعمل الهيئة
على تفعيل العمل بمقتضاه.
و. ضمان اال لتازم بأحكام القانون وتوقيع التدابير والعقوبات
وضع القانون إطا ار قانوني ا يعمل على ضمان الت ازم الشركات والجهات الم ازولة بتطبيق أحكامه، بدء ا من وضع
ً ً ً
أحكام إل ازمية على الجهات، حتى ال تتعرض أل ي من التدابير أو العقوبات، مرو ار بما أناط به الهيئة من العمل
ً
على التحقق من إنفاذ تلك القواعد، وصوالً لتوقيع الج ازءات في الحاالت التي حددها القانون.
وقد حدد الق ار ارن سالفا البيان رقما 271 لسنة 4102، 13 لسنة 5102 العديد من المتطلبات التي يجب م ارعتها
من جانب الشركات والجهات، ومخاطبة الهيئة بشأنها بشكل دوري للتحقق من سالمة أدائها، كمعايير المالءة
المالية، وقواعد إعداد القوائم المالية، فضالً عن االلت ازم بما رسمته الق ار ارت من إج ارءات تتعلق بإخطار الهيئة حال
نقل أو غلق أو فتح فرع للشركة أو للجمعية والمؤسسة األهلية، وكذا حوالة المحافظ االئتمانية، موجب ا على كل
ً
شركة وجهة تحديد مسئول اتصال مع الهيئة.
33

وفي حال ما تبين للهيئة قيام الشركة أو الجهة بمخالفة أ ي من أحكام القانون والقارارت الصادرة تنفيًذ ا له،
يكون لها أن تتخذ العديد من التدابير التالية، ومنها: توجيه تنبيه إلى الشركة أو الجهة بإ ازلة المخالفة، أو المنع
من م ازولة كل أو بعض األنشطة المرخص بم ازولتها، أو حل مجلس إدارة الشركة، أو إصدار ق ارر بدمج الشركة
في شركة أخرى، أو إلغاء الترخيص ...الخ.
وإحكام ا لدور الهيئة الرقابي، أجاز القانون في المواد من (02 – 42) لرئيس الهيئة تحريك الدعوى الجنائية،
ً
بالنسبة للج ارئم التي تقع من الشركات أو الجمعيات أو المؤسسات األهلية التي ت ازول نشاط التمويل متناهي الصغر
بالمخالفة ألحكام القانون، ويعاقب مرتكبها بعقوبة بين الحبس والغ ارمة على النحو المقرر بمواد القانون.
43

ا
ثالث ا: أهمية إصدار دليل خاص حلماية املتعاملني
تسعى الهيئة العامة للرقابة المالية إلى تطوير مبادئ حماية المتعاملين في القطاع المالي غير المصرفي؛ بهدف
تعزيز مفهوم الشفافية واإلفصاح في المعامالت المالية، في إطار عالقة متوازنة توفر الحماية للمتعاملين في القطاع
المالي غير المصرفي، وحصول المتعاملين على معاملة عادلة بشفافية وصدق وأمانة، وكذلك حصولهم على المنتجات
والخدمات المالية بكل يسر وسهولة وبتكلفة مناسبة وجودة عالية.
وفي إطار المنهجية التي تتبعها الهيئة بشأن تكريس دورها الرقابي في مجال حماية حقوق المتعاملين، فقد أصدرت
الهيئة خالل السنوات الماضية العديد من التعليمات والق ارارت للقطاع المالي غير المصرفي تستهدف تعزيز مفهوم
الشفافية واإلفصاح في المعامالت المالية التي تقدمها المؤسسات المالية إلى مختلف العمالء، والعمل على توفير بيئة
مناسبة لحفظ حقوق العمالء في إطار عالقة متوازنة توفر الحماية للقطاع غير المصرفي، مع عدم تعريضه لمخاطر
السمعة التي تنشأ في حالة عدم الت ازم المؤسسات المالية بالضوابط والمبادئ المعنية بالحفاظ على سالمة واستق ارر
السوق ، من حيث المعاملة العادلة والشفافية والعمل على حل وتسوية الن ازعات وشكاوى المتعاملين بأسلوب منجز
وعادل وااللت ازم بضوابط السلوك المهني وحماية سرية وبيانات المتعاملين.
فقد أصدرت الهيئة أول دليل تفصيلى عن حماية المتعاملين في القطاع المالي غير المصرفي في السوق المصرى.
وفي إطار اإلعداد لهذا الدليل، قامت الهيئة باالطالع على أفضل الممارسات في العديد من الدول، كما تم االستعانة
أيض ا بأفضل الممارسات والمعايير الدولية الموضوعة في حماية المتعاملين من قبل المؤسسات المالية الدولية مثل
ً
DCEO وDATCNU وUE
وقد اعتمدت الهيئة عند إصدارها هذا الدليل بشكل أكثر على تقرير البنك الدولي knaB dlroW الصادر في 7102
بشأن أفضل الممارسات )secitcarP dooG( لحماية المتعاملين في القطاع المالي غير المصرفي.
وقد تم إعداد دليل حماية المتعاملين في القطاع المالي غير المصرفي بما يناسب ويتالءم مع اإلطار القانوني
والثقافي المصري، آخًذا في االعتبار التشريعات والقوانين الخاصة بالقطاع المالي غير المصرفي، واللوائح التنفيذية
والقارارت، باإلضافة إلى درجة نضوج السوق المصري ، سواء بالنسبة للمتعاملين الفارد أو المؤسسات المالية التي
تقدم الخدمات المالية، وتكاليف االمتثال، وتحديات اال لتازم.. الخ.
ومن المتوقع إصدار نسخ أخرى لدليل حماية المتعاملين في القطاع المالي غير المصرفي خالل السنوات القادمة،
مع تطور السوق والخدمات المالية المقدمة وزيادة وعي المتعاملين.
53

وتعتبر حماية المتعاملين أم ار مهم ا وأساسي ا؛ وذلك لضمان حصول المتعاملين على المعلومات الالزمة التي تتيح
ً ً ً
لهم اتخاذ ق ارارت مدروسة وعن بينة.
ويجب أن تكون المعلومات واضحة ومبسطة حتى يستطيع العمالء أن يفهموها، باإلضافة إلى أهمية أن يقوم مقدمو
الخدمات المالية بمعاملة المتعاملين معاملة عادلة وعدم القيام بأي ممارسات مضللة ألي من المتعاملين؛ لذا وجب أن
يتحلى مقدمو الخدمات المالية بالسلوك المهني المسئول واالحت ارفية قبل وأثناء وبعد تقديم وبيع الخدمات المالية، وأن
يكونوا مؤهلين وحاصلين على المؤهالت والشهادات الالزمة التي تمكنهم من أداء دورهم بكفاءة وتميز.
فضال ً عن ذلك، فإن من حق المتعاملين اللجوء إلى آليات للتظلم والشكاوى لتسوية النازعات، وكذلك وجود آليات
لحماية خصوصية وسرية معلومات المتعاملين الشخصية، وأيض ا وجود سبل لضمان حماية المتعاملين في حاالت
ً
إفالس مقدمي الخدمات المالية.
وتعتبر مجموعة المبادئ الواردة في هذا الدليل مكملًة وليست بديلًة لما أصدرته الهيئة من قارارت وقواعد مختلفة
في مجال حماية المتعاملين، وعلى المؤسسات المالية العمل على اتخاذ اإلجارءات الالزمة لتطبيق ما ورد في هذا
الدليل من مبادئ وضوابط. وإذا تعارض أي من المبادئ الواردة في هذا الدليل مع صريح القوانين، تكون الغلبة
للقوانين في التطبيق.
63

ا
رابع ا: املبادئ العامة حلماية املتعاملني يف القطاع املايل غري املصريف
المبدأ الول: اإلفصاح والشفافية
تلتزم المؤسسات المالية في مجال اإلفصاح والشفافية بالتالي:
أ. عرض المعلومات الخاصة بالمنتجات والخدمات المالية أو التمويلية بلغة سهلة وواضحة، متضمنة كافة
المفاهيم والشروط واألحكام األساسية مع عدم استخدام مصطلحات فنية غير واضحة أو غير ضرورية، وإذا
تم استخدام مصطلحات تقنية فيجب تفسيرها بطريقة واضحة.
ب. أن يكون حجم الخط وتباعد المسافات بين الحرف والكلمات واضحا ومقروءا بسهولة للشخص العادي.
ً ً
ج. أن يكون التواصل الشفوي - خالل مرحلتي ما قبل التعاقد والتعاقد في شرح الخصائص والممي ازت الرئيسية
للمنتجات والخدمات المالية أو التمويلية - بشكل واضح ومفهوم إل ازلة أي غموض؛ حتى يتمكن العمالء من
اتخاذ ق ارارتهم االستثما رية أو التمويلية.
د. تسليم العمالء نموذج البيانات الساسية والذي يتضمن المعلومات الرئيسية عن أنواع المنتجات والخدمات
المالية أو التمويلية، وإيضاح أهم المخاطر لتلك المنتجات والخدمات المالية أو التمويلية، وكافة العموالت
والمصاريف، وشرح آلية إنهاء العالقة مع العمالء وما يترتب عليها من آثار..الخ – وذلك في ملخص موجز
وشارح وأسلوب واضح.
ويصدر البيان في حدود صفحتين على األكثر لكل منتج أو خدمة مالية او تمويلية، ويجب أن يوقع العمالء
عليه بعد ق ارءة كافة بنوده.
ويتيح النموذج للعمالء سهولة إج ارء مقارنة بين عروض الشركات المختلفة في السوق الختيار أفضل منتج
وخدمة مالية أو تمويلية مالئمة الحتياجاتهم وقد ارتهم المالية.
ه. النص صارحة في عقود المنتجات والخدمات المالية أو التمويلية، وأيض ا اإلفصاح للعمالء على وج ود فترة
ً
(1)
سماح مدتها (عشرة أيام عمل) تبدأ من تاريخ تعاقد العمالء مع المؤسسات المالية، إذا لم يتم تقديم خدمات
مالية أو تمويلية لهم.
وطوال هذه الفترة يمكن للعمالء القيام بفسخ التعاقد واسترداد مستحقاتهم (إن وجدت) بدون توقيع أي شروط
ج ازئية عليهم. ويجوز للمؤسسات المالية خصم أي مصاريف إدارية تكبدتها إلصدار العقود بشرط أن تكون
المصاريف اإلدارية محددة القيمة ومبررة ومعلنة مسبًق ا للعمالء قبل التوقيع على العقود.
(1) تلتزم جهات التمويل متناهي الصغر بأال تقل الفترة عن ثالثة أيام عمل.
73

و. شرح آلية إنهاء العالقة مع العمالء وما يترتب عليها من حقوق ومسئوليات والتازمات واقعة على العمالء،
وإيضاح سبل التعويض، وكذا شرح الج ازءات المطبقة في حاالت فسخ التعاقد من جانب العمالء.
ز. شرح تفاصيل السعار والعموالت والرسوم والعوائد للمنتجات والخدمات المالية أو التمويلية المقدمة وطرق
حساب تلك المؤش ارت.
ح. شرح أي تغييارت قد تطأر على الحكام أو الشروط الخاصة بالمنتجات والخدمات المالية أو التمويلية والتوقيتات
المتوقعة لحدوثها.
ط. إخطار العمالء بأي تغييارت على الرسوم أو التكلفة المتوقعة على حساباتهم وإبالغهم بها بوقت كاف .
ي. م ارعاة أن تتسم المعلومات المعروضة عن المنتجات والخدمات المالية أو التمويلية - المتمثلة في الدعاية
وعروض البيع وجميع سبل الدعاية األخرى - بالدقة والمانة.
ويحظر على المؤسسات المالية عرض أي معلومات أو خصائص للمنتجات والخدمات المالية أو التمويلية
من شأنها تضليل العمالء أو خداعهم أو حذف بيانات مهمة.
ك. أن توفر لعمالئها كافة المعلومات والبيانات المتعلقة بالخدمات والمنتجات المالية أو التمويلية المقدمة
للمتعاملين من خالل كتيبات أو منشوارت أوما يوازيها إلكتروني ا، على أن يتم تدوين وإيضاح هذه المعلومات
ً
بمنتهى الشفافية والحيادية، وأن تتسم بالوضوح وسهولة الفهم والبساطة والدقة، بما يكفل اطالع المتعاملين
بمختلف مستوياتهم الثقافية والمادية عليها وتفهمهم للم ازيا والمخاطر المتوقعة.
ل. مارعاة تناسب النصائح المقدمة للعمالء مع قدارتهم وإمكانياتهم وخبارتهم وأهدافهم المالية فيما يخص
المنتجات والخدمات المالية أو التمويلية المقدمة إليهم، وأن تقدم المعلومات بالشكل الذي يسمح للعمالء بإج ارء
مقارنة بين المنتجات والخدمات المالية أو التمويلية المقدمة ومثيالتها في السوق .
م. أن ترسل لعمالئها كشوف حساب دورية كتابية أو إليكتروني ا، موضح ا بها العمليات المنفذة على حساباتهم
ً ً
عن الفترة المرسل عنها، باإلضافة إلى مصادقات كتابية أو إليكترونية عن العمليات التي تمت على حساباتهم.
وفي حالة عدم الرد أو االعت ارض من العمالء خالل خمسة عشر يوم ا من تاريخ االستالم تعتبر مصادقة
ً
على حساباتهم.
ن. أن تفصح كتابة في كافة العقود والمكاتبات مع العمالء عن خضوعها لرقابة الهيئة العامة للرقابة المالية،
مع توضيح رقم الترخيص والسجل التجاري ، وأيض ا اإلدا رة المختصة لديهم للتعامل مع شكاوى وتظلمات
ً
العمالء وكيفية التواصل المباشر معها عن طريق رقم هاتفى مخصص للشكاوى .
ويجب إحاطة العمالء كتابة عن حقهم في اللجوء إلى اإلدارة المختصة بالشكاوى بالهيئة إذا لم يقبلوا التسوية
المعروضة من قبل إدارة الشكاوى الخاصة بالمؤسسات المالية.
