المبدأ الثاني: السلوك والكفاءة المهنية
تلتزم المؤسسات المالية في مجال السلوك والكفاءة المهنية بالتالي:
أ. أن تحرص على ممارسة وأداء عملها بأسلوب مهني مسئول؛ لتحقيق أفضل مصلحة للعمالء في كافة م ارحل
تعاملهم مع المؤسسات المالية، باعتبارها مسئولة عن حماية العمالء فيما يقدم إليهم من منتجات وخدمات
مالية أو تمويلية. ويأتي على قمة هذه السلوكيات الن ازهة والمصداقية والتحقق من مناسبة المنتجات والخدمات
المالية أو التمويلية المقدمة للعمالء إلمكانياتهم وقد ارتهم واحتياجاتهم المالية.
ب. التأكد من توافر المؤهالت العلمية والكفاءات والمها ارت الالزمة، باإلضافة إلى التدريب المالئم والمستمر للعاملين
بالمؤسسات المالية الذين يتعاملون مع العمالء ويقدمون لهم المنتجات والخدمات المالية أو التمويلية. ويجب التأكد
من فهم وإلمام واستيعاب العاملين لدى المؤسسات المالية للمنتجات والخدمات المالية أو التمويلية المقدمة للعمالء.
ج. توفير المعلومات الالزمة بما يتيح للعمالء إج ارء مقارنة بين الخدمات والمنتجات المالية أو التمويلية المتاحة
في السوق.
د. أن تكون لديها سياسات مكتوبة وواضحة ومعتمدة من مجلس اإلدارة بشأن تعارض المصالح، والعمل بشكل مستمر
وفعال للتأكد من كفاية اإلجارءات المتبعة والسياسات المطبقة في كشف الحاالت المحتملة لتعارض المصالح.
ه. اإلفصاح عن أي حاالت تعارض للمصالح وفًق ا لما تحدده سياساتها الداخلية، وكذلك ما تفرضه الهيئة من
قواعد ونظم للحوكمة.
المبدأ الثالث: العدالة وعدم التمييز بين العمالء
تلتزم المؤسسات المالية في مجال العدالة وعدم التمييز بين العمالء بالتالي:
أ. حظر إد ارج أي مصطلحات غير منصفة أو مضللة في العقود المبرمة بينها وبين العمالء.
ب. م ارعاة أن تتسم تعامالتها بالعدل والمساواة واإلنصاف واألمانة خالل جميع م ارحل تعاملها مع العمالء، وأن
تحرص على جعل هذا المنهج جزء ا من قواعد الحوكمة لديها.
ً
ج. حظر القيام بأي ممارسات ضارة ضد عمالئها عند استيفاء الديون، أو عند استقطاب عمالء جدد، مثل تك ارر
االتصال واإللحاح على العمالء للتعاقد.
د. أن تعطي مزيد ا من الرعاية واالهتمام بالعمالء خصوص ا كبار السن وذوي االحتياجات الخاصة. ويجب على
ً ً
المؤسسات المالية أن تبذل العناية الكافية عند التعامل مع العمالء من محدودي الدخل والعلم ومساعدتهم
واالستجابة الستفسا ارتهم وأسئلتهم، وذلك دون تمييز بين الجنسين.
ه. أن تسهل عملية انتقال حسابات عمالئها - طبًق ا لرغبتهم - لشركات أخرى منافسة في السوق بدون تعطيل
أو تسويف، ويتم ذلك بعد استيفاء العمالء كافة اإلج ارءات المطلوبة لغلق حساباتهم لديها.
