المبدأ ال اربع: حماية سرية وخصوصية حسابات وبيانات العمالء
تلتزم المؤسسات المالية في مجال حماية سرية وخصوصية حسابات وبيانات العمالء بالتالي:
أ. وضع األنظمة الرقابية واآلليات والسياسات التي تكفل حماية المعلومات المالية والشخصية لعمالئها، والحفاظ على
سريتها وخصوصيتها وعدم االطالع عليها أو استغاللها إال على النحو الذي ينظمه القانون وتلك حاالت استثنائية.
ب. أن تحتفظ لديها بقاعدة بيانات للعمالء لمدة معينة تحددها الهيئة حسب كل نشاط.
ج. وضع النظم والتدابير الالزمة والتي تحدد كافة العاملين لديها الذين لهم حق االطالع فقط أو التعامل على
حسابات العمالء، بناء على اختصاصهم ودرجتهم الوظيفية.
ً
د. وضع أنظمة رقابية داخلية فعالة تتسم بالكفاءة والرقابة الدقيقة؛ بهدف الحد من عمليات االحتيال واالختالس
أو إساءة استخدام البيانات المالية. ويجب التأكد بشكل مستمر من كفاءة األنظمة المستخدمة لمواكبة التغيي ارت
في األساليب االحتيالية وكذا مواكبة التطور التكنولوجي.
المبدأ الخامس: تسوية الن ازعات ومعالجة شكاوى العمالء
تلتزم المؤسسات المالية في مجال تسوية النازعات ومعالجة شكاوى العمالء بالتالي:
أ. أن تخصص وحدة أو إدارة متخصصة للتعامل مع شكاوى العمالء لديها، وأن تحدد لها آلياتها واختصاصاتها،
وأن تعين بها موظفين متخصصين لفحص الشكاوى والتظلمات.
ب. أن تحدد مدة زمنية يتم خاللها فحص شكاوى العمالء واالنتهاء منها.
ج. أن تولي شكاوى وتظلمات العمالء العناية الالزمة، وأن يتم األداء والفصل فيها بشكل سريع وعادل ومستقل،
كما ينبغي أن تتأكد من قيام وحدة أو إدارة الشكاوى لديها بمسئولياتها بفعالية وبدون تأخير أو تباطؤ.
د. االحتفاظ بسجالت العمالء الخاصة بالشكاوى محدثًة ومصفوفًة ومنمطًة ، بما يسهم في تسهيل تحديد نمط
التعامل مع نوع الشكاوى المقدمة من العمالء.
ه. بخالف ما تقدم، إذا لم يوافق العمالء على التسوية النهائية التي اتخذتها إدارة الشكاوى بالمؤسسات المالية،
يحق للعمالء اللجوء لوسائل أخرى مثل التوجه إلى اإلدارة المختصة بالشكاوى بالهيئة، والتي ستقوم بفحص
ود ارسة الشكا وى المقدمة واتخاذ الق ارارت الالزمة أو اللجوء إلى مركز التحكيم لتسوية الن ازعات المالية، والتي
يجب أن يكون منصوص ا عليها في العقود المبرمة أو في القانون.
ً
و. وفي جميع األحوال، للعمالء الحق في اللجوء للقضاء، وهو الجهة الفاصلة للفصل في أي ن ازع ينشأ بين
األط ارف.
