المطبقة في حاالت فسخ التعاقد من جانب العمالء.
ك. شرح أي تغيي ارت قد تط أر على األحكام أو الشروط الخاصة بالمنتجات والخدمات المالية والتوقيتات المتوقعة
لحدوثها.
ل. إبالغ العمالء - عن طريق أحد وسائل االتصال المضمونة والمتفق عليها مسبًق ا بين الطرفين - بأي تغيير
في األحكام والشروط خالل ثالثين يوم عمل على األقل قبل إج ارء أي تغيي ارت.
م. أن توفر لعمالئها كافة المعلومات والبيانات المتعلقة بالمنتجات والخدمات المالية المقدمة للمتعاملين من خالل
كتيبات أو منشوارت أو إلكتروني ا، على أن يتم تدوين وإيضاح هذه المعلومات بمنتهى الشفافية والحيادية، وأن
ً
تتسم بالوضوح وسهولة الفهم والبساطة والدقة، بما يكفل اطالع المتعاملين بمختلف مستوياتهم الثقافية والمادية
عليها وتفهمهم للم ازيا والمخاطر المتوقعة، وباألخص عند استخدام نظام الش ارء بالهامش أو اقت ارض األسهم
بغرض البيع أو أسهم الشركات الصغيرة ذات السيولة المحدودة أو المشتقات أو العقود المستقبلية أو الخيا ارت،
وأي نوع من األدوات المالية ذات المخاطر العالية.
كما يجب اإلفصاح عن السياسات واالست ارتيجيات المقترحة لتجنب تلك المخاطر.
