ن. االحتفاظ في كل وقت بالدفاتر والحسابات والسجالت والمستندات والمكاتبات التي توضح م اركزهم المالية،
كما يجب أن ترسل لعمالئها عند طلبهم البيانات المالية الدورية الخاصة بها وفًق ا آلخر قوائم مالية معتمدة.
س. أن يكون لديها م واقع إلكترونية تنشر عليها كافة المعلومات والبيانات األساسية لها وتقاريرها السنوية، باإلضافة
إلى التوعية المالية للعمالء.
ع. يجب على الشركات أن تفصح - كتابة وبخط واضح وفي مكان بارز ومرئي، في كافة العقود والمكاتبات
واإلعالنات والمطبوعات مع العمالء - عن خضوعها لرقابة الهيئة العامة للرقابة المالية، مع توضيح رقم
الترخيص والسجل التجاري ، وأيض ا اإلدا رة المختصة لديها للتعامل مع شكاوى وتظلمات العمالء، وكيفية التواصل
ً
المباشر معها عن طريق رقم هاتفى مخصص للشكاوى . ويجب إحاطة العمالء كتابة عن حقهم في اللجوء إلى
