ف. شروط الدعاية واإلعالن
تلتزم الشركات في مجال الدعاية واإلعالن بما يلي:
•
مارعاة أن تتسم المعلومات المعروضة عن المنتجات والخدمات المالية - المشار إليها في الدعاية وعروض
البيع وجميع سبل الدعاية األخرى - بالدقة والمانة.
ويحظر على الشركات عرض أي معلومات أو خصائص للمنتجات والخدمات المالية من شأنها تضليل
العمالء أو خداعهم أو حذف بيانات مهمة.
•
على الوسطاء والمستشارين بالشركات عدم تضليل العمالء المرتقبين، وخاصة فيما يتعلق بخصائص وفوائد
المنتجات والخدمات المالية، وعلى سبيل المثال األداء السابق والمستقبلي والتكلفة.
• التواصل مع العمالء باستخدام وسيلتي اتصال على القل من الوسائل المفضلة لدى العمالء والتي يتعاملون
بها بسهولة، ومنها - على سبيل المثال ال الحصر- البريد اإللكتروني، البريد المسجل، الرسائل النصية،
والهاتف، كما يمكن للشركات استخدام قنواتها الرئيسية (الفروع، الموقع اإللكتروني).
•
عند استخدام قنوات اإلعالم العامة المرئية والمسموعة والمقروءة لتسويق المنتجات والخدمات المالية -
ي ارعى استخدام األساليب اإلعالنية والدعائية والتسويقية التي ي ر ونها مناسبة للش ارئح المستهدفة، وبما يتماشى
مع األنظمة واللوائح والتعليمات والقواعد الصادرة عن الهيئة، والتأكد من م ارعاة القوانين األخرى ذات العالقة.
