ب. خدمات االستشاارت المالية
يجب على مقدمي خدمات االستشاارت المالية اإلفصاح للعمالء الحاليين والمرتقبين عما يلي:
- توفير معلومات أساسية واقعية تعرض بإيجاز وبلغة واضحة ومفهومة للعمالء المنتجات والخدمات المالية
التى يتم عرضها عليهم أو بيعها لهم.
- توضيح موقف األدوات المالية التي ينصح بها المستشار المالي، من حيث طريقة الحصول عليها سواء
من خالله أو من خالل كيان اعتباري أو أشخاص طبيعية بحوزتهم تلك األدوات المالية، وهل سيتم
ش ارؤها أم بيعها.
- االلت ازم بالمعايير المصرية للتقييم المالي للمنشآت عند تحديد القيمة العادلة لألوارق المالية.
