(8)
المبدأ الثاني: السلوك والكفاءة المهنية
تلتزم الشركات في مجال السلوك والكفاءة المهنية بما يلي:
أ. اإلفصاح للعمالء عن شروط الترخيص ومدى الت ازمهم بقواعد السلوك والكفاءة المهنية.
ب. بذل عناية الرجل الحريص لتوفير الموارد اإلدارية والمالية والتشغيلية والبشرية الالزمة لتنفيذ أعمالها وخدمة
عمالئها بكل كفاءة ودون تأخير.
ج. أن يتوافر لدى القائمين على إدارة الشركات الخب ارت اإلدارية والكفاءات الالزمة لم ازولة النشاط.
د. أن تحرص على ممارسة وأداء عملها بأسلوب مهني مسئول لتحقيق أفضل مصلحة للعمالء في كافة م ارحل
تعاملهم مع المؤسسات المالية، باعتبارها مسئولة عن حماية مصالح العمالء فيما يقدم إليهم من منتجات
أوخدمات مالية. ويأتي على قمة هذه السلوكيات الن ازهة والمصداقية والتحقق من مناسبة الخدمات والمنتجات
المقدمة للعمالء إلمكانياتهم وقد ارتهم واحتياجاتهم المالية، مع م ارعاة مستواهم المادي والعلمي.
ه. التنافس في تقديم أفضل المنتجات والخدمات واألسعار بما يلبي احتياجات العمالء ورغباتهم، دون إخالل بما
تقتضيه األنظمة واللوائح في هذا الشأن.
و. التأكد من توافر المؤهالت العلمية والكفاءات والمها ارت الالزمة، باإلضافة إلى التدريب المالئم والمستمر
لموظفي الشركات الذين يتعاملون مع العمالء ويقدمون لهم المنتجات والخدمات المالية، والتأكد من فهم وإلمام
واستيعاب العاملين لدى الشركات للمنتجات والخدمات المالية المقدمة للعمالء.
ز. التأكد من حصول العاملين بالشركات على التأهيل المهني المطلوب واستيفاء متطلبات الكفاءة، من خالل
إلحاقهم بب ارمج متخصصة للحصول على الشهادات المهنية المناسبة التي تؤهلهم للتعامل مع العمالء.
ح. التأكد من أن العاملين الذين يتول ون خدمات العمالء يتمتعون باآلتي:
• القيام بأداء مهامهم بكفاءة وفعالية ومهنية والقدرة على تقديم الخدمات المنوطة بهم في الوقت المناسب.
• اتباع السلوكيات الجيدة والتعامل بمهنية عند خدمة العمالء الحاليين أو العمالء المرتقبين في جميع األوقات.
• اإللمام الكامل بأفضل الممارسات المهنية؛ حتى يتسنى لهم مساعدة العمالء.
ط. أن يكون لديها سياسة مكتوبة وواضحة ومعتمدة من مجلس اإلدارة بشأن تعارض المصالح، والعمل بشكل مستمر
وفعال للتأكد من كفاية اإلج ارءات المتبعة والسياسات المطبقة في كشف الحاالت المحتملة لتعارض المصالح.
(8) مادة 512، 712، 812 من الالئحة التنفيذية للقانون 59 لسنة 2991 الخاص بسوق أرس المال.
