ي. اإلفصاح عن أي حاالت تعارض للمصالح وفًق ا لما تحدده سياساتهم الداخلية وكذلك ما تفرضه الهيئة من
قواعد ونظم للحوكمة، ووجود سياسة مكتوبة بشأن تعارض المصالح، وتحديد اإلج ارءات الالزمة لضمان
التعامالت العادلة مع كافة العمالء، والتأكد من وضع السياسات التي تساعد في الكشف عن العمليات المحتملة
لتضارب المصالح مع تفعيلها وتطبيقها.
ك. في احتمالية حدوث تعارض للمصالح بين الشركات وأي أط ارف أخرى وكان لهذا التضارب أي أثر محتمل
على العمالء فينبغي على الشركات اإلفصاح للعمالء عن هذا التضارب، وفًق ا لما تقتضيه األنظمة واللوائح
والتعليمات ذات العالقة.
ل. وبالنسبة للشركات المرخص لها بم ازولة أكثر من نشاط، عليها أن تفرد لكل نشاط إدارة مستقلة مع الفصل
(9)
التام بين اإلدا ارت؛ وبما يؤدي إلى تجنب نشوء تعارض المصالح.
(01)
المبدأ الثالث: العدالة وعدم التمييز بين العمالء
تلتزم الشركات في مجال العدالة وعدم التمييز بين العمالء بما يلي:
(11)
أ. م ارعاة الدقة واألمانة والحرص أثناء تنفيذ أوامر العمالء أو أثناء عرض وتقديم المنتجات والخدمات المالية.
(21)
ب. حظر اتباع سياسة أو إج ارء عمليات من شأنها اإلض ارر بالعمالء أو اإلخالل بحقوقهم.
(31)
ج. حظر اتباع أية أساليب في عملها تنطوي على الغش أو التدليس.
د. حظر إد ارج أي مصطلحات غير منصفة أو مضللة في العقود المبرمة بينها وبين العمالء.
ه. م ارعاة أن تتسم معامالتهم مع العمالء بالعدل والمساواة واإلنصاف واألمانة، وأن تحرص على جعل هذا المنهج
جزء ا من قواعد الحوكمة لديها.
ً
و. حظر القيام بأي ممارسات ضارة ضد عمالئها عند استيفاء الديون، أو عند استقطاب عمالء جدد، مثل تك ارر
االتصال واإللحاح على العمالء للتعاقد.
ز. حظر إساءة استخدام األصول الخاصة بالعمالء.
