ح. إعطاء مزيد من الرعاية واالهتمام بالعمالء، خصوص ا كبار السن وذوي االحتياجات الخاصة. وأن تبذل العناية
ً
الكافية عند التعامل مع العمالء من محدودي الدخل والعلم، ومساعدتهم واالستجابة الستفسا ارتهم وأسئلتهم،
وذلك دون تمييز بين الجنسين، وأيض ا عدم التفضيل في التعامل بين عمالئها (الحاليين أو المرتقبين) بسبب
ً
العرق أو الجنس أو الدين.
ط. أن تكون لديهم نظم مناسبة للحصول على المعلومات الضرورية عن العمالء لتقدير احتياجاتهم من المنتجات
والخدمات المالية وتقديم العروض المالئمة حسب احتياجات كل عميل.
ي. أن تحصل من العمالء على معلومات شاملة ودقيقة عن قد ارتهم وإمكانياتهم وخب ارتهم وأوضاعهم وأهدافهم
المالية؛ لتقديم المشورة والنصح لهم في اختيار المنتجات والخدمات المالية المالئمة لهم، وأن تقدم المعلومات
بالشكل الذي يسمح للعمالء بإج ارء مقارنة بين المنتجات والخدمات المالية المقدمة ومثيالتها في السوق.
ك. يحظر على مسؤلي المبيعات في الشركات اللجوء إلى الممارسات الخاطئة وغير العادلة، مثل االتصال
واإللحاح للتعاقد مع عمالء جدد بدون رغبتهم.
ل. تسهيل اإلج ارءات للعمالء عند رغبتهم في نقل حساباتهم إلى شركات أخرى أو التعامل مع صناديق أخرى -
بدون تعطيل أو تسويف - وفي فترة ال تتجاوز ثالثة أيام عمل - بعد التأكد من قيام العمالء بتسديد ما عليهم
من الت ازمات واستيفاء كافة اإلج ارءات المطلوبة لغلق حساباتهم.
م. عدم شمول أي عقود بين الشركات وعمالئها على أية نصوص مسيئة للشروط واألحكام المتبعة من قبل تلك
الشركات، ومنها على سبيل المثال إل ازم العمالء بعمل إيداع ألية مبالغ مالية مقابل الحصول على خدمة مقدمة
من الشركات بأعلى مما هو منصوص عليه في القانون المنظم للنشاط، أو إل ازم العمالء بإبقاء النقدية الخاصة
بهم في حسابات معينة تحددها الشركات، والتي تستلزم معها دفع مقابل نقدي (رسوم) أعلى من نظي ارتها.
ن. عدم وجود أية نصوص من شأنها تقليل أو تقييد الحقوق الخاصة بالعمالء لديها، منها على سبيل المثال وجود
أية نصوص تعفي الشركات من القيام باإلفصاح الكامل للبنود الواردة بالبند السابق، أو وجود نصوص تمنع
العمالء من الرجوع على السجالت الخاصة بهم لدى الشركات، أو نصوص تقلل من خصوصية بيانات العمالء.
س. وجود نص بالعقود يؤكد أحقية العمالء في الرجوع إلى القضاء ألي أض ارر أو خسائر تسببت لهم نتيجة سوء
استخدام الشروط واألحكام من قبل الشركات المتعامل معها.
ع. في حالة تعذر تقديم المنتجات أو الخدمات المالية للعمالء، يحق للعمالء معرفة أسباب الرفض، كما يحق
لهم إستعادة المستندات األصلية التي قدموها للشركات.
