(41)
المبدأ ال اربع: حماية سرية وخصوصية حسابات وبيانات العمالء
تلتزم الشركات في مجال حماية سرية وخصوصية حسابات وبيانات العمالء بما يلي:
أ. وضع األنظمة الرقابية واآلليات والسياسات التي تكفل حماية المعلومات المالية والشخصية لعمالئها، والحفاظ
على سريتها وخصوصيتها، وعدم االطالع عليها أو استغاللها وعدم إفشاء أية معلومات عنهم أو عن
معامالتهم إلى الغير - بدون موافقتهم الكتابية المسبقة وفي حدود هذه الموافقة - إال على النحو الذي ينظمه
القانون ، ويستثنى من ذلك الحاالت التي يلزم فيها تقديم معلومات محددة إلى الجهات الرقابية أو البورصة أو
الجهات القضائية.
ب. وضع النظم والتدابير الالزمة والتي تحدد كافة الموظفين المختصين لديها الذين لهم حق االطالع فقط أو
التعامل على حسابات العمالء، بناء على اختصاصهم ودرجتهم الوظيفية.
ج. وضع أنظمة رقابية داخلية فعالة تتسم بالكفاءة والرقابة الدقيقة؛ بهدف الحد من عمليات االحتيال واالختالس
أو إساءة استخدام البيانات المالية. ويجب التأكد بشكل مستمر من كفاءة األنظمة المستخدمة لمواكبة التغيي ارت
في األساليب االحتيالية، وكذا مواكبة التطور التكنولوجي.
د. إدارة كافة المخاطر التي قد يتعرض لها العمالء نتيجة تقديم المنتجات والخدمات المالية بوسائل إلكترونية.
ه. تحمل أية أض ارأرو خسائر قد تلحق بالعمالء بسبب وقوع خلل في األنظمة لدي الشركات أوعمليات اإلحتيال
أو اإلخت ارق التي قد تحدث ألى سبب كان، بخالف ما وقع نتيجة لتقصير من جانب العمالء.
و. اتخاذ اإلج ارءات التي تكفل الت ازم المديرين والعاملين بها بالحفاظ على سرية البيانات والمعلومات لديهم، وعليها
اتخاذ اإلج ارءات المناسبة لتفعيل األنظمة الرقابية لديهم، وكذا اتخاذ كافة التدابير واإلج ارءات األمنية الالزمة
لحماية بيانات العمالء الكتشاف أو معالجة أي تجاوازت حدثت أو يتوقع حدوثها.
ز. يلتزم العامل ون بالشركات - سواء العامل ون الدائم ون أو المؤقت ون - بالتوقيع على إق ارارت المحافظة على
السرية بشأن بيانات العمالء، والتأكد من عدم كشفهم المعلومات المالية والشخصية للعمالء، ومنع الدخول
عليها، واقتصارها على األشخاص المخولين فقط، سواء أثناء العمل أو بعد تركهم لوظائفهم.
ح. تطبيق الحد األقصى من التدابير واإلج ارءات األمنية لرقابة عمليات التمويل وحمايتها من االحتيال أو
االستخدام غير المشروع.
