المبدأ الخامس: تسوية الن ازعات ومعالجة شكاوى العمالء (51)
تلتزم الشركات في مجال تسوية النازعات ومعالجة شكاوى العمالء بما يلي:
أ. التعامل مع الشكاوى داخليا:
ً
•
توفير آلية مناسبة لعمالئها لتقديم شكاواهم، تتسم بالفعالية والعدالة والوضوح والن ازهة واالستقاللية والحيادية،
وتمكنهم من متابعة ومعالجة الشكاوى دون تأخير، وفًق ا لألنظمة واللوائح والتعليمات الصادرة من الهيئة
والجهات ذات العالقة.
•
تخصيص إدارة متخصصة للتعامل مع شكاوى العمالء لديها، وأن تحدد لها آلياتها واختصاصاتها، وأن تعين
بها موظفين متخصصين لفحص الشكاوى والتظلمات.
•
أن تولي شكاوى وتظلمات العمالء العناية الالزمة، وأن يتم األداء والفصل فيها بشكل سريع وعادل ومستقل،
كما ينبغي أن تتأكد من قيام إدارة الشكاوى لديها بمسئولياتها بفعالية وبدون تأخير أو تباطؤ.
•
االحتفاظ بسجالت العمالء الخاصة بالشكاوى محدثًة ومصفوفة ومنمطة، بما يسهم في تسهيل تحديد نمط
التعامل مع نوع الشكاوى المقدمة من العمالء.
•
االلت ازم عند تلقي شكاوى العمالء القيام بما يلي:
−
اإلق ارر كتابة باستالم الشكاوى.
−
تقديم تقدير زمني للتعامل مع الشكاوى.
−
تزويد العمالء بمسئول االتصال لمتابعة الشكاوى المقدمة.
−
تزويد العمالء باسم المسئولين عن الشكاوى وأرقام هواتفهم؛ حتى يتمكن العمالء من االتصال بهم
عند الحاجة إلى متابعة الشكاوى.
−
إبالغ العمالء بما تم في الشكاوى المقدمة منهم.
−
تسوية الشكاوى بشكل سريع وعادل وخالل مدة ال تجاوز أسبوع ا.
ً
−
إشعار العمالء خطي ا بقبول الشكاوى أو رفضها، مع توضيح األسباب الداعية لذلك والتعويض
ً
المعروض للعمالء، وتوضيح أي خالفات في قيمة التعويض المعروض على العمالء.
(51) مادة 812، 912 من الالئحة التنفيذية للقانون 59 لسنة 2991 الخاص بسوق أرس المال.
