ب. التعامل مع الشكاوى خارجيا:
ً
•
بخالف ما تقدم، إذا لم يوافق العمالء على النتائج النهائية التي اتخذتها إدارة الشكاوى بالشركات، يحق للعمالء
اللجوء لوسائل أخرى مثل التوجه إلى االتحاد المصري لألوارق المالية الذي يستقبل شكاوى العمالء ويعمل
على تسويتها ودي ا أو يرفع بها توصية للهيئة، أو التوجه إلى اإلدارة المختصة بالشكاوى بالهيئة، والتى ستقوم
ً
بفحص ود ارسة الشكا وى المقدمة واتخاذ الق ارارت الالزمة.
• باإلضافة إلى ذلك من حق العمالء أن يلجأوا لمركز التحكيم لتسوية الن ازعات المالية، والتي يجب أن يكون
منصوص ا عليها في العقود المبرمة أو في القانون.
ً
•
وفي جميع األحوال واألوقات، للعمالء الحق في اللجوء للقضاء؛ للفصل في أي ن ازع ينشأ بين األط ارف.
المبدأ السادس: سبل الضمانات والتعويضات
صندوق تأمين المتعاملين في الوارق المالية من المخاطر غير التجارية، الناشئة عن أنشطة الشركات العاملة في
مجال الوارق المالية والشركات المقيد لها أوارق مالية بالبورصة، والمعروف اختصا ار بصندوق "حماية المستثمر":
ً
أ. نطاق الحماية التي يوفرها الصندوق
•
تغطية الخسارة المالية الفعلية لعمالء شركات األوارق المالية (األعضاء) ضد المخاطر غير التجارية الناشئة
عن نشاط العضو في األوارق المالية المقيدة بالبورصة المصرية، وتشمل الحماية الخطار التالية:
− إفالس أو تعثر عضو الصندوق ؛ وتتحدد حالة التعثر وبدايتها بق ارر يصدره مجلس إدارة الصندوق.
−
خطأ أو إهمال أو غش أو احتيال العضو أو ممثله القانوني أو القائم باإلدارة الفعلية له أو من العاملين لديه
سواء بنفسه أو باالشتارك مع الغير، وذلك وفًق ا لنتيجة التحقيقات التي تجريها الهيئة أو الجهات القضائية.
− الت ازم الصندوق بالوفاء لعميل العضو بقيمة التعويض المقرر عن الخسارة التي لحقت بالعميل.
− تكون وحدة التغطية بحد أقصى خمسمائة ألف جنيه للعميل، ويشمل األوارق المالية التي يتعامل عليها
العميل لدى العضو، وكذلك الرصيد النقدي الدائن بالحساب الناتج عن تعامالت العميل في األوارق المالية
لدى الشركة بما ال يتعدى مائة ألف جنيه، وبما ال يجاوز الحدود األخرى الواردة بق ارر إنشاء الصندوق .
− للصندوق تعويض عمالء أعضاء الصندوق بش ارء ذات األوارق المالية بقيمة التعويض المستحق لهم
من الصندوق.
− للصندوق تعويض عمالء أعضاء الصندوق بش ارء ذات األوارق المالية لهم بقيمة التعويض المستحق
من الصندوق ، وذلك وفًق ا للقواعد التي يصدر بها ق ارر من مجلس إدارة الصندوق.
55

− ال يلتزم الصندوق بتعويض عمالء أعضائه أو المستثمرين فى األوارق المالية عن أي خسائر مالية
تنتج عن التغير في قيمة األوارق المالية الخاصة بالعميل أو الناتجة عن ضياع الفرص البديلة الستثمار
أموال العميل بمعرفة العضو.
− ال يلتزم الصندوق بالتعويض بأكثر مما تتيحه أمواله، وفي حالة زيادة قيمة التعويضات المقررة عن المبالغ
المتاحة للتعويض لدى الصندوق يتم توزيع هذه المبالغ على مستحقي التعويض بطريقة قسمة الغرماء.
− للعميل العضو الرجوع على العضو المخالف بما يجاوز ما أداه إليه الصندوق من تعويض.
• يتضمن نظام عمل مجلس إدارة الصندوق اختصاصاته وقواعد استثمار أمواله؛ وقد أتاح إمكانية استخدام
جزء من فائض استثمار الصندوق ألمواله - بما ال يتعدى 1% من حجم األموال المتاحة في الصندوق
- في مجاالت تهدف إلى حماية المستثمر وتوعية المتعاملين فى السوق وتحقيق الوقاية السابقة.
• لمجلس إدارة الصندوق - في ضوء د ارسة أوضاع السوق ومؤش ارت القيمة السوقية والتداول وتقييم
المخاطر وحجم األموال المتاحة بالصندوق - اقتارح تعديل االشتاركات الدورية وكذا التغطية التي
يوفرها للمتعاملين فى السوق.
ب. قواعد وإجارءات تقديم طلبات التعويضات
طلب التعويض والمستندات المؤيدة له:
•
يتم صرف التعويض بناء على طلب من عميل العضو (الشركة).
ً
•
يقدم طلب التع ويض من العميل مستوفي ا البيانات والمستندات المؤيدة له والتي تتضمن:
ً
− صورة من العقد المبرم مع الشركة عضو الصندوق .
−
صورة من إخطار العميل للعضو بالواقعة محل المخالفة.
− كشف حساب نقدي صادر من الشركة عضو الصندوق .
− مستندات إثبات سداد العضو للشركة عضو الصندوق .
−
بيان يوضح كافة اإلج ارءات التي اتخذها العميل في مواجهة العضو خالل ثالثين يوم ا من تاريخ
ً
اكتشاف العميل للواقعة الموجبة للتعويض.
−
تتضمن م رفقات طلب التعويض ما يفيد إج ارء تحقيقات في الطلب بالهيئة أو إحدى الجهات
القضائية، إن وجدت، على أن يتم موافاة الصندوق بنتائج هذه التحقيقات.
•
على العميل المتضرر مطالبة العضو بمستحقاته وإخطار الهيئة، وذلك قبل تقديم طلب التعويض الى
الصندوق، ويكون إخطار العميل للهيئة أو طلب الصندوق نتائج التحقيقات قاطع ا للمواعيد المنصوص عليها.
ً
65

• ال تقبل شكوى العميل بعد مضي ثالث سنوات ميالدية من حدوث الواقعة محل طلب التعويض، ما لم
يكن العميل قد اتخذ إج ارء قضائي ا ضد الشركة أو تقدم للهيئة بشكوى خالل هذه المدة.
ً ً
• يتم إجارء تحقيق بمعرفة لجنة يشكلها مجلس إدارة الصندوق ، على أال تتجاوز المدة - التي يستغرقها
التحقيق، وإصدار ق ارر مسبب فيه، سواء بقبول الطلب أو برفضه - خمسة عشر يوم ا من تاريخ تقديم
ً
الطلب مستوفي ا البيانات والمستندات المؤيدة له، وتكون هذه المدة ثالثين يوم ا في حالة طلبات التعويض
ً ً
التي تقدم من ثالثين عميالً فأكثر سواء كانت ضد عضو واحد أو أكثر من أعضاء الصندوق.
•
يخطر العميل بقبول الطلب أو رفضه خالل فترة ال تتجاوز خمسة عشر يوم ا من تاريخ تقديمه طلبه
ً
مستوفي ا البيانات والمستندات، على أن يتضمن اإلخطار أسباب الرفض أو عدم تلبية كل طلبات العميل.
ً
• يقتصر التعويض على األض ارر المالية دون األض ارر األدبية.
•
ي ارعى عند تحديد قيمة التعويض أية مبالغ حصل عليها العميل من العضو أو الغير بسبب الخطر
ُ
محل التعويض، كما ي ارعى عند صرف التعويض خصم أية مبالغ مستحقة للعضو لدى العميل.
•
يتم صرف مستحقات العميل خالل ثالثين يوم ا من تاريخ البت في طلب التعويض بثبوت حقه في التعويض.
ً
• يكون التعويض بمثابة تسوية نهائية لمستحقات العميل في مواجهة الصندوق عن الواقعة محل
التعويض، وذلك مع عدم اإلخالل بحق العميل في الرجوع على العضو للمطالبة بالتعويض فيما يجاوز
ما أداه إليه الصندوق.
ج. التظلمات
• لكل ذي مصلحة الحق في التظلم من ق ارارت اللجنة المشار إليها أعاله أمام مجلس إدارة الصندوق
خالل خمسة عشر يوم ا من تاريخ إبالغه بق ارر التعويض أو بق ارر رفضه، على أن يوضح بالتظلم
ً
موضوعه وأسانيده ويرفق به ما يؤيده من مستندات، ويتسلمه منه الموظف المختص.
• على مجلس إدارة الصندوق البت في التظلم خالل خمسة عشر يوم ا من تاريخ تقديمه مستوفي ا
ً ً
المستندات الالزمة.
• يتم إخطار العضو والعميل بقارر مجلس إدارة الصندوق خالل أسبوع من تاريخ صدوره.
• للعميل أو العضو الحق في االعتارض على قارر مجلس إدارة الصندوق أمام الهيئة خالل خمسة
عشر يوم ا من تاريخ إخطاره به، وتفصل الهيئة في االعت ارض خالل خمسة عشر يوم ا من تاريخ
ً ً
تقديمه، ويكون ق ارر الهيئة بالفصل في االعت ارض نهائي ا؛ وذلك دون اإلخالل بحق العميل والعضو في
ً
التظلم من ق ارر الهيئة واللجوء للقضاء.
75

د. التازمات هامة تخص عمالء الشركات العاملة في مجال الوارق المالية
−
الصدق عند تقديم المعلومات
تقديم كافة المعلومات المطلوبة منهم كاملًة ودقيقة عند تعبئة أي نماذج تطلبها الشركات، وال يجوز للعمالء
تقديم أي معلومات مضللة أو خاطئة أو غير مكتملة أو عدم اإلفصاح عن المعلومات الهامة أو الجوهرية.
−
قارءة كافة المعلومات التي قدمتها الشركات بدقة
االطالع على كافة التفاصيل الكاملة بشأن االلت ازمات المترتبة عليهم مقابل حصولهم على المنتجات
والخدمات المالية من الشركات، والتأكد من فهمهم لها بشكل واضح وقدرتهم على االلت ازم بها.
−
طرح السئلة
طرح أي أسئلة لموظفي الشركات لالستفسار في حال عدم وضوح أي بنود أو شروط في عقود فتح الحساب
أو أي مستندات أخرى مقدمة من قبل الشركات، ويجب على موظفي الشركات اإلجابة على تلك األسئلة
بأسلوب مهني واضح يساعد العمالء على اتخاذ الق اررت المناسبة.
−
التأكد من البيانات الواردة في عقود فتح الحساب
التأكد من أن النسخ المصدرة لعقود فتح الحساب تشمل كافة المحتويات، ومن ذلك - على سبيل المثال ال
الحصر- بياناتهم الشخصية وقيمة العموالت ومعدالت العوائد وكافة الرسوم واألعباء المالية.
− معرفة كيفية تقديم الشكاوى
التأكد من كافة المعلومات والبيانات الالزمة بشأن آلية تقديم الشكوى واإلطار الزمني لموافاتهم بالنتيجة.
وينبغي على العمالء التأكد من حصولهم على أرقام وعناوين االتصال لتقديم الشكاوى ومتابعاتها.
−
استخدام المنتج والخدمة المالية بموجب الحكام والشروط
عدم استخدام أي منتجات وخدمات مالية إال وفًق ا لألحكام والشروط المرتبطة بها، وذلك بعد التأكد من فهمها
بشكل كامل.
−
عدم التعرض للمخاطر
عدم ش ارء أي منتجات وخدمات مالية عند الشعور أن المخاطر ال تتالءم مع وضعهم المالي.
−
تقديم طلبات للحصول على المنتجات أو الخدمات المالية التي تتناسب مع احتياجات العمالء
التأكد من مالءمة المنتجات والخدمات المالية الحتياجاتهم، وعلى العمالء اإلفصاح عن كافة الت ازماتهم
المالية مع كافة الجهات، وقدرتهم على الوفاء بااللت ازمات المترتبة بعد الحصول على الخدمات المالية.
−
إبالغ الشركات بشأن اإلجارءات غير النظامية
إبالغ الشركات في حال اكتشاف أي إج ارءات مخالفة أو غير سليمة تمس المنتجات والخدمات المالية على
الفور - وفي حال عدم تجاوب الشركات - فإنه يحق للعمالء التقدم بالشكاوى إلى الهيئة.
85

−
استشا رة الشركات عند مواجهة أي صعوبات
التحدث مع الشركات التي يتعامل ون معها لطلب االستشارة إذا واجهوا أية صعوبات مالية أو كانوا غير
قادرين على تحمل االلت ازمات المالية، ومناقشة الخيا ارت المتاحة بما يتناسب مع وضعهم المالي.
−
تحديث المعلومات
تحديث بياناتهم الشخصية بما فيها بيانات االتصال بشكل دوري وعندما تطلب الشركات ذلك، مع م ارعاة
أن عدم تحديث البيانات الشخصية وال سيما الجوهرية منها قد يؤدي إلى نشوء مسئولية على العمالء أو
ضياع حقوقهم.
−
عنوان البريد
تحديد عنوان للمارسالت (البريد العادي/ أو البريد اإللكتروني) وأرقام االتصال الخاصة بهم، وعدم استخدام عناوين
أخرى ال تخصهم، مثل عناوين األصدقاء أو األقارب، على النحو الذي يؤدي إلى إفشاء معلوماتهم الشخصية.
−
الوكالة العامة
توخي الحذر عند إصدار توكيالت عامة للغير إلنجاز تعامالتهم المالية، وأهمية م ارعاة المعرفة المسبقة
لمن يصدر لهم التوكيالت وتكون لهم الصالحية للتصرف في شئونهم المالية، ومن لهم حق االطالع عليها.
−
عدم التوقيع على نماذج (االستماارت) غير المكتملة
أن يتأكدوا من اكتمال كافة المواضيع واألرقام المطلوبة في النماذج المقدمة لهم للتوقيع عليها، وال يجوز
التوقيع على أي نماذج فارغة أو غير مكتملة، مثل: أوامر البيع والش ارء على بياض، أو نموذج لمصادقات
على حساباتهم فارغة أو غير مكتملة.
−
مارجعة جميع المعلومات والبيانات
م ارجعة جميع المعلومات التي قاموا بتسجيلها في النماذج؛ لضمان صحة المعلومات، وعدم وجود أخطاء
في البيانات المدونة، ومعرفة أن التوقيعات الخاصة بهم على النماذج تعني موافقتهم على محتوى النماذج.
−
اإلفصاح عن معلوماتهم الشخصية
عدم اإلفصاح عن أي معلومات شخصية أو مالية ألي طرف آخر غير الشركات التابعين لها وتحت أي
ظرف من الظروف.
−
أحقية العمالء في الحصول على نسخ من العقود والمستندات الموقعة
ينبغي على العمالء التأكد من حصولهم على نسخ من العقود والمستندات بعد التوقيع عليها والمصدق عليها
والمعتمدة من الشركات واالحتفاظ بها في مكان آمن.
95

ا
سادس ا: دليل محاية املتعاملني مع شركات التأمني
المبدأ الول: اإلفصاح والشفافية
أ. تلتزم شركات التأمين لدى تعاملها مع عمالئها باإلفصاح والشفافية، وعلى وجه أخص ما يلي:
•
عرض المعلومات الخاصة بالمنتجات والخدمات التي تقدمها- سواء التأمينية منها أو االستثما رية لعمليات
تأمينات األشخاص وتكوين األموال - بلغة سهلة وواضحة، متضمنة كافة المفاهيم والشروط واألحكام
األساسية، مع عدم استخدام مصطلحات فنية غير واضحة أو غير ضرورية. وإذا تم استخدام مصطلحات
تقنية فيجب تفسيرها بطريقة واضحة.
• أن يكون حجم الخط وتباعد المسافات بين الحرف والكلمات واضحا ومقروءا بسهولة للشخص العادي.
ً ً
• أن يكون التواصل الشفوي - خالل مرحلتي ما قبل التعاقد والتعاقد في شرح الخصائص والمميازت الرئيسية
لوثائق التأمين للمؤمن عليهم - بشكل واضح ومفهوم، وإ ازلة أي غموض؛ حتى يتمكن المؤمن عليهم من
اتخاذ ق ارارتهم التأمينية.
•
تسليم العمالء نموذج البيانات األساسية، يتضمن المعلومات الرئيسية عن نوع المنتجات والخدمات التأمينية
المقدمة، وأهم المخاطر التي تغطيها هذه المنتجات والخدمات التأمينية، والشروط العامة واالستثناءات للتغطية
التأمينية، وفترة السماح، وأية ضمانات مالية إن وجدت، والشروط الفاسخة لوثائق التأمين، وما يترتب عليها
من آثار مالية، وكيفية االستفادة من صندوق ضمان حملة الوثائق و/أو المستفيدين منها. ويجب أن يتضمن
النموذج تنويه ا هام ا وصريح ا بأن أي عوائد أو أرباح سابقة على تلك المنتجات والخدمات التأمينية غير
ً ً ً
مضمون تحقيقها في المستقبل.
كما يصدر النموذج في حدود صفحتين على األكثر لكل منتج أو خدمة تأمينية. ويجب أن يوقع العمالء عليه
بعد ق ارءة كافة بنوده. ويتيح نموذج البيانات األساسية أن تكون البيانات المقدمة للعمالء سهلة المقارنة مع
عروض شركات التأمين المختلفة في السوق الختيار أفضل منتج وخدمة تأمينية مناسبة الحتياجاتهم التأمينية.
• توفير كتيبات أو ملخصات صغيرة شارحة لكل منتج وخدمة تأمينية تقدمها شركات التأمين، على أن تكون
مكتوبة بأسلوب واضح وسهل الفهم، بما يتناسب مع كافة المستويات الثقافية والتعليمية للمؤمن لهم، وم ارعاة
أال يشوب ما يتم الدعاية عنه غموض أو تضليل.
06

•
أن تدرج كافة المنافع الرئيسية والشروط الفاسخة للعق ود، في نماذج تقديم طلبات الحصول على المنتجات
والخدمات التأمينية، التي يقوم المؤمن لهم باستيفائها والتوقيع على كل صفحاتها، على أن تكون شاملة
ومصاغة بوضوح، ومفهومة وغير مضللة، وبخط مقروء وبارز. ويجب أن يحصل المؤمن لهم على نسخ من
الطلبات بعد توقيعهم عليها.
•
فيما عدا ما يتعلق بتعديل الخطاء اإلمالئية، وما تقره النظمة المعمول بها - يجب االلت ازم بما تضمنته
وثائق التأمين وملحقاتها وعدم تعديلها إال بموافقة خطية من المؤمن لهم، ووفًق ا لنموذج يعد بغرض التعديالت
على وثائق التأمين، على أن تصدر شركات التأمين ملحًق ا للوثائق بعد موافقة المؤمن لهم على التعديالت.
•
بالرغم من اختالف طبيعة كل منتج تأميني عن اآلخر، إال أنه يجب إيضاح البيانات األساسية في كل منتج
تأميني كالتالي:
−
اسم المؤمن، والشكل القانوني أو المجموعة التي ينتمي إليها إن وجد.
−
نوع وثيقة التأمين، شاملة التغطية التأمينية والشروط واالستثناءات.
−
طريقة سداد األقساط، ومواعيد االستحقاق، ودورية سدادها، وتبعات التأخير في دفع األقساط.
−
عندما يتعلق األمر بسياسة دمج وثيقة التأمين مع منتجات مالية وخدمات أخرى، يجب اإلفصاح عن
كل منتج وخدمة مالية وقيمة أقساطهم على حدة.
−
اإلفصاح للعمالء عند ش ارئهم وثائق تأمين عما إذا كانت الوثيقة إجبارية أو تكميلية.
−
اإلفصاح للعمالء عن أي خصم أو إضافة في قيمة التكاليف الفعلية والمصاريف اإلدارية على مبلغ
األقساط المحدد، وأي مصاريف أخرى سوف يقوم العمالء بدفعها بشكل مباشر.
−
اإلفصاح وإبالغ العمالء عن تاريخ بدء التغطية التأمينية ونهايته.
−
النص ص ارحة في وثائق التأمين واإلفصاح للعمالء على أنه توجد فترة سماح مدتها عشرة أيام عمل،
إذا لم يتم تقديم خدمات تأمينية لهم. وتبدأ فترة السماح من تاريخ تعاقد المؤمن لهم مع شركات التأمين،
والتي يسمح خاللها للمؤمن لهم بفسخ التعاقد واسترداد مستحقاتهم بدون توقيع أية شروط ج ازئية عليهم.
ويجوز للشركات خصم أي مصاريف إدارية تكبدتها إلصدار العقود، بشرط أن تكون المصاريف اإلدارية
محددة القيمة ومبررة ومعلنة مسبًق ا للعمالء قبل التوقيع على العقود.
16

−
شرح وإيضاح جميع المخاطر التي تتضمنها وثائق التأمين، وكذا المخاطر غير القابلة للتأمين للمؤمن
عليهم، مع إيضاح كافة المعلومات الجوهرية ذات الشأن؛ إلب ارز أي مخاطر جسيمة أو استثنائية أو أي
قيود على وثائق التأمين.
− إيضاح حقوق ومسئوليات وواجبات كل طرف من أط ارف العالقة التأمينية، وتوضيح تفاصيل األقساط
وأية ض ارئب أو رسوم أو دمغات، وكذا أنواع المخاطر، وشرح آلية إنهاء العالقة التأمينية أو إلغاء وثائق
التأمين، وما يترتب على ذلك من آثار - أي ا كان نوعها- من حقوق ومسئوليات والت ازمات واقعة على
ً
العمالء وعلى الشركات في ذات الوقت، وإيضاح سبل التعويض. وكذا شرح الج ازءات المطبقة في
حاالت فسخ التعاقد من جانب العمالء.
• أن تكون شروط وثائق التأمين واستثناءاتها ومازياها الرئيسية واضحة ومختصرة وسهلة الفهم ودقيقة وغير
مضللة، بحيث تناسب كافة أنماط المؤمن لهم من حيث مستوياتهم الثقافية والتعليمية، وتمكنهم من ق ارءتها
دون عناء.
•
اإلجابة على كافة استفساارت المؤمن لهم، من جانب موظفي شركات التأمين ومندوبيها ومسئولي مبيعاتها،
والمتعلقة بوثائق التأمين التي تقدم لهم. وتظل الشركات هي المسئولة عن أية معلومات تم تقديمها للمؤمن لهم
من خالل أي من ممثليها، على أن تكون هذه المعلومات مكتوبة.
• تحديث كافة المعلومات المتعلقة بالخدمات والمنتجات التأمينية بشكل دوري ، وتوفير كافة المعلومات الالزمة
والمحدثة للمؤمن لهم عبر م واقع الشركات اإللكترونية، ومن خالل قنوات االتصال المتاحة والتي يجب أن
تناسب كافة العمالء.
•
أن تتسم المعلومات المقدمة من شركات التأمين بالحياد والشفافية والدقة والمانة، في ضوء التشريعات
(61)
المنظمة للتأمين أو ق اررت الهيئة في هذا الشأن.
• إخطار العمالء بأي تعديالت تطأر على وثائق التأمين أو أي تعديالت أخرى تخص بيانات عمل الشركات
وم اركزها الرئيسية وفروعها أو في حالة تغيير أي من مسئوليها و/أو ممثليها الذين ينبغي على المؤمن عليهم
التعامل معهم مباشرة. ويجب أن تتسم اإلخطا ارت بالوضوح والشفافية والص ارحة، وأن تكون في توقيتها المناسب.
(61) قارر رقم 508 لسنة 6102 بشأن ضوابط المواقع اإللكترونية للشركات ووسطاء التأمين أو إعادة التأمين على شبكة المعلومات الدولية، وقارر رقم 037
لسنة 6102.
26

• إخطار عمالئها بأية أحداث تكون جوهرية أو تتسم بالقوة القاهرة وتؤثر على ماركزهم المالية والتأمينية،
ومنها على سبيل المثال ال الحصر: انخفاض معدالت العائد على االستثمار، أو تغير سعر الصرف للعمالت
(71)
األجنبية، أو زيادة قيمة الشئ موضوع التأمين .
•
تعريف عمالئها بوسطاء التأمين المخول لهم التعامل معهم، وعلى الوسطاء أن يقدموا للعمالء ما يثبت
عالقتهم بالشركات، وكذا كارنيهات القيد بالهيئة العامة للرقابة المالية.
•
إخطار المؤمن لهم وحملة الوثائق مسبًق ا برغبة الشركات بتعديل بعض الحكام والشروط الموضحة بالوثائق،
مع تقديم شر ح وا ف ألسباب تغيير السياسة الخاصة بحملة الوثائق، ولما ستئول إليه حقوق حملة الوثائق
والمستفيدين منها بعد التغيير. وال يجوز إج ارء أية تعديالت على الوثائق بدون موافقة مكتوبة من المؤمن
عليهم أو حملة الوثائق، وبالتأكيد بعد اعتماد الهيئة العامة للرقابة المالية تلك التعديالت.
•
نشر ملخص وا ف للتقارير والقوائم المالية السنوية وأية أحداث جوهرية في صحيفتين يوميتين واسعتي
اال نتشار، تكون إحداهما على األقل باللغة العربية، وفًق ا للنماذج التي تعدها الهيئة في هذا الشأن، وكذلك على
(81)
الموقع اإللكتروني الذي تخصصه الهيئة لهذا الشأن.
• أن يكون لديها م واقع إلكترونية تنشر عليها كافة المعلومات والبيانات الساسية لها، والتوعية التأمينية
للعمالء، وتعريفهم بالشركات وكيفية االتصال بها، وتقديم الشكاوى واالستفسا ارت وتلقي الردود عليها، وكذا
القوائم المالية والمي ازنيات الختامية. باإلضافة إلى اإلج ارءات والشروط واألحكام الخاصة بوثائقهم وأية تغيي ارت
تط أر عليها. وال يجوز استخدام هذه المواقع لغير الغ رض المصرح به من الهيئة. ويتعين الحصول على موافقة
مسبقة من الهيئة قبل إطالقهم الم واقع اإللكترونية على شبكة اإلنترنت.
كما يجب عليها االلت ازم بعدم إنشاء أكثر من موقع للشركة الواحدة، وأن يتم كتابة محتويات الموقع وفًق ا لق ارارت
(91)
الهيئة في هذا الشأن.
(71) شرط النسبية.
(81) مبدأ مستحدث (طبًقا للقارر الوازري رقم 22 لسنة 4102 بتعديل بعض أحكام الالئحة التنفيذية للقانون رقم 59 لسنة 2991 الخاص بسوق أرس المال).
(91) قارر رقم 508 لسنة 6102 بشأن ضوابط المواقع اإللكترونية لشركات ووسطاء التأمين أو إعادة التأمين على شبكة المعلومات الدولية، والقارر 221 لسنة
5102 بشأن إصدار وتوزيع وثائق التأمين النمطية اإللكترونية.
36

•
يجب على شركات التأمين أن تفصح كتابة - وبخط واضح وفي مكان بارز ومرئي، في كافة العقود والمكاتبات
واإلعالنات والمطبوعات مع العمالء - عن خضوعها لرقابة الهيئة العامة للرقابة المالية مع توضيح رقم
الترخيص والسجل التجاري ، وأيض ا اإلدا رة المختصة لديها للتعامل مع شكاوى وتظلمات العمالء وكيفية التواصل
ً
المباشر معها عن طريق رقم هاتفى مخصص للشكاوى . ويجب إحاطة العمالء كتابة عن حقهم في اللجوء إلى
اإلدارة المختصة بالهيئة إذا لم يقبلوا التسوية المعروضة عليهم من قبل إدارة الشكاوى الخاصة بشركات التأمين.
(02)
ب. شروط الدعاية واإلعالن
تلتزم شركات التأمين، في مجال الدعاية واإلعالن، بما يلي:
•
التواصل مع عمالئها باستخدام أي وسيلة من وسائل االتصال التي يختارها العمالء مثل: البريد اإللكتروني،
البريد المسجل، الرسائل النصية، تطبيقات الهاتف الجوال، الخط الساخن. وللشركات استخدام قنواتها الرئيسية
(الفروع، والم واقع اإللكترونية)، وكذلك استخدام قنوات اإلعالم العامة المرئية والمسموعة والمقروءة لتسويق
منتجاتها باستخدام األساليب اإلعالنية والدعائية والتسويقية التي ت ارها مناسبة للش ارئح المستهدفة، وبما يتماشى
مع األنظمة واللوائح والتعليمات والقواعد الصادرة من الهيئة.
•
أن يتسم المحتوى التسويقي واإلعالني للمنتجات أو الخدمات التأمينية بالشفافية والصدق واألمانة والدقة، وأال
يشوبه أي تضليل.
•
توخي الحذر عند إرسال إشعا ارت أو إعالنات للعمالء عن طريق البريد اإللكتروني أو أي وسائل اتصال
أخرى ؛ للتحقق من عدم احتواء اإلشعا ارت المرسلة على معلومات شخصية تخص العمالء.
•
اتباع األساليب المهنية، وأن ت ارعي في كل إعالن يصدر الصدق في شكله ومضمونه، بحيث ت ارعي دقة
البيانات وعرضها بأسلوب صحيح وواضح. ويجب أن تكون كافة العبا ارت واألرقام المستخدمة واضحة ودقيقة
وسهلة الفهم وبخط مقروء.
•
أن تتناسب المواد التسويقية مع الفئة العمرية والثقافية والمادية لكل عميل.
•
أن توضح المادة التسويقية - أثناء الدعاية - الجهة اإلدارية والرقابية التابع لها شركات التأمين، وكافة
التفاصيل األخرى مثل: رقم الترخيص، والسجل التجاري.
(02) مادة 84 مكرر/ 1/ من الالئحة التنفيذية لقانون رقم 01 لسنة 1891 بشأن اإلشارف والرقابة على التأمين في مصر.
46

ج. يحظر على شركات التأمين ما يلى:
•
تقديم أي عروض، أو نشر بيانات أو ادعاءات كاذبة، أو استخدام عبا ارت من شأنها أن تخدع أو تضلل
العمالء بطريقة مباشرة أو غير مباشرة.
• عرض إعالن يتضمن عالمة تجارية ال تخص الشركات وبدون وجه حق في استعمالها.
•
عرض إعالنات تسويقية غير صحيحة أو مضللة للجمهور، سواء كان ذلك متعلًق ا باألسعار، أو أوضاع
الشركات المالية، أو تصنيفها من جهة غير معترف بها، أو غير ذات اختصاص، بما يضلل العمالء.
•
استخدام صيغ المبالغة في كتابة م ازيا تأمينية أو مالية أو أية مز ية تتعدى شروط الوثائق، أو إصدار بيانات
َ
مضللة بخصوص إب ارم رهون أو قروض بضمان الوثائق.
•
حذف أية معلومات مهمة، أو استخدام أية ألفاظ أو عبا ارت أو بيانات توضيحية أو أسماء أو عناوين أو
أوصاف على ال وثائق من شأنها تضليل حملة الوثائق والعمالء المرتقبين أو خداعهم، فيما يتعلق بطبيعة أو
مدد الم ازيا المدفوعة أو نطاق التغطية التأمينية أو األقساط المقر رة أو أي تبعات ضريبية على ذلك.
د. خدمة العمالء ما قبل البيع
يجب على شركات التأمين أن تلتزم باآلتي:
•
تقديم المعلومات الكافية لعمالئها، عندما تقوم بمهمة التواصل مع العمالء؛ بهدف تقديم العروض والمنتجات
التأمينية، والتي تحتوي على الحد األدنى التالي:
− معلومات عن نشاط الشركات وما إذا كان الوسطاء (شركات أو أشخاص طبيعي ون أو مندوب وهم)، يعمل ون
لمصلحتهم مباشرة أو لمصلحة شركات تأمين أخرى أو يعمل ون بشكل مستقل.
−
إبالغ العمالء بأية عالقة مالية بين الوسطاء وشركات التأمين بخالف اتفاقيات العمولة المتعارف عليها،
على سبيل المثال، إذا كانت هناك أية ملكية أو مصلحة مشتركة لدى الطرفين.
−
معلومات عن طبيعة ونطاق المنتجات والخدمات التأمينية التي يمكن أن تقدمها الشركات.
•
أن تسعى للحصول على قدر معقول من المعلومات عن العمالء لتقدير احتياجاتهم من المنتجات والخدمات
التأمينية، وتقديم العروض المالئمة الحتياجات كل عميل.
56

•
تقديم المشورة والتوصية للعمالء في اختيار الخدمات والمنتجات التأمينية المالئمة والملبية الحتياجاتهم
وقد ارتهم المالية بشك ل كا ف .
•
عند تقديم مشورة تتعلق باستبدال وثائق التأمين، يجب توضيح مقدار الزيادة في المصروفات األولية وتبريره،
وإيضاح اآلثار المالية المترتبة على العمالء عند استبدال الوثائق.
(12)
ه. مواصفات وثائق التأمين:
تلتزم شركات التأمين عند إصدار وثائق التأمين، باآلتي:
•
م ارعاة كتابة كافة البيانات بأسلوب سهل وبسيط وواضح، والبعد عن استخدام المصطلحات الغامضة أو
المجحفة أو التي تثير الشكوك.
•
م ارعاة أن تتضمن الوثائق كافة األحكام المنظمة للعالقة بين األط ارف (الشركات المؤمنة والمؤمن لهم أو
المستفيدين)، باإلضافة إلى م ارعاة الوصف الدقيق لكافة التفاصيل الخاصة بالتغطية التأمينية، وقيمة مبلغ
التأمين بشكل واضح وصريح، وفي حالة وجود شرط بنسبة التحمل يجب إيضاحه وتحديد قيمته.
•
م ارعاة إيضاح كافة اإلج ارءات التي يتعين على المؤمن لهم أو المستفيدين اتباعها عند وقوع الخطر
المؤمن ضده، وكيفية حص ول المؤمن لهم على مستحقاتهم من الشركات المؤمنة.
•
م ارعاة طبيعة العالقة بين المؤمن لهم والمستفيدين، والتحقق بدقة من توافر المصلحة التأمينية للمستفيدين
(22)
عند إب ارم العمليات التأمينية الكبيرة، وكذا العمليات التأمينية التي ليس لها هدف اقتصادي وقانوني واضح.
•
بالنص ص ارحة في وثيقة التأمين على شروط إلغاء أو تخفيض أو تصفية وثيقة التأمين إذا كانت من
(32)
النوع الذي له قيمة تصفية.
•
يجب أن تتضمن الوثائق ش ر وط جواز اللجوء للتحكيم لفض أي ن ازع ينشأ بين األط ارف، باإلضافة إلى كتابة
الش ر وط الخاصة بسقوط حق المؤمن لهم في مبلغ التأمين وحاالته بخط واضح وبارز مقروء وسهل الفهم.
