تقديم معلومات وافية لعمالئها عن وثائق التأمين التي تتضمن المشاركة في األرباح (سواء كانت تأمينات
حياة أو تأمينات تكافلية) أو مرتبطة بوحدات استثما رية، من حيث كيفية المشاركة في األرباح، ومبالغ
التغطيات التأمينية، والعوائد المالية، والمخاطر المحتملة، وأية معلومات تخص تلك الوثائق، وبما يحقق
الفهم الكامل للعمالء عن المنتجات التأمينية المقدمة.
• يحق لكافة العمالء الحصول على المنتجات التأمينية المطلوبة. ويجب أن يكون لدى شركات التأمين أسباب
مقنعة لرفض أو إلغاء أو عدم قبول تجديد التأمين، وال يعد ق ارر الشركات األخرى لوحده سبب ا مقنع ا لذلك.
ً ً
•
تقديم كافة مستندات وثائق التأمين للعمالء فو ار وبعد إب ارم تلك الوثائق.
ً
76

و. خدمة العمالء بعد البيع
يجب على شركات التأمين:
• أن تقوم - بعد بيع المنتجات التأمينية - بتقديم الخدمات للعمالء في أوقات وطرق مناسبة، بما في ذلك
الرد على استفسا ارتهم وطلباتهم اإلدارية، واألمور األخرى المتعلقة بتعديل شروط وثائق التأمين.
•
ذكر أية تعديالت تتم على وثائق التأمين كتابة، باإلضافة إلى أية مبالغ إضافية مستحقة على المؤمن
لهم نتيجة هذه التعديالت.
•
سرعة إرسال إشعا ارت للعمالء بأي تغيي ارت في اإلفصاح أو الشروط المعدة للعمالء عند إب ارم وثائق
التأمين، أو تغيي ارت في بيانات االتصال بالشركات أو إج ارءات تقديم المطالبات، وذلك كله في توقيتاتها
المناسبة، وبالطريقة التي تناسب كافة العمالء.
•
إرسال إشعا ارت للعمالء بت واريخ تجديد أو انتهاء وثائقهم التأمينية قبلها بفترة كافية.
•
أن تضمن الحفاظ على أموال العمالء نيابة عنهم وفق الضوابط المعمول بها، وذلك عند تقسيط مبلغ
التأمين على العمالء.
(42)
ز. حسن إدارة وحماية حسابات العمالء
يجب على شركات التأمين:
•
استيفاء البيانات والمستندات التفصيلية الموضحة عن عمالئها أو من ينوب عنهم، مع م ارعاة التحديث
المستمر لهذه البيانات، واالحتفاظ بسجالت بيانات تحديد هوية العمالء خاصة المقيمين خارج البالد، وفًق ا
لمتطلبات المادة (84) مكرر (11) من الالئحة التنفيذية للقانون رقم (01) لسنة 1891. (52)
•
أن يحصل المؤمن لهم على كش وف حساب دورية موضح بها قيم ما لديهم من وثائق وأصول أو استثما ارت.
كما يجوز للمؤمن لهم االعت ارض خالل فترة محددة بكشوف الحساب (خالل 51 يوم ا من تاريخ استالمهم)،
ً
ويجوز للمؤمن لهم خاللها االعت ارض عما ورد من بيانات بكشف حسابهم، من خالل طرق محددة سلًف ا
(62)
عند التعاقد.
