•
أن تقوم بإخطار العمالء بم واعيد تجديد وثائق التأمين الخاصة بهم، وأن يتم ذلك قبل حلول موعد انتهاء
الوثائق القديمة بفترة كافية ال تقل عن 03 يوم ا. وفي حالة عدم رغبة الشركات في تجديد الوثائق، فيجب
ً
(72)
أن يتم إخطار العمالء مسبًق ا وبفترة معقولة عن أسباب عدم التجديد.
