إخطار العمالء في نهاية كل سنة تأمينية بموقف وثائقهم من حيث معدل األرباح المضافة على حساباتهم
االستثما رية أو على مبالغ تأمينهم، أو حصتهم من فائض صندوق التأمين كما في التأمين التكافلي.
ح. إلغاء أو تصفية وثائق التأمين
تلتزم شركات التأمين باآلتي:
•
عدم إلغاء أو تصفية التأمين ساري المفعول، ما لم يكن ذلك بطلب من العمالء أنفسهم، أو ما لم تنص
وثائق التأمين على شروط اإللغاء أو التصفية.
•
ما لم تنص وثائق التأمين على شروط اإللغاء أو التصفية – تلتزم برد جزء نسبي من قيمة األقساط أو
االشت اركات (التأمين التكافلي) المدفوعة عن المدة غير المنقضية من التأمين الملغي، كما ينبغي عليها
تزويد العمالء بمبرارت اإللغاء كتابي ا، باإلضافة إلى وصف طريقة استرداد أقساط أو اشت اركات التأمين
ً
(التأمين التكافلي) المستحقة للمؤمن لهم عند إلغاء أو تصفية وثائق التأمين.
•
ما لم تنص وثائق التأمين على شروط اإللغاء أو التصفية، يحق للمؤمن لهم إلغاء أو تصفية التأمين،
واسترداد جزء نسبي من األقساط أو االشت اركات (التأمين التكافلي) المدفوعة عن المدة غير المنقضية من
التأمين الملغي.
•
يجوز لشركات التأمين إلغاء وثائق التأمين في حالة عدم سداد المؤمن لهم، أو تخلفهم عن سداد األقساط
(82)
أو االشت اركات (التأمين التكافلي) الخاصة ب وثائقهم وتجاوزهم المدة المحددة لذلك ضمن شروط الوثائق.
• يجب أن تكون هناك أسباب مقنعة إللغاء التأمين، وعلى شركات التأمين أن تقوم بإج ارء معاينات دورية
لمحل التأمين؛ بحيث تتناسب التغطيات التأمينية مع قيمته الحقيقية، وعليها متابعة تنفيذ المؤمن لهم
للتوصيات وتدابير الوقاية التي ترد في تقارير المعاينة، وفي حالة امتناعهم عن ذلك تقوم الشركات بإلغاء
(92)
وثائق التأمين.
