ط. تحديد السعاروالعموالت
يجب على شركات التأمين:
•
االلتازم عند التسعير بمارعاة األسس الفنية السليمة والمعتمدة من الهيئة العامة للرقابة المالية عند تسعير الوثائق.
•
أن تقوم بإخطار الهيئة باألسعار المقترحة مرفًق ا بها بيان مفصل باألسس اإلكتوارية التي استندت إليها
في تحديد هذه األسعار، وذلك خالل فترة ال تقل عن ثالثين يوم ا قبل بدء تطبيقها لم ارجعتها وفًقا للمعايير
ً
الفنية واإلكتوارية.
• أن تقدم للهيئة ط رق التسعير التي سبق للعمالء الموافقة عليها كجزء من طلبات الموافقة على المنتجات
والخدمات التأمينية.
(13)
ي. مطالبات العمالء لشركات التأمين
ما يجب على شركات التأمين:
• في حالة وقوع الخطر، يلتزم المؤمن لهم أو المستفيد ون من وثائق التأمين بإخطار شركات التأمين بذلك،
وبطلب التعويض خالل عشرة أيام عمل من تاريخ وقوع الخطر أو علمهم به، ما لم ينص في الوثائق
على ميعاد آخر.
•
تسوية المطالبات بشكل سريع، ويجوز لهم رفض المطالبات أو قبولها بحد أقصى شهر من تاريخ استالم
المطالبات مكتملة المستندات واألسانيد الكافية المتعلقة بها، مع بيان أسباب الرفض كتابيا.
ً
•
تقديم إرشادات وتوجيهات للعمالء عند تقديم المطالبات، وتزويدهم بمعلومات كافية عن اإلج ارءات المتبعة
إلتمام عملية تسوية المطالبات. وتلتزم الشركات بتقديم نموذج ألصحاب المطالبات أو من يمثلهم، على
أن يشمل جميع البنود والبيانات الالزمة ومكان إدارة المطالبات بها وأرقام وثائق التأمين وأرقام المطالبات،
وما يشير ص ارحة إلى حق العمالء في اللجوء إلى الهيئة في حالة عدم رضائهم عن تسوية المطالبات،
وكيفية الوصول إلى إدارة الشكاوى بالهيئة، وأن يكون كل ذلك بصورة مكتوبة.(23)
