•
تعيين خب ارء معاينة أو مقد ري أض ارر متى تطلب األمر. ويجب إخطار العمالء أو المستفيدين بهذا
اإلج ارء، حيث يجب البدء في فحص أي مطالبة خالل خمسة عشر يوم ا من تاريخ استالم المطالبة. وفي
ً
حالة االستعانة بخب ارء لتقدير حجم الضرر، فإن عليهم تقديم تقارير نهائية خالل ثالثين يوم ا من تاريخ
ً
المطالبة، ما لم ي نص على خالف ذلك.
•
إرسال إشعا ارت كتابية للعمالء أو المستفيدين بقبول أو رفض المطالبات. وفي حالة الرفض الكلي أو
الجزئي، يتعين على الشركات أن تبدي أسباب رفض المطالبات بوضوح وشفافية، وأن تسلم العمالء أو
المستفيدين كافة المستندات المتعلقة بالمطالبات.
•
عند قبول المطالبات، يتم توضيح اآللية التي تم من خاللها التوصل إلى مبلغ التسوية، وتقديم المبرارت
الالزمة حال تخفيض أو عدم قبول جزء من المطالبات.
• دفع مبالغ المطالبات حال صحتها بدون تأخير غير مبرر وفًقا ألحكام القانون.
•
االحتفاظ بملف خاص بكل المطالبات يضم كافة الم ارسالت والعمليات والتقارير، سواء الطبية أو تقارير
المعاينة وتقدير األض ارر أو أية تقارير أخرى والمالحظات، وأي مستندات أخرى ذات صلة لتيسير عمليات
الرقابة والفحص.
•
وضع إج ارءات محددة الستقبال مطالبات عمالء التأمين متناهي الصغر ود ارستها وإنهائها خالل عشرة
أيام عمل من تاريخ استيفاء المستندات المطلوبة.
كما يجب على الشركة االحتفاظ بملفات خاصة بمطالبات العمالء وتقسيمها إلى تعويضات مسددة،
وتعويضات تحت التسوية، وتعويضات مرفوضة، ويجب أال تتجاوز مدة تسوية المطالبات المغطاة المدة
(33)
المنصوص عليها في الوثائق.
