(43)(53)
المبدأ الثاني: السلوك والكفاءة المهنية
تلتزم شركات التأمين في مجال السلوك والكفاءة المهنية بما يلي:
• أن يتمتع العاملون بشركات التأمين بحسن السير والسلوك، وعدم التورط أو اال تهام في أي ج ارئم مخلة
بالشرف والمانة، أو سوء التصرف أو التعثر المالي، وأيضا خلو ملفاتهم من أي ج ازءات بسبب عدم تنفيذ
ً
مسئولياتهم الوظيفية بدقة والت ازم.
• أن يتمتع العاملون بشركات التأمين بالكفاءات المهنية، والحصول على التدريبات الالزمة، وأن تكون
لديهم الخب ارت الالزمة التي تؤهلهم لمباشرة اختصاصاتهم الوظيفية على أكمل وجه.
•
أن يتمتع وسطاء التأمين ومسئولو المبيعات بأعلى درجات الكفاءة والمهنية والشفافية ليتمكنوا من أداء
دورهم على أكمل وجه لجذب العمالء، وإقناعهم بأهمية المنتج التأميني ومساعدتهم في اختيار ما يناسب
احتياجاتهم التأمينية.
• التنافس في تقديم أفضل المنتجات والخدمات والسعار بما يلبي احتياجات العمالء التأمينية، دون إخالل
بما تقتضيه األنظمة واللوائح والتعليمات المتعلقة بأسس وطريقة تسعير المنتجات التأمينية.
•
ممارسة وأداء أعمالهم بأسلوب مهني مسئول لتحقيق أفضل مصلحة للعمالء في كافة مارحل تعاملهم مع
الشركات باعتبارها مسئولة عن حماية العمالء فيما يقدم إليهم من خدمات ومنتجات مالية، ويأتي على قمة
هذه السلوكيات الن ازهة والمصداقية والتحقق من توافق المنتجات والخدمات المقدمة للعمالء مع قد ارتهم المالية
واحتياجاتهم التأمينية.
•
التأكد من توافر المؤهالت العلمية والكفاءات والمهاارت الالزمة، باإلضافة إلى التدريب المالئم والمستمر
للعاملين، خاصة الذين يتعاملون مع العمالء ويقدمون لهم المنتجات والخدمات التأمينية. ويجب التأكد من
فهم وإلمام واستيعاب العاملين بالشركات للمنتجات والخدمات التأمينية المقدمة للعمالء.
(43) مادة 84 مكرر/71/ومواد 721، 921، 031، 231، 331 من الالئحة التنفيذية للقانون رقم 01 لسنة 1891 بشأن اإلشارف والرقابة على التأمين في
مصر.
(53) الكفاءة المهنية: هي القدرة على القيام بالمهام الوظيفية التنظيمية بصورة تتفق ومعايير تقديم الخدمات التي ترتبط بهذه المهنة، وفي التوقيتات المناسبة لها،
وتقديم النصح واإلرشاد الالزمين لمتلقي الخدمة بما يساعده على معرفة حقوق والتازماته. وكذا االلتازم بمعايير أداء الخدمات المرتبطة بنشاط التأمين والواردة
بالالئحة التنفيذية للقانون رقم 01 لسنة 1891، بشأن اإلشارف والرقابة على التأمين في مصر.
27

• تقييم مستوى الكفاءة المهنية لوسطاء التأمين من خالل تقارير تقييم دورية تعد من اإلدارة المسئولة داخل
شركات التأمين، وتتضمن معرفة أري العمالء وتقييمهم لمستوى الخدمات المقدمة من جانب وسطاء
التأمين، وعما إذا كان تم إطالعهم على كافة التفاصيل والمعلومات الواجب توافرها لدى المؤمن لهم.
•
التأكد من عدم ممارسة وسطاء التأمين لعملهم قبل الحصول على ترخيص مازولة مهنة الوساطة،
واسيتفائهم كافة المتطلبات والشروط المهنية المطلوبة، باإلضافة إلى االهتمام بتنمية قد ارتهم المهنية عن
طريق التدريب المستمر، وكذلك تقييمهم عن ط ريق اختبا ارت الكفاءة المهنية المتعارف عليها، ومن خالل
توافر نظم الرقابة الداخلية الفعالة.
•
إلازم العاملين لديها بقواعد السلوك المهني في أداء دورهم والعمل بطريقة مهنية وبأسلوب مسئول، وأن
تكون هناك قواعد مكتوبة وصادرة من مجلس إدارة الشركات.
• حظر استقطاب العاملين بشركات التأمين لعمالئهم حال االنتقال بين الشركات العاملة بالسوق ، بما قد يضر
بمصالح العمالء وقد ارتهم على السداد، وكذا يؤثر على سالمة الم اركز المالية للشركات.
•
القيام بواجباتها والتازماتها وتقديم خدماتها بأعلى جودة وفي توقيتات مناسبة لمصلحة العمالء والمستفيدين
على طول امتداد العالقة فيما بينهم، حيث تعتبر الشركات هي المسئولة عن حماية مصالح عمالئها التأمينية.
•
أن يتوافر في الموظفين ومسئولي بيع الخدمات والمنتجات التأمينية المؤهالت والكفاءات الالزمة التي
تتناسب مع درجة صعوبة وتعقيد المنتجات والخدمات المقدمة للعمالء.
•
أن يلتزم وسطاء التأمين ببذل جهود فعالة لتقديم خدمات تأمينية تناسب احتياجات العمالء التأمينية
وقدرتهم المالية.
•
تدريب الوسطاء والعاملين المعنيين بجهات التوزيع اإللكتروني على آليات التعامل مع وثائق التأمين
المصدرة إلكتروني ا وما يرتبط بذلك من خدمات للمؤمن عليهم وتزويدهم باإلرشادات الالزمة، وذلك بما يحقق
ً
63
فهم متطلباتهم ويعزز الشفافية والوضوح ويزيد من وعي المتعاملين.
• التأكد من أن العاملين من ذوي العالقة بالعمالء والمستفيدين على إلمام كامل بأفضل الممارسات المهنية
في مجال تقديم الخدمات لعمالء شركات التأمين، سواء التي تصدر من خالل الهيئة للمهن المرتبطة أو
من خالل االطالع على التجارب الدولية في هذا الشأن.
