المبدأ ال اربع: حماية خصوصية وسرية حسابات وبيانات العمالء
تلتزم شركات التأمين في مجال خصوصية وسرية حسابات وبيانات العمالء بما يلي:
•
حماية بيانات وحسابات المؤمن لهم المالية والتأمينية والشخصية، وعدم استخدامها إال ألغ ارض مهنية
محددة ومرتبطة بالعمليات التأمينية، وعدم الكشف عنها إال بموافقة المؤمن عليهم، باستثناء األحوال التي
تقضي بإل ازمها بالكشف عن تلك البيانات دون الحاجة إلى موافقة المؤمن عليهم على ذلك وفًقا للقوانين
الحاكمة في هذا الشأن، كما في حالة الدعاوى المرفوعة أمام القضاء، أو في حاالت العرض على لجان
فض المنازعات على سبيل المثال.
• أال تفصح عن أية معلومات تخص أي من عمالئها ألي طرف ثالث دون تصريح مسبق من الهيئة،
باستثناء م ارقبي حسابات الشركات والخب ارء اإلكتواريين وشركات إعادة التأمين المشتركة.
•
اتخاذ اإلج ارءات المناسبة وتفعيل األنظمة الرقابية واستخدام التكنولوجيا الحديثة؛ لحماية قواعد بيانات
العمالء والمستفيدين واكتشاف ومعالجة التجاوازت التي حدثت أو المتوقع حدوثها.
•
اتخاذ كافة التدابير واإلج ارءات األمنية الالزمة لحماية المعلومات المتبادلة إلكتروني ا مع العمالء، وتوفير
ً
أحدث التقنيات والب ارمج لضمان حماية وسالمة عمليات الدفع اإللكتر وني.
•
االلت ازم بالضوابط التكنولوجية وقواعد تأمين المعلومات المرتبطة بإصدار وتوزيع شركات التأمين لبعض
(04)
وثائق التأمين النمطية اإللكترونية من خالل شبكة نظم المعلومات.
•
إدارة كافة المخاطر التي قد يتعرض لها العمالء نتيجة تقديم المنتجات والخدمات التأمينية بوسائل إلكترونية.
•
تحمل أية أض ارر أو خسائر قد تلحق بالعمالء بسبب وقوع خلل في األنظمة لدي شركات التأمين أوعمليات
االحتيال أو االخت ارق التي قد تحدث ألي سبب كان، بخالف ما وقع نتيجة لتقصير من جانب العمالء.
•
أن تتخذ كافة اإلج ارءات الالزمة لحماية وثائق التأمين المصدرة إلكتروني ا، ضد التزوير والتالعب عن طريق
ً
طباعة (عالمات مائية- شعا ارت بار زة.. الخ) مع االلت ازم بضوابط إصدار وثائق التأمين اإلجباري الصادرة
عن الهيئة بكتابها الدوري المؤرخ 21/11/9002، وما يصدر عن الهيئة تباع ا من ضوابط في هذا الشأن،
ً
واتخاذ إج ارءات حماية البيانات من خالل الوسائل التكنولوجية الحديثة.
