المبدأ الخامس: تسوية الن ازعات ومعالجة شكاوى العمالء (14)
تلتزم شركات التأمين في مجال تسوية النازعات ومعالجة شكاوى العمالء بما يلي:
أ. التعامل مع الشكاوى داخلي ا
ً
•
توفير آلية مناسبة للعمالء لتقديم الشكا وى ، تتسم بالفعالية والعدالة والوضوح، ويمكن من خالل تلك اآللية متابعة
ومعالجة الشكاوى دون تأخير، وفًقا لألنظمة واللوائح والتعليمات الصادرة عن الهيئة والجهات ذات العالقة.
•
إخطار العمالء باإلج ارءات التي تم اتخاذها في سبيل فحص شك واهم.
•
إنشاء ملفات لفحص أي شكا وى ترد إليها، وتودع فيها كافة األوارق والمستندات المتعلقة بالشكا وى.
• تسوية الشكاوى بكل ن ازهة وعدل ودون تمييز، وأن يتم البت فيها بحد أقصى خالل ثالثين يوم ا من تاريخ
ً
ورودها، وتصدر الق ار ارت إما بالقبول أو بالرفض مع ذكر السبب في حالة الرفض.
•
أن تخطر الهيئة بأسباب رفض الشكاوى سواء كان كلي ا أو جزئي ا لطلبات الشاكين.
ً ً
• شرح إج ارءات تقديم الشكاوى إذا لم يقبل العمالء أو المستفيد ون التسوية التي تم إج ارؤها، ومنها توجيههم
إلى إدارة الشكاوى بالهيئة.
•
توفير إدارة لتقديم الشكاوى في مكان معلوم لكافة عمالئها، وإد ارجها على م واقع الشركات اإللكترونية، وتوفير
نسخة للعمالء حال رغبتهم في الحصول عليها مكتوبة، ويجب أن يتضمن الموقع بيان ا تفصيلي ا يوضح
ً ً
اإلج ارءات التي تقوم بها الشركات أو الوسطاء في حالة وجود شكاوى للعمالء، مع توضيح أحقية العمالء
(24)
في التقدم للهيئة بالشكاوى حال عدم التوصل لحلول ترضي أصحاب الشكا وى.
•
عند تلقي شكاوى العمالء والمستفيدين، تلتزم الشركات بالقيام بالتالي:
−
اإلق ارر كتابة باستالم الشكا وى.
−
تزويد العمالء أو المستفيدين بمرجع االتصال لمتابعة الشكا وى المقدمة.
(14) مادة84 مكرر/ 7/ من الالئحة التنفيذية لقانون رقم 01 لسنة 1891 بشأن اإلشارف والرقابة على التأمين في مصر.
(24) قارر رقم 508 لسنة 6102 بشأن ضوابط المواقع اإللكترونية لشركات ووسطاء التأمين أو إعادة التأمين على شبكة المعلومات الدولية.
77

−
إبالغ العمالء أو المستفيدين كتابي ا، وبطريقة االتصال التي تناسب ظروف تواجدهم، بما تم في الشكاوى
ً
المقدمة منهم.
−
تسوية الشكاوى بشكل سريع وعادل، خالل مدة ال تتجاوز 03 يوم ا من تاريخ استالم الشكا وى.
ً
−
إشعار العمالء أو المستفيدين خطي ا بقبول الشكاوى أو رفضها وتوضيح األسباب الداعية لذلك، وأية
ً
تعويضات معروضة للعمالء للتسوية إن وجدت، وتوضيح أسباب االختالف في قيمة التعويضات
المعروضة على العمالء عن الواردة بشروط الوثائق.
ب. التعامل مع الشكاوى خارجي ا
ً
•
بخالف ما تقدم، إذا لم يوافق العمالء على النتائج النهائية التي توصلت إليها إدارة الشكاوى بشركات التأمين،
يحق للعمالء اللجوء لوسائل أخرى مثل اإلدارة المختصة بالشكاوى بالهيئة أو م اركز التحكيم المختصة بتسوية
الن ازعات االقتصادية والتأمينية، والتي يجب أن يكون منصوص ا عليها في العقود المبرمة أو في القانون .
ً
•
وفي جميع األحوال واألوقات، للعمالء الحق في اللجوء للقضاء، وهو الجهة الفاصلة والنهائية للفصل في
أي ن ازع ينشأ بين األط ارف.
المبدأ السادس: سبل الضمانات والتعويضات
أ. بالنسبة لقطاع التأمين هناك إجارءات محددة لحماية العمالء وحملة الوثائق، من خالل اآلليات التالية:
• صندوق ضمان حملة الوثائق و/ أو المستفيدين منها لدى شركات التأمين:
وافق مجلس إدارة الهيئة بتاريخ 03/7/8102 على إنشاء صندوق ضمان حملة الوثائق و/أو المستفيدين منها لدى
شركات التأمين المسجلة بالهيئة العامة للرقابة المالية. ويهدف الصندوق - وفًقا ألحكام نظامه األساسي - إلى
تعويض حملة الوثائق و/أو المستفيدين منها من عمالء الشركات األعضاء بالصندوق في الحاالت الناشئة عن
عدم قد رة هذه الشركات على الوفاء بالت ازماتها تجاه حملة الوثائق والمستفيدين منها، وذلك في حالة إلغاء الترخيص
أو شطب التسجيل أو الحكم بإشهار اإلفالس أو التصفية، وبعد ثبوت أن أصول وموارد الشركات غير كافية للوفاء
بكامل الت ازماتها قبل حملة الوثائق والمستفيدين منها، على أن تكون التغطية بحد أقصى 08% من قيمة التعويض
للوثيقة الواحدة، وذلك بعد خصم أية الت ازمات على العميل من قبل العضو. ويجوز للصندوق تعويض عمالء
أعضاء الصندوق من خالل تحويل وثائقهم بذات الشروط واألوضاع لشركة أخرى مرخص لها بم ازولة نشاط التأمين
في مصر، شريطة موافقة الشركة المحال إليها على ذلك، وبصفة خاصة الوثائق طويلة األجل.
87

•
تحديد القواعد والسس الفنية التي تحكم حساب المخصصات الفنية لحملة وثائق التأمين، وذلك على
وجه محدد بالقانون رقم 01 لسنة 1891 والئحته التنفيذية:
تتضمن كافة أنواع المخصصات واالحتياطيات الفنية سواء لشركات تأمينات األشخاص أو شركات تأمينات
الممتلكات والمسئوليات والمطلوبة لوفاء تلك الشركات بالت ازماتها تجاه حملة الوثائق و/أو المستفيدين منها، والتي
تضمنت أيض ا مخصص ا لمواجهة أي تقلبات عكسية في نتائج أنشطة شركات التأمين.
ً ً
ب. التازمات هامة تخص عمالء شركات التأمين
•
اإلفصاح عن كافة المعلومات بصدق
−
يلتزم العميل بتقديم كافة المعلومات وبشكل دقيق مع اتباع مبدأ منتهى حسن النية عند استيفاء أي
نماذج تطلبها الشركات، واالمتناع عن تقديم أي معلومات مضللة أو خاطئة أو غير مكتملة أو عدم
اإلفصاح عن المعلومات الهامة أو الجوهرية.
− يجب أن يكون العمالء على د ارية بأن تقديم أية معلومات غير صحيحة في طلبات التأمين قد يؤدي
إلى بطالن التأمين.
•
قارءة كافة المعلومات التي قدمتها الشركات بدقة
يتم تسليم العمالء معلومات وافية بشأن الت ازماتهم، مقابل حصولهم على المنتجات والخدمات التأمينية. ويجب على
العمالء االطالع على تلك االلت ازمات والتأكد من فهمهم لها بشكل واضح وقدرتهم على االلت ازم بها.
•
طرح السئلة
في حالة عدم وضوح أي بند أو شرط في وثائق التأمين أو أي من المستندات المقدمة من قبل الشركات، فإنه يحق
للعمالء االستفسار عنها، وطرح األسئلة على موظفي الشركات، كما يجب على موظفي الشركات اإلجابة على تلك
األسئلة بأسلوب مهني واضح يساعد العمالء على اتخاذ الق ار ارت المناسبة.
•
التأكد من البيانات الواردة بوثائق التأمين
التأكد من أن النسخ المصدرة لوثائق التأمين تشمل كافة محتويات الوثائق، ومن ذلك - على سبيل المثال ال
الحصر- البيانات الشخصية، وتاريخ سريان التغطية التأمينية، وشروط التأمين، وبصفة خاصة شروط التصفية
واإللغاء، وحدود واستثناءات التغطيات ومالحق الوثائق.
97

• معرفة كيفية تقديم الشكاوى
سوف توفر الشركات المعلومات والبيانات الالزمة بشأن آلية تقديم الشكاوى ، مثل أرقام وعناوين االتصال لتقديم
الشكاوى ومتابعاتها، واإلطار الزمني لموافاة العمالء بالنتائج. ويجب على العمالء استخدام تلك الخدمات عند
الحاجة ومعرفة كيفية رفع الشكاوى إلى الهيئة عند الضرورة.
•
استخدام الخدمة أو المنتج التأميني بموجب الحكام والشروط
يجب على العمالء عدم استخدام المنتجات والخدمات التأمينية إال وفًقا لألحكام والشروط الموضحة في وثائق
التأمين، وذلك بعد التأكد من فهمها بشكل كامل.
•
عدم التعرض للمخاطر
تحتوي بعض الخدمات والمنتجات التأمينية على مستويات متفاوتة من المخاطر، وينبغي على الشركات شرحها
بوضوح للعمالء. ويجب على العمالء تجنب طلب منتجات وخدمات تأمينية عند الشعور أن المخاطر ال تتالءم
مع وضعهم المالي.
•
تقديم طلبات للحصول على المنتجات أو الخدمات التي تتناسب مع احتياجات العمالء
عند تقديم العمالء طلب الحصول على أي من المنتجات والخدمات التأمينية، ينبغي عليهم التأكد من مالءمتها
الحتياجاتهم التأمينية، باإلضافة إلى قدرتهم على الوفاء بااللت ازمات المترتبة على حص ولهم على تلك المنتجات
والخدمات التأمينية.
•
إبالغ الشركات بشأن اإلجارءات غير النظامية
عند اكتشاف العمالء أي إج ارءات غير نظامية تمس المنتجات والخدمات المقدمة لهم، يجب عليهم إبالغ الشركات
بذلك على الفور، وفي حالة عدم تجاوب الشركات فإنه يحق لهم التقدم بشك واهم إلى الهيئة.
•
إستشا رة الشركات عند مواجهة أي صعوبات
يجب على العمالء استشارة الشركات التي يتعاملون معها عند مواجهة صعوبات مالية ينتج عنها عدم قدرتهم على
تحمل االلت ازمات الخاصة بالمنتجات والخدمات التأمينية، حتى يستطيعوا مناقشة الخيا ارت المتاحة بما يتناسب مع
وضعهم المالي.
08

•
تحديث المعلومات
ينبغي على العمالء تحديث بياناتهم الشخصية بما فيها بيانات االتصال، ويكون التحديث بشكل مستمر وعندما
تطالبهم الشركات بذلك. وينبغي أن يدرك العمالء بأن عدم تحديث بياناتهم الشخصية، ال سيما الجوهرية منها، قد
يؤدي إلى وقوع مسئولية عليهم أو ضياع حقوقهم.
•
عنوان البريد
يجب أن يستخدم العمالء عناوينهم البريدية (البريد العادي/أو البريد اإللكتروني) وأرقام االتصال الخاصة بهم عند
طلبها من الشركات التي يتعاملون معها، كما يجب أال يستخدم العمالء عناوين أخ رى ال تخصهم كاألصدقاء أو
األقارب، مما قد يؤدي إلى إفشاء معلوماتهم الشخصية.
•
التوكيالت
يجب على العمالء الحذر من إصدار توكيالت عامة ألي أشخاص إلنجاز تعامالتهم التأمينية، واالكتفاء - كلما
كان ذلك ممكن ا - بالتوكيالت الخاصة والمحدد بها نوع التصرف الموكل للشخص الصادر له التوكيل، وعدم التوسع
ً
في منح سلطات أكثر مما تتطلبه العملية التأمينية، وأن يكون مكتوب ا بصورة محددة ليس فيها أي لبس، باإلضافة
ً
إلى الحرص من إعطاء أية معلومات عن وثائق التأمين ألشخاص غير مخول لهم االطالع على تلك المعلومات.
•
عدم التوقيع على نماذج (االستماارت) غير المكتملة
يجب على العمالء التأكد من اكتمال كافة الموضوعات واألرقام المطلوبة في النماذج المقدمة لهم للتوقيع عليها،
وعدم القيام بالتوقيع على أي نماذج فارغة (على بياض) أو غير مكتملة البيانات.
•
مارجعة جميع المعلومات والبيانات
ينبغي على العمالء م ارجعة جميع المعلومات والبيانات التي قاموا بتدوينها في نماذج طلب المنتجات والخدمات
التأمينية؛ لضمان صحة المعلومات المقدمة، والتأكد من عدم وجود أي أخطاء في البيانات المدونة، مع اإلد ارك
بأن توقيعهم على النماذج يعني موافقتهم عليها.
18

•
اإلفصاح عن معلوماتهم الشخصية
- ينبغي على العمالء - تحت أي ظرف من الظروف - عدم اإلفصاح عن أي معلومات شخصية أو تأمينية
ألي طرف آخر غير الشركات التي يتعامل ون معها أو الجهات الرسمية.
- يتعين على العمالء اإلفصاح للشركات عن أي معلومات ذات صلة بالمنتجات والخدمات التأمينية المطلوبة،
والمعلومات الضرورية لتحديد احتياجاتهم التأمينية وتقييم المخاطر التي قد يتعرض ون لها.
ج. أحقية العمالء في الحصول على نسخ من العقود والمستندات الموقعة
ينبغي على العمالء التأكد من حصولهم على نسخ من العقود والمستندات بعد التوقيع عليها والمصدق عليها
والمعتمدة من الشركات واالحتفاظ بها في مكان آمن.
وفيما يتعلق بوثائق التأمين اإللكتروني التي تصدرها الشركات أو فروعها عن طريق البريد اإللكترونى، يكون للمؤمن
لهم الحق في أن يطلبوا من الشركات تزوديهم بنسخ ورقية من وثائق التأمين المصدرة إلكتروني ا وأى مستندات أخرى
ً
لها عالقة بتلك الوثائق، موقعة ومختومة من الشركات، أو أن يطلبوا من الشركات إرسالها لهم عن طريق البريد
المسجل خالل مدة ال تتجاوز سبعة أيام عمل من تاريخ طلب المؤمن لهم.
28

ا
سابع ا: دليل محاية املتعاملني مع صناديق التأمني اخلاصة
المبدأ الول: اإلفصاح والشفافية
أ. تلتزم صناديق التأمين الخاصة باإلفصاح والشفافية مع أعضائها، وبصفة خاصة فيما يلي:
•
عرض كافة المعلومات الرئيسية عن أنظمة صناديق التأمين الخاصة بلغة سهلة وواضحة متضمنة أهميتها
ودورها في تأمين المخاطر التأمينية لألعضاء وكذا أحكام نظمها األساسية، مع عدم استخدام مصطلحات فنية
غير واضحة أو غير ضرورية، واستخدام أمثلة توضيحية تتناسب مع مختلف مستويات األعضاء الفكرية والثقافية.
• أن يكون حجم الخط وتباعد المسافات بين الحرف والكلمات واضحة ومقروءة بسهولة للشخص العادي.
•
إيضاح وشرح التفاصيل والمبادئ الرئيسية لم ازيا صناديق التأمين الخاصة لألعضاء كتابي ا بشكل واف
ً
وواضح وصريح ودون أي غموض، مع توضيح الفرق بينها وبين البدائل التأمينية المتوفرة من خالل شركات
التأمين وذلك قبل االنضمام أو االشت ارك في الصناديق.
•
تسليم األعضاء نموذج البيانات األساسية، ويتضمن أهم المعلومات الرئيسية كما يلي:
−
أسماء وأنواع صناديق التأمين الخاصة المتاح لهم االشت ارك بها، على أن تشمل كافة البيانات الخاصة
بمسئولي إدا رة الصناديق وكيفية الحصول على اإلجابات المناسبة ألي استفسا ارت.
−
أهم المخاطر المرتبطة باالشت ارك أو عضوية الصناديق التي قد يتعرض لها األعضاء.
−
كافة المصاريف اإلدارية وأي تكاليف أو اشت اركات سوف يسددها األعضاء.
−
أي اشت اركات أو أي صورة من صور التمويل العينية أو النقدية من جانب جهة أو صاحب العمل،
وتوضيح اآلثار المترتبة على م ازيا واشت اركات أعضاء الصناديق في حالة عدم وفاء جهة أو صاحب
العمل بحصته التمويلية.
−
العوائد أو األرباح السابقة للصناديق، مع ضرورة التنويه على أن العوائد المحققة ليس بالضرورة يمكن
تحقيقها مستقبالً.
− كيفية تحقيق التوازن المالي واإلكتوارى للصناديق ومدى ارتباطه باستم ارر جميع األعضاء في الصناديق
واستق اررهم، وكذلك عالقته بقيمة واستم اررية مساهمة جهة العمل.
38

− نوعية الضمانات المتوفرة من خالل االشت ارك في الصناديق للحفاظ على حقوق األعضاء وم ازياهم،
وعلى سبيل المثال: (وجود هيئة الرقابة المالية التي ت ارقب كافة حسابات وأنشطة الصناديق).
−
السياسات المتبعة، وتبعيات الخروج المبكر من الصناديق، واألسباب التي تؤدي إلى إمكانية خسارة
أرس المال (االشت اركات المسددة سواء بصورة كلية أو جزئية). وأيض ا آليات واشت ارطات إلغاء العضوية،
ً
وما يترتب على ذلك من آثار أي ا كان نوعها.
ً
−
مدى إمكانية االستمارر في عضوية الصناديق في حالة تركهم للخدمة لدى جهة أو صاحب العمل ألي
سبب غير حاالت االستحقاق.
−
شروط وكيفية حساب قيم المازيا عند التصفية الكلية للصناديق.
ويجب أن يوقع العمالء على النموذج بعد قارءة كافة بنوده.
• توفير كافة المعلومات بصورة واضحة تساعد األعضاء - دون اشت ارط مستوى ثقافي وعلمي عا ل - لفهم
المبادئ والمؤش ارت األساسية وتحليل أداء الصناديق، ومتابعة أي تطوارت خاصة بقيمة م ازياهم أو معاشاتهم
أو استثما ارتهم الفردية.
• توقيع طلب االنضمام لعضوية الصناديق يتكون من أصلين (أصل مع الصندوق وأصل مع العضو)، على
أن يتضمن الطلب ما يلى:
−
البيانات الشخصية والوظيفية والمالية (مفردات المرتب، ونسب الخصم الموردة للصناديق وطريقة ت ازيدها
ودورية خصمها).
−
النص ص ارحة في نماذج طلبات االنضمام أو العضوية لصناديق التأمين الخاصة واإلفصاح للعمالء على
أنه توجد فترة سماح مدتها (عشرة أيام عمل) تبدأ من تاريخ تفعيل االنضمام لعضوية الصناديق، إذا لم يتم
تقديم خدمات مالية لهم، وطوال هذه الفترة يسمح لألعضاء بفسخ العضوية والخروج من الصناديق واسترداد
مستحقاتهم بدون توقيع أي شروط ج ازئية عليهم.
ويجوز للصناديق خصم أي مصاريف إدارية تكبدتها إلصدار العقود بشرط أن تكون المصاريف اإلدارية
محددة القيمة ومبررة ومعلنة مسبًق ا لألعضاء قبل التوقيع على العقود.
−
بيانات الصناديق األساسية مثل: العنوان، المركز الرئيسي أو أى فروع أو مكاتب للصناديق، وأسماء
المسئولين عن اإلجابة على أي استفسا ارت خاصة بالعضوية والموقع اإللكتروني أو البريد اإللكتروني
وأي وسيلة أخرى للحصول على أي بيانات للصناديق.
48

−
اإلفصاح كتابة عن خضوعها لرقابة الهيئة العامة للرقابة المالية، مع توضيح رقم الترخيص، وأي ضا
ً
اإلدا رة المختصة لديهم للتعامل مع شكاوى وتظلمات األعضاء وكيفية التواصل المباشر معها عن طريق
رقم هاتفي مخصص للشكاوى . ويجب إحاطة األعضاء كتابة عن حقهم في اللجوء إلى اإلدارة المختصة
بالشكاوى بالهيئة إذا لم يقبلوا التسوية المعروضة عليهم.
− النص على طريقة التواصل التي يرغب بها العضو، على أن تتضمن ثالثة طرق للتواصل على األقل.
•
تقديم المعلومات لألعضاء التي توضح كافة حقوقهم ومسئولياتهم مثل:
−
شروط العضوية واستثناءاتها.
−
االشت اركات والم ازيا االستثما رية أو التأمينية التي تكفلها أنظمة الصناديق، وكذلك الخطط االستثما رية،
وأهم المخاطر، وكافة المصاريف والتكاليف.
−
االختيا ارت المتاحة أمام األعضاء عند تغيير صاحب العمل أو عند الخروج المبكر قبل تاريخ التقاعد.
−
آليات واشت ارطات إلغاء العضوية، وما يترتب على ذلك من آثار أي ا كان نوعها.
ً
وتقدم تلك المعلومات بطريقة واضحة ومختصرة وسهلة الفهم ودقيقة وغير مضللة، بحيث تناسب كافة أنماط
األعضاء، من حيث مستوياتهم الثقافية والتعليمية، وتمكنهم من ق ارءتها دون عناء وتساعدهم على اتخاذ ق ار ارت
االنضمام من عدمها بسهولة ويسر.
•
اإلفصاح لألعضاء عما إذا كانت هناك اختيا ارت أخرى في الم ازيا واالشت اركات، ومتى يحق لهم ممارسة
تلك الخيا ارت والحد األدنى من الم ازيا المضمونة.
•
في حالة وجود ضمانات مرتبطة بالمعاشات، يتم اإلفصاح عن طبيعة الضمانات وقيمتها وكذلك بيانات
تفصيلية عن الضامن، والتكلفة الفعلية لتلك الضمانات، وما إذا كان من حق األعضاء عدم االشت ارك بها،
وتبعيات ذلك من حيث المخاطر والتكلفة.
•
في حالة قيام الصناديق بتقديم عدة م ازيا تأمينية لألعضاء، يتم وضع اآلليات الالزمة لتوضيح كافة
المعلومات الخاصة بكل مز ية تأمينية على حدة أو وضع آليات موحدة لكافة الخدمات؛ وفي جميع األحوال،
تقدم المعلومات بطرق مبسطة وموحدة وقابلة للمقارنة وتسهل عملية االختيار لألعضاء.
•
في حالة صرف الم ازيا التأمينية للتقاعد والعجز يتم تحديد كيفية وتوقيتات صرف الم ازيا، وذلك قبل تاريخ
بدء صرفها بثالثة أشهر على األقل.
58

•
عند استحقاق م ازيا الوفاة يتم صرف الم ازيا المستحقة لألعضاء فى مدة ال تتجاوز 01 أيام عمل من تاريخ
استيفاء المستندات الالزمة، عن طريق إخطار المستفيدين كتابيا موضحا بها كيفية صرف الم ازيا وكيفية
ً ً
تلقي أي شكاوى تخص حقوق المستفيدين.
•
اإلفصاح لألعضاء عن أي تغيي ارت تط أر على إدارة الصناديق ومجلس اإلدارة والقائمين عليها.
•
اإلفصاح لألعضاء عن أي خطط أو مقترحات للدمج مع صناديق أخرى ، على أن يتضمن كافة البيانات
الالزمة التى توضح م ازيا وعيوب الدمج؛ لتسهيل اتخاذ األعضاء للق ارارت السليمة في هذا الشأن.
•
إخطار األعضاء بأي تغيي ارت تط أر على النظام األساسي للصناديق، وبصفة خاصة ما يلي:
−
شروط العضوية.
−
شروط استحقاق الم ازيا وقيمتها.
−
نسب االشت اركات وقيمتها.
−
مساهمة الجهة سواء كانت عينية أو نقدية.
− المصروفات اإلدارية والعمومية أو أي تكاليف خاصة بإدارة الصندوق واستثما ارته.
ويتم اإلفصاح بصورة كتابية مرفًقا بها اإلجارءات القانونية التي تم/أو سيتم اتخاذها نحو اعتمادها من الجمعية
العامة للصناديق، وكذا هيئة الرقابة المالية.
•
إخطار األعضاء كتابيا، أو اإلعالن بصورة تصل بسهولة لكافة األعضاء – في حالة إسناد أي من مهام
ً
إدارة الصناديق لجهة خارجية – بأي تعاقدات/إسناد األعمال إلدارة خارجية، وأهم شروطها والتكاليف
واألعباء المرتبطة بها، وذلك من خالل ملخص كاف .
•
توزيع كل الق ارارت والضوابط الصادرة من الهيئة العامة للرقابة المالية، بشأن الصناديق على األعضاء فور
صدورها من الهيئة ودون أدنى تكلفة.
•
إخطار األعضاء بحقهم في حضور الجمعيات العامة للصناديق وكيفية ممارسة حقوقهم بصورة مكتوبة
وموثقة لكل عضو بصفة شخصية.
•
توفير نسخ من القواعد والضوابط المرتبطة بأعمال الصناديق لكل عضو بصفة شخصية، سواء كان ذلك
بصورة ورقية أو إلكترونية.
68

•
إخطار األعضاء بالحاالت التي يحق لهم فيها دعوة الجمعية العامة، والنصاب القانوني الالزم لذلك،
ونوعية الموضوعات التي يحق لهم عرضها، وكيفية اتخاذ الق ارارت بشأنها.
•
الت ازم القائمين على إدارة الصناديق بعدم نشر أي معلومات مضللة أو غير واضحة أو خاطئة لألعضاء أو
قبل اعتمادها من الجمعية العامة للصندوق أو الهيئة العامة للرقابة المالية، في الحاالت التي تتطلب الحفاظ
على حقوقهم.
•
اإلفصاح لألعضاء عن أي تخفيض للم ازيا المكتسبة مع شرح أسبابها ومبرارتها؛ وذلك بوقت كاف قبل
اتخاذ أي إج ارءات قانونية نحو اعتماد التخفيض.
•
يتعين على إدارة الصناديق أن تقدم ألعضائها تقري ار عن حجم األموال المستثمرة وقنوات استثما رها والمخاطر
ً
المرتبطة بها، وكذلك تكاليف إدا رتها والتي ينبغي أن تحتوي أيض ا على مقارنات متعددة السنوات.
ً
•
يقدم مجلس اإلدارة تقري ار سنوي ا يتضمن مؤش ارت األداء الرئيسية وتحليل لتطور النتائج المالية واالستثما رية
ً ً
للصناديق.
• أن يكون لديها م واقع إلكترونية تنشر عليها كافة المعلومات والبيانات األساسية لها وتقاريرها السنوية،
باإلضافة إلى التوعية المالية لألعضاء.
•
يعتبر الموقع اإللكتروني للهيئة بمثابة أحد المصادر الرئيسية للمعلومات والمواد اإلرشادية للمتعاملين بنشاط
صناديق التأمين الخاصة. وينشر الموقع تقارير مقارنة ألداء الصناديق - لكل صندوق على حدة- من
حيث معدل االستثمار المحقق ومعدل التكلفة اإلدارية بغرض المقارنة واإلفصاح وتقييم األداء.
ب. شروط الدعاية واإلعالن
تلتزم صناديق التأمين الخاصة في مجال الدعاية واإلعالن بما يلي:
•
الحرص على نشر أهدافها من خالل المنشوارت والمطبوعات والنشر على اإلنترنت، مع م ارعاة إيضاح
العناصر األساسية من حيث الم ازيا والمخاطر والتكلفة، وم ارعاة الوضوح وسهولة الفهم، وأن يكون في
مستوى الشخص العادي.
•
الحرص على القيام بالمباد ارت والب ارمج التوعوية عن أنواع وأهداف الصناديق عامة ودورها لدى الجمهور،
وذلك من خالل كافة القنوات المتاحة (إعالم، إذاعة، إنترنت، صحافة، منشوارت، ومطبوعات).
78

•
التواصل مع األعضاء باستخدام وسيلتي اتصال على األقل من الوسائل التي يفضلها األعضاء (مثل البريد
اإللكتروني، البريد المسجل، الرسائل النصية والهاتف).
كما يمكن للصناديق استخدام قنواتهم الرئيسية (الفروع، والموقع اإللكتروني)، وبما يتماشى مع األنظمة
واللوائح والتعليمات والقواعد الصادرة من الهيئة.
•
توخي الحذر عند إرسال أي إشعا ارت أو إعالنات ألكثر من عضو عن طريق البريد اإللكتروني أو وسائل
اتصال أخرى ؛ للتحقق من عدم احتواء اإلشعا ارت المرسلة على معلومات شخصية تخص أعضاء آخرين.
• حظر تقديم أي عروض أو بيانات أو ادعاءات كاذبة أو أن تكون مصوغة بعبا ارت من شأنها أن تؤدي
بطريقة مباشرة أو غير مباشرة إلى خداع أو تضليل األعضاء، حيث تقع المسئولية على اإلدارة في حاالت
التضليل أو الغش.
•
م ارعاة أن تناسب المواد التوعوية كافة الفئات العمرية والثقافية لمختلف األعضاء.
ج. اشتارطات خاصة بصحة العضوية:
•
التوقيع على نموذج العضوية بالصناديق، والتأكد من أنه تم استيفا ؤه مباشرة من األعضاء.
•
انطباق شروط العضوية الواردة بالئحة النظام األساسي للصناديق على األعضاء.
•
وجود نسختين أصليتين من نموذج طلب االنضمام، موقعتين من األعضاء، ومعتمدتين من الصناديق تسلم
إحداها لألعضاء من خالل التوقيع باالستالم في سجل خاص بالعضوية تمسكه الصناديق.
•
إق ارارت موقعة من األعضاء باطالعهم على الئحة النظام األساسي للصناديق وفهمهم لكافة محتوياتها وعدم
وجود أي معلومات غير مفهومة أو غير واضحة لديهم.
•
أن البيانات التي تم استيفا ؤها من جانب األعضاء تتفق مع الواقع وليس بها أي معلومات مضللة أو مزورة
أو غير حقيقية.
•
يا، وأن من حق أي عضو االنسحاب وفًقا
ً
اإلفصاح لألعضاء أن االشت ارك بالصناديق اختياري وليس إجبار
للشروط الالئحة إن وجدت.
88

د. إدارة وحماية حسابات وبيانات العضاء:
تلتزم صناديق التأمين الخاصة بما يلي:
•
استخدام النظم اإللكترونية الالزمة لتحصيل اشت اركات األعضاء وسداد مستحقاتهم بصورة ذاتية أو من
خالل التعاقد الخارجي مع أحد مقدمي هذه الخدمة، بما يساهم فى تعزيز التحول الستخدام المعامالت
المالية اإللكترونية.
•
االحتفاظ بكافة المعلومات الالزمة عن أعضاء الصناديق بسجالت إلكترونية لكل عضو على حدة تتضمن
ما يلى:
−
بالنسبة للصناديق محددة االشتاركات:
- البيانات الشخصية.
- البيانات الوظيفية.
- البيانات المالية ورصيد الحساب االستثما ري .
مع االلت ازم بإخطار األعضاء بصورة دورية كل ثالثة أشهر على األكثر بكشوف الحساب، والتى ت ظهر قيمة
رصيد االستثمار والعائد المحقق، وذلك وفًقا لطرق االتصال المثبتة من األعضاء في نموذج العضوية، مع إعطاء
األعضاء الحق في االعت ارض خالل 51 يوم ا من تاريخ استالم الكشوف؛ وعلى أن تتضمن كشوف الحساب أي
ً
تغيي ارت متوقع حدوثها في السياسة االستثما رية إلدارة أموال وأصول واستثما ارت األعضاء.
−
بالنسبة للصناديق محددة الميزة:
- البيانات الشخصية.
- البيانات الوظيفية.
- البيانات التأمينية مثل الميزة التأمينية، بصفة خاصة المكتسبة (المدد السابقة) وقيم التصفية والخروج المبكر.
- نسب تمويل الم ازيا المكتسبة.
•
تحصيل االشتاركات بشكل سليم وقانوني وقيدها بشكل صحيح، وإحالتها إلى الكيان القائم على إدارة األموال.
98

•
إنشاء عدة سجالت تتضمن ما يلي:
- سجل للعضوية يتضمن كافة البيانات الواردة بنموذج طلب العضوية.
- سجل لمحاضر جلسات مجلس اإلدارة والجمعية العامة.
- سجل لألموال واألصول واالستثما ارت للصناديق وكافة التعامالت المالية والتغيي ارت التي تط أر عليها.
- سجل اإلي اردات متضمنا االشت اركات ومساهمات الجهة/صاحب العمل سواء كانت عينية أو نقدية.
ً
- سجل المصروفات اإلدارية والعمومية.
- سجل مطالبات األعضاء والتعويضات والم ازيا التأمينية أو االجتماعية أو العينية.
- سجل قروض األعضاء إن وجدت.
- سجل الشكاوى والقضايا المرفوعة. (34)
−
تلتزم إدارة الصناديق بعمل فحص اكتواري للم اركز المالية للصناديق كل ثالث سنوات على األكثر؛ لتحديد
التوازن االكتواري بين موارد والت ازمات الصناديق، وكيفية االستفادة من الفائض اإلكتواري إن وجد، أو تدعيم
العجز إن وجد، وبما يحقق استم اررية أداء الصناديق وتحقيق العدالة التأمينية بين األجيال المختلفة لألعضاء.
−
يجب على إدارة الصناديق بذل العناية الالزمة لترشيد استخدام الموارد اإلدارية والمالية والتشغيلية والبشرية
الالزمة لتنفيذ أعمالهم قدر المستطاع والعمل بأمانة لحفظ أصول األعضاء وعدم ضياع مدخ ارتهم.
− الحفاظ على الحقوق المكتسبة لألعضاء وحماية استثما ارتهم من خالل االستعانة بمختصين إلدارة المحافظ
االستثما رية للصناديق.
− ال يجوز استغالل أموال الصناديق واالشت اركات في غير األغ ارض المخصصة لها، ويجب أن تكون أموال
الصناديق مخصصة للوفاء بالت ازماتها.
−
الفصل التام بين أموال الجهة أو صاحب العمل وأموال الصناديق، وعدم استخدام أموال الصناديق للوفاء بأي
الت ازمات على صاحب العمل.
−
تتضمن عملية الترخيص موافقة الهيئة العامة للرقابة المالية على ممارسة الصناديق لنشاطها ود ارسة ورقابة
الهيئة لها لمدى امتثالها للمتطلبات القانونية والفنية الخاصة بالخدمات التأمينية الم ارد تقديمها لألعضاء.
(34) مادة 11 من الالئحة التنفيذية للقانون رقم 45 لسنة 5791 في شأن صناديق التأمين الخاصة.
09

المبدأ الثاني: السلوك والكفاءة المهنية
تلتزم صناديق التأمين الخاصة في مجال السلوك والكفاءة المهنية بما يلي:
أ. أن تكون مسجلة وحاصلة على ت ارخيص من الهيئة قبل بدء ممارسة نشاطها طبًقا ألحكام القانون 45
لسنة 5791، وال يجوز لها بأي حال من األحوال ممارسة نشاطها قبل الحصول على ت ارخيص الهيئة.
ب. أن يتمتع القائم ون على إدارة الصناديق بحسن السير والسلوك، وعدم التورط أو االتهام في أي ج ارئم مخلة
بالشرف واألمانة، أو سوء التصرف أو التعسر المالي، وأيض ا خلو ملفاتهم الوظيفية من أي ج ازءات بسبب
ً
عدم تنفيذ مسئولياتهم الوظيفية بدقة وبصفة خاصة المسئوليات المالية.
ج. أن يتوفر في القائمين على إدارة الصناديق المؤهالت العلمية والكفاءات الالزمة إلدارتها، باإلضافة إلى الت ارخيص
والتأهيل المهني والمها ارت الالزمة، وأيضا التدريب المالئم والمستمر، وبصفة خاصة الموظف ون الذين يتعاملون
ً
مع األعضاء. ويجب التأكد من فهم وإلمام واستيعاب العاملين لدى الصناديق للخدمات المقدمة لألعضاء.
د. وجود سياسات محددة ومعتمدة من مجلس إدارة الصناديق، بشأن عدم تعارض المصالح في كافة أنشطة
الصناديق، بما فيها تلك المتعلقة بإدارة االستثما ارت وتوظيفها. ويجب أن تتضمن اإلج ارءات الالزمة لضمان
التعامل العادل مع كافة األعضاء، باإلضافة إلى توافر أدوات متابعة تنفيذ تلك السياسات والتحقق من تفعيلها.
ه. تلتزم اإلدارة العليا للصناديق باإلفصاح عن أي تعارض للمصالح مع أي تعديالت مقترحة لبنود الم ازيا أو
االشت اركات.
و. م ارعاة اإلفصاح لألعضاء في احتمالية حدوث تعارض للمصالح بين القائمين على إدارة الصناديق
واستثما ارتها، وإذا كان لهذا التضارب أي آثار محتملة على األعضاء.
المبدأ الثالث: العدالة وعدم التمييز بين العضاء
تلتزم صناديق التأمين الخاصة - في مجال العدالة وعدم التمييز بين العضاء - بما يلي:
أ. التعامل بعدل وأمانة وإنصاف مع األعضاء في جميع م ارحل التعامل وعدم التمييز فيما بينهم في الحقوق
والواجبات، وذلك كله في ضوء أحكام الئحة النظام األساسي للصناديق.
ب. أن ت ارعي مصالح األعضاء وتعمل دائم ا على تقديم أفضل الخدمات لتحقيق أعلى درجات األمان وتحقيق
ً
أهداف األعضاء المالية.
19

ج. بذل العناية واالهتمام الخاص باألعضاء بشكل عام وعدم التمييز أو التفضل بينهم، والسيما محدودي التعليم
وكبار السن وذوي االحتياجات الخاصة من الجنسين.
د. عدم التمييز بين األعضاء في توفير المعلومات وإتاحتها، سواء من ناحية التوقيت أو خصوصيتها.
ه. حظر االستثما ارت في األدوات المالية في جهات أو شركات أخرى لها عالقة بالقائمين على إدارة الصناديق
أو الجهة المنشئة للصناديق لمنع تضارب المصالح.
و. ال يجوز القيام بأي ممارسات من شأنها إق ارن أو تقييد أي معاملة مالية بأخرى ؛ بحيث ينبغي أن يكون لألعضاء
حرية االختيار دائم ا بدون ممارسة أي ضغوط، مثل إجبار األعضاء الذين ينضمون لصندوق التأمين الخاص
ً
على ش ارء أي منتجات أخ رى - سواء كانت مرتبطة بالصندوق – أو أي جهة - أو صاحب العمل.
ز. ال يجوز لعضو الصندوق (عضو الجمعية العامة) االشت ارك في التصويت إذا كان موضوع الق ارر المعروض
هو إب ارم اتفاق معه أو رفع دعوى عليه أو إنهاء دعوى بينه وبين الصندوق، وكذلك كلما كانت له مصلحة
شخصية في الق ارر المعروض، فيما عدا انتخاب أجهزة إدارة الصندوق.(44)
ح. أحقية األعضاء في الحصول على مستحقاتهم المالية والمقيمة بطريقة عادلة وفي فترة قصيرة (بحد أقصى
03 يوم من تاريخ استيفاء المستندات المطلوبة) عند تغييرهم صاحب العمل.
ط. ال يجوز استبعاد األعضاء من الصندوق ألي سبب غير منصوص عليه بالالئحة أو ألي أسباب شخصية،
ما لم يكن ذلك ق ارر الجمعية العامة للصندوق.
ي. في حالة تعذر تقديم أي من الخدمات التي تقدمها الصناديق ألعضائها، يحق لألعضاء معرفة أسباب الرفض،
كما يحق لهم استعادة المستندات األصلية التي قدموها للصناديق.
المبدأ ال اربع: حماية خصوصية وسرية حسابات وبيانات العضاء:
تلتزم صناديق التأمين الخاصة في مجال حماية خصوصية وسرية حسابات وبيانات العضاء، بما يلي:
أ. اتخاذ اإلج ارءات الالزمة المناسبة وتفعيل األنظمة الرقابية واستخدام التكنولوجيا الحديثة لحماية قواعد بيانات
األعضاء واكتشاف ومعالجة التجاوازت التي حدثت أو المتوقع حدوثها.
(44) مادة 22 من القانون رقم 45 لسنة 5791.
29

ب. اتخاذ كافة التدابير واإلج ارءات األمنية الالزمة لحماية المعلومات المتبادلة مع األعضاء إلكتروني ا، وتوفير
ً
أحدث التقنيات والب ارمج لضمان حماية وسالمة عمليات الدفع اإللكتروني.
ج. إدارة كافة المخاطر التي قد يتعرض لها األعضاء نتيجة تقديم الصناديق لخدماتها بوسائل إلكترونية.
د. تحمل أية أض ارر أو خسائر قد تلحق باألعضاء بسبب وقوع خلل في األنظمة لدى الصناديق أوعمليات
االحتيال أو االخت ارق التي قد تحدث ألى سبب كان، بخالف ما وقع نتيجة لتقصير من جانب األعضاء.
ه. تطبيق الحد األقصى من التدابير واإلج ارءات األمنية لرقابة حسابات األعضاء واستثما ارتهم وحمايتها من
االحتيال أو االستخدام غير المشروع.
و. عدم اإلفصاح عن معلومات أي من األعضاء ألي طرف ثالث دون تصريح مسبق لذلك من الجهات المعنية
والمختصة، أو بموافقة األعضاء أو المشتركين كتابيا، حيث ال يجوز نشر أو تبادل بيانات ومعلومات عن
ً
تعامالت األعضاء لغير المرخص لهم من قبل القانون.
ز. إخطار األعضاء عند وجود طرف خارجي تنوي تبادل البيانات والمعامالت معهم ألسباب قانونية.
المبدأ الخامس: تسوية الن ازعات ومعالجة شكاوى العضاء:
تلتزم صناديق التأمين الخاصة في مجال تسوية النازعات ومعالجة شكاوى العضاء بما يلي:
أ. التعامل مع الشكاوى داخلي ا:
ً
•
توفير إدارة أو مسئول لتقديم الشكاوى في مكان معلوم لألعضاء تتسم بالفعالية والعدالة والوضوح، وإدارجها على
م واقع الصناديق اإللكترونية، وتوفير نسخ مكتوبة لألعضاء في حال رغبتهم في الحصول عليها. ويجب أن
تتضمن الم واقع اإللكترونية بيانات تفصيلية توضح اإلجارءات التي تقوم بها الصناديق في حالة وجود شكاوى
لألعضاء، مع توضيح أحقية األعضاء في التقدم للهيئة بالشكاوى في حال عدم التوصل لتسوية أو نتائج مرضية.
•
إنشاء ملف لكل شكوى على حدة، توضع فيه كافة األوارق والمستندات المتعلقة بالشكا وى ، وتسجل في السجل
الخاص بها.
•
