المبدأ الول: اإلفصاح والشفافية
أ. تلتزم جهات التمويل لدى تعاملها مع عمالئها باإلفصاح والشفافية، وعلى وجه الخص ما يلي:
•
أن تعرض المعلومات الخاصة بالمنتجات والخدمات التمويلية بلغة سهلة وواضحة متضمنة كافة المفاهيم والشروط
واألحكام األساسية، مع عدم استخدام مصطلحات فنية غير واضحة أو غير ضرورية، وإيضاح كافة النقاط
الغامضة والحرص على عدم تضليل العمالء.
وإذا تم استخدام مصطلحات تقنية فيجب تفسيرها بطريقة واضحة.
• أن يكون حجم الخط وتباعد المسافات بين األحرف والكلمات واضح ا ومقروء ا بسهولة للشخص العادي.
