و. قيد الرهن والضمانات والتأمين - لصالح جهات التمويل - قبل منح التمويل
•
من حق جهات التمويل الحصول على الضمانات الكافية -قبل منح التمويل للعمالء- ضمان ا لقيم التمويل الممنوح.
ً
• (07)
يجب إيضاح الضمانات التي يقدمها العمالء وكيفية تصرف جهات التمويل فيها.
•
يحق لجهات التمويل أن تشترط على العمالء من أصحاب المهن الحرة أن يؤمنوا لصالح الجهات
- بقيمة حقوقهم طبًق ا لعقود التمويل - ضد مخاطر عدم السداد بسبب الوفاة أو العجز أو التعثر؛
وفي حالة جهات التمويل متناهي الصغر تلتزم بالتأمين على عمالئها ضد مخاطر الوفاة والعجز الكلى
(17)
المستديم.
•
يجب أن تتضمن المعلومات المتعلقة بالضمانات الخاصة بالتمويل التالي:
−
الت ازم أط ارف االتفاق بإثبات تاريخ عقد اتفاق التمويل وتوثيقه بالشهر العقاري بالشكل الرسمي العام أو
التصديق عليه بحسب األحوال ووضع الصيغة التنفيذية عليه.
−
البيانات التفصيلية البديلة في الحاالت التي تقبل فيها جهات التمويل ضمانات للتمويل، بخالف قيد الرهن
على العقار أو رهن العقار الضامن مع تحديد نوع وشروط الضمانات البديلة وقيمتها.
− بيانات التأمين على العقار- إن وجدت - وآلية ودورية سداد أقساط التأمين، ومن يتحملها، والمستفيد ون
من وثائق التأمين في حالة وقوع الخطر المغطى تأميني ا.
ً
−
عند استخدام سجل الضمانات المنقولة - لقيد الضمان على أصول منقولة - يجب على جهات التمويل
– باستثناء شركات التمويل العقارى - إخطار عمالئها بأن الضمانة أصبحت قائمة، وال يجوز التصرف
فيها إال بعد الرجوع للشركات الدائنة، وايضاح حقوقهم والت ازماتهم بشأنها.
