ز. اإلجارءات التي يجب أن تتخذها جهات التمويل مع العمالء بعد إبارم عقود التمويل
• (37)
أن يحصل العمالء على كشوف حساب مكتوبة ودورية مجانا مرتين على األقل سنوي ا، تشمل كافة
ً ً
تفاصيل حساباتهم وتعامالتهم وأنواع الحسابات وأنواع عقود التمويل.
•
يحق السداد المعجل للعمالء، بتصفية كل أو جزء من مبلغ التمويل، في أي وقت وقبل تاريخ استحقاقاتهم،
نظير تحملهم مصروفات السداد المعجل وفًقا للشروط المتفق عليها في عق ود التمويل.
(47)
ويلتزم العمالء في تلك الحاالت بإخطار جهات التمويل برغبتهم في السداد المعجل خالل مدة ال تقل عن شهر ،
كما يلتزم ون بسداد عوائد التمويل المستحقة حتى تواريخ السداد المعجل، على أن يتم خفض القيم اإليجارية
(57)
المتغيرة أو األرباح عن المدد المتبقية من عمر التمويل بنسبة مئوية متفق عليها بعق ود التمويل ، وطبًقا
لجداول السداد المرفقة بعقود التمويل.
•
اإلفصاح للعمالء عن جداول السداد الجديدة، بعد السداد المعجل لجزء من قيم التمويل، مع ضرورة إيضاح
التغيي ارت التي ط أرت عليهم.
•
عند تحصيل أي مبالغ من العمالء يجب إعطا ؤهم إيصاالت موقعة ومختومة تفيد السداد، على أن تتضمن
أسماء العمالء وتوا ريخ السداد والمبالغ المسددة وأرقام العق ود موضوع التمويل.
•
يجوز أن يتم السداد باإليداع في حساب جهات التمويل لدى أحد البنوك أو أحد مكاتب الهيئة القومية للبريد
أو مسئولي التحصيل، أو من خالل نظم الدفع اإللكتروني والهاتفية الموافق عليها من الهيئة، أو بأي وسيلة
تم االتفاق عليها في عقود التمويل.
•
يحظر على جهات التمويل وأي طرف ثالث، أن يقوم بأي ممارسات تعسفية أثناء جمع األقساط أو مطالبات
سداد الديون، ويجب أن ينص ص ارحة في عقود التمويل على طرق سداد األقساط.
•
يجب أن يتم إخطار العمالء والحصول على موافقتهم في حالة وجود طرف ثالث مسئول عن جمع األقساط
أو الديون ؛ وعند استخدام طرف ثالث يجب إبالغ العمالء ببيانات الطرف الثالث واإلج ارءات التي يجب أن
يتخذها العمالء في حالة وجود شكاوى وأية مصروفات إضافية ناتجة عن التعامل مع طرف ثالث، وتستمر
مسئولية جهة التمويل بالنسبة للخدمات التمويلية المقدمة.
