المبدأ الثاني: السلوك والكفاءة المهنية
أ. تلتزم جهات التمويل في مجال السلوك والكفاءة المهنية، بما يلي:
• وضع ميثاق مكتوب للسلوك المهني والتشديد على االلت ازم به، مع م ارعاة أداء العاملين لعملهم بطرق مهنية
وأسلوب مسئول.
•
م ارعاة تطبيق اللوائح لقواعد السلوك المهني خاصة للعاملين بإدارة المبيعات والتسويق وخدمة العمالء ومتابعة
التحصيل وحسابات التمويل المتعثرة؛ ويجب تزويد العاملين بنسخ من لوائح قواعد السلوك المهني وأخذ
إق ارارت منهم بااللت ازم بها.
•
أخذ العناية الالزمة لتوفير الموارد اإلدارية والمالية والتشغيلية والبشرية الالزمة لتنفيذ أعمالهم وخدمة عمالئهم
بكل كفاءة ودون تأخير.
• (08)
أن يتوافر لدى القائمين على إدارة جهات التمويل الخب ارت اإلدارية والكفاءات الالزمة لم ازولة النشاط.
• أن يتمتع العامل ون لديها بحسن السير والسلوك، وعدم التورط أو االتهام في أي ج ارئم مخلة بالشرف واألمانة،
أو سوء التصرف أو العسر المالي، وأيض ا خلو ملفاتهم من أي خالفات مع رؤسائهم بسبب عدم تنفيذ
ً
مسئولياتهم الوظيفية بدقة والت ازم.
• أن يتمتع العامل ون لديها بالكفاءات المهنية، ويحصلوا على التدريبات الالزمة، وأن تكون لديهم الخب ارت
الالزمة التي تؤهلهم لمباشرة اختصاصاتهم الوظيفية على أكمل وجه.
•
أن يتمتع الوسطاء من مسئولي المبيعات وخب ارء التقييم العقاري بأعلى درجات الكفاءة والمهنية، بما يمكنهم
من ممارسة دورهم على أكمل وجه.
• أن يتقدم خب ارء التقييم والوكالء العقاري ون ووسطاء التمويل العقاري بطلبات للقيد في جداول الهيئة مرفًقا بها
المستندات التى تثبت استيفاءهم للشروط المطلوبة قبل ممارسة تلك األنشطة؛ وللهيئة - عند إخالل أي من
خب ارء التقييم العقا ري أو الوكالء العقاريين أو وسطاء التمويل العقا ري بأي من الت ازماتهم - اتخاذ ما تاره
(18)
مناسب ا من التدابير، مثل اإل نذار أو وقف مازولة النشاط أو الشطب من سجالت القيد بالهيئة.
ً
• أن يقوم العامل ون بواجباتهم والت ازماتهم وتقديم خدماتهم بأعلى جودة وفي الوقت المناسب، وذلك لما فيه
مصلحة العمالء على طول امتداد العالقة فيما بينهم؛ حيث تعتبر جهات التمويل المسئول األول عن حماية
مصالح عمالئهم.
