ب. كما يتعين مارعاة قواعد السلوك المهنى اآلتية:
•
عند إج ارء اتصاالت مع أقارب العمالء المتعث رين أو جي ارنهم أو زمالئهم أو أصدقائهم، أو زيارة أماكن عملهم؛
بغرض طلب أو نقل المعلومات حول المالءة المالية للعمالء أو الضامنين - يتعين أن يتم ذلك بمهنية؛ للحفاظ
على سمعة العمالء.
•
حصول العاملين على المؤهالت والكفاءات الالزمة التي تتناسب مع صعوبة وتعقيدات المنتجات والخدمات
التمويلية المقدمة للعمالء.
• التأكد من أن العاملين من ذوي العالقة بالعمالء يتمتعون باآلتي:
−
القيام بأداء مهامهم بكفاءة وفعالية ومهنية وقدرة على تقديم الخدمات المنوطة بهم.
−
إتباع السلوكيات الجيدة والتعامل بمهنية عند خدمة العمالء الحاليين أو العمالء المرتقبين في جميع األوقات.
−
اإللمام الكامل بأفضل الممارسات المهنية؛ حتى يتسنى لهم مساعدة العمالء.
•
التأكد من حصول العاملين على التأهيل المهني المطلوب واإليفاء بمتطلبات الكفاءة، من خالل إلحاقهم
بب ارمج متخصصة للحصول على الشهادات المهنية التي تؤهلهم للتعامل مع العمالء.
•
العمل على حماية ممتلكات العمالء من أي أخطار أو نصب أو احتيال قد يلحق بأموالهم واستثما ارتهم.
•
ضرورة تزويد العمالء بأية إشعا ارت أو بيانات أو كشوف متعلقة بحسابهم، حتى وإن كانت هناك ن ازعات من
أي نوع.
•
ح ا لبنود االحتيال والرشوة والعموالت والهدايا.
ً
تضمين الميثاق المهني تعريًف ا واض
• التنافس في تقديم أفضل المنتجات والخدمات واألسعار بما يلبي احتياجات العمالء ورغباتهم، دون اإلخالل
بما تقتضيه األنظمة واللوائح في هذا الشأن.
• أن يكون لدى جهات التمويل سياسة مكتوبة وواضحة ومعتمدة من مجلس اإلدارة بشأن تعارض المصالح،
وتحديد اإلج ارءات الالزمة لضمان التعامل العادل مع كافة العمالء، والعمل بشكل مستمر وفعال للتأكد من
كفاية اإلج ارءات المتبعة والسياسات المطبقة في كشف الحاالت المحتملة لتعارض المصالح.
•
في حالة حدوث تعارض للمصالح بين جهات التمويل وأي أط ارف أخ رى ، وكان لهذا التعارض أي أثر محتمل
على العمالء، ينبغي اإلفصاح للعمالء عن تعارض المصالح، وفًقا لما تقتضيه األنظمة واللوائح والتعليمات
ذات العالقة.
