• أن تكون هناك سياسات وإج ارءات واضحة موضوعة من قبل اإلدارة العليا لجهات التمويل لتجنب تعارض
المصالح، والتي قد تنشأ بسبب نظم المرتبات والمكافآت المخصصة للموظفين أو الوسطاء، والمرتبطة فقط
بزيادة عدد وقيمة التمويل للعمالء الحاليين والمرتقبين.
•
توفير آلية لإلبالغ عن المخالفات األخالقية للعاملين وكيفية تقديم تلك الشكاوى عن سوء معاملة العمالء
لإلدارة العليا بجهات التمويل.
ج. ويجب أن تحظر لوائح قواعد السلوك المهني اآلتي:
•
التواصل مع العمالء المتعث رين باستخدام مغلفات مكتوب على ظاهرها كلمات تشير إلى أنها تحتوي على
معلومات لتحصيل الديون.
•
أي تجاو ازت لسرية معلومات العمالء، وتضارب المصالح والقيم المهنية.
•
تعامل جهات التمويل والعاملين لديها مع وسطاء غير رسميين؛ لمنع الضرر الذي قد يقع على العمالء نتيجة
مثل هذه التعامالت.
• استقطاب العاملين بجهات التمويل لعمالئهم حال االنتقال بين الجهات العاملة بالسوق ، بما قد يضر بمصالح
العمالء وقد ارتهم على السداد، وكذا يؤثر على سالمة الم اركز المالية لجهات التمويل.
المبدأ الثالث: العدالة وعدم التمييز بين العمالء
تلتزم جهات التمويل في مجال العدالة وعدم التمييز بين العمالء بما يلي:
أ. العمل بأمانة وعدل وإنصاف مع العمالء في جميع م ارحل العالقة بينهم، كما يجب على جهات التمويل الوفاء
بااللت ازمات بالعقود المبرمة وباألنظمة واللوائح والقوانين والتعليمات الصادرة.
ب. بذل العناية واالهتمام الخاص بالعمالء بشكل عام، والسيما محدودي الدخل والع لم وكبار السن وذوي
االحتياجات الخاصة من الجنسين.
ج. عدم التمييز أو التفضيل في التعامل بين عمالئها (الحاليين أو المرتقبين) بسبب العرق أو الجنس أو الدين.
د. عدم القيام بأي ممارسات من شأنها اقت ارن أو تقييد أي معامالت مالية بأخرى ؛ كما ينبغي أن يكون للعمالء
حرية االختيار دائم ا بدون ممارسة أي ضغوط، ويكون باطال ً أي نص في العقود يخالف أو يقيد أي حق
ً
للعمالء بنص القانون.
111

ه. أي غموض أو التباس يرد في أي بند من بنود عقود التمويل يفسر لصالح بعض العمالء دون البعض اآلخر.
و. ال يجوز ممارسة أي ضغوط أو إك اره أو تمييز أثناء سريان عقود التمويل.
ز. االلت ازم بمعاملة العمالء بشكل جيد وباحت ارم حتى عند التأخير في االلت ازم بواجباتهم التعاقدية، وكذلك يجب
على شركات التمويل أن ت ارعي تواجد الضمانات المالئمة لتتبع حاالت الفساد وتصحيحها، وكذلك التأكيد
28
على حسن التعامل من قبل موظفيهم، وباألخص خالل عمليات التحصيل( ) لألقساط أو المتأخ ارت.
ح. يحظر على مسؤلي المبيعات لدى جهات التمويل اللجوء إلى سياسات ربط المنتجات التمويلية بعضها ببعض،
مثل ربط شارء وثائق تأمين من شركة معينة للحصول على التمويل من جهة التمويل، والتي يكون لديها تعاقدات
أو اتفاقات تجارية سارية مع شركة التأمين، مما يحد من اختياارت العمالء، وقد يؤدي لتقليص المنافسة في السوق ؛
لذلك يجب أن يتم اإلفصاح للعمالء قبل التعاقد عن المنتجات المرتبطة، وأن يكون لدى العمالء حق االختيار
للمنتج الثاني (في هذا المثال، ش ارء الوثائق من أي شركة تأمين أخرى في السوق ).
ط. يحظر على مسئولي المبيعات في جهات التمويل اللجوء إلى الممارسات الخاطئة، مثل االتصال واإللحاح
لتقديم قروض لعمالء جدد بدون رغبتهم؛ مما قد يعرض العمالء لخطورة فرط االستدانة، خاصة األف ارد من
ذوي الدخول المنخفضة؛ نتيجة لقلة ثقافتهم المالية.
ي. أن تستجيب لطلب العمالء في إنهاء التعاقد المبرم معهم، وأن يتم ذلك في فترة ال تتجاوز ثالثة أيام عمل
بعد استيفاء العمالء كافة اإلج ارءات المطلوبة لغلق حساباتهم لديها، مما يسهل عملية انتقال حسابات العمالء
- طبًق ا ل رغبتهم - لشركات أخرى منافسة بدون تعطيل أو تسويف.
ك. في حالة تعذر تقديم المنتجات أو الخدمات التمويلية للعمالء، يحق للعمالء معرفة أسباب الرفض، كما يحق
لهم استعادة المستندات األصلية التي قدموها لجهات التمويل.
(28) قارر مجلس إدارة الهيئة رقم 321 بتاريخ 61/ 01/ 6102.
211

(38)
المبدأ ال اربع: حماية خصوصية وسرية حسابات وبيانات العمالء
تلتزم جهات التمويل في مجال حماية خصوصية وسرية حسابات وبيانات العمالء بما يلي:
أ. أن تحتفظ لديها دائم ا بقاعدة معلومات وبيانات العمالء وأن يتم تحديثها دوري ا، وينبغي احت ارم خصوصية تلك
ً ً
البيانات سواء الشخصية أو المالية أو التم ويلية.
ب. حماية بيانات وحسابات العمالء الشخصية والمالية والتمويلية، وعدم استخدامها إال ألغ ارض مهنية محددة
ونظامية وعدم الكشف عنها إال بموافقة العمالء، باستثناء اآلتي:
−
عندما يقتضي األمر الكشف عن تلك المعلومات بأمر إل ازمي تفرضه القوانين مثل حكم قضائي أو أمر
من النائب العام.
−
عندما يتم الكشف عن المعلومات بموافقة العمالء أو المستفيدين كتابيا.
ً
ج. اتخاذ اإلج ارءات المناسبة وتفعيل األنظمة الرقابية واتخاذ كافة التدابير واإلج ارءات األمنية الالزمة؛ لحماية
بيانات العمالء، واكتشاف ومعالجة التجاوازت التي حدثت أو المتوقع حدوثها، وحمايتها عند التعامل مع أي
طرف ثالث بشكل مباشر أو غير مباشر.
د. الحفاظ على سرية البيانات والمعلومات التي تحصل عليها من جهة االستعالم االئتماني والتصنيف اإلئتماني
(48)
والتعهد باقتصار استخدامها في األغ ارض المتعلقة بمنح التمويل.
ه. عند إرسال إعالنات أو إشعا ارت ألكثر من عميل عن طريق البريد اإللكتروني أو أي وسيلة اتصال أخرى،
أن تتحقق جهات التمويل من عدم احتواء اإلشعا ارت المرسلة على معلومات شخصية تخص عمالء آخرين.
و. على العاملين بجهات التمويل، الدائمين أو المؤقتين، التوقيع على نماذج المحافظة على السرية بشأن بيانات
العمالء، والتأكد من عدم كشفهم عن المعلومات الشخصية أو المالية للعمالء ومنع الدخول عليها، واقتصارها
على األشخاص المخولين فقط، سواء أثناء العمل أو بعد تركهم لوظائفهم.
ز. اتخاذ اإلج ارءات المناسبة وتفعيل األنظمة الرقابية واستخدام التكنولوجيا الحديثة؛ لحماية قواعد بيانات العمالء،
واكتشاف ومعالجة التجاوازت التي حدثت أو المتوقع حدوثها.
(38) قارر مجلس إدارة الهيئة رقم 321 بتاريخ 61/ 01/ 6102.
(48) قارر مجلس إدارة الهيئة رقم 321 بتاريخ 61/ 01/ 6102.
