ح. تطبيق الحد األقصى من التدابير واإلج ارءات األمنية لرقابة عمليات التمويل وحمايتها من االحتيال أو
االستخدام غير المشروع.
ط. اتخاذ كافة التدابير واإلج ارءات األمنية الالزمة لحماية المعلومات المتبادلة مع العمالء إلكتروني ا، وتوفير أحدث
ً
التقنيات والب ارمج لضمان حماية وسالمة عمليات الدفع اإللكتروني.
ي. إدارة كافة المخاطر التي قد يتعرض لها العمالء نتيجة تقديم المنتجات والخدمات التمويلية بوسائل إلكترونية.
ك. تحمل أية أض ارر أو خسائر قد تلحق بالعمالء بسبب وقوع خلل في األنظمة لدى جهات التمويل أو عمليات
االحتيال أو االخت ارق التي قد تحدث ألي سبب كان، بخالف ما وقع نتيجة لتقصير من جانب العمالء.
المبدأ الخامس: تسوية الن ازعات ومعالجة شكاوى العمالء
تلتزم جهات التمويل في مجال تسوية النازعات ومعالجة شكاوى العمالء بما يلي:
أ. التعامل مع الشكاوى داخلي ا
ً
•
توفير آلية مناسبة للمستثم رين لتقديم شكواهم، تتسم بالفعالية والعدالة والوضوح، ويمكن من خاللها متابعة
ومعالجة الشكاوى دون تأخير، وفًق ا لألنظمة واللوائح والتعليمات الصادرة من الهيئة والجهات ذات العالقة.
•
إخطار العمالء باإلج ارءات التي تم اتخاذها في سبيل فحص الشكاوى.
•
إنشاء ملف لفحص أي شكاوى ترد إليهم تودع فيه كافة األوارق والمستندات المتعلقة بالشكاوى.
• تسوية الشكاوى بكل ن ازهة وعدل ودون تمييز، وأن يتم البت فيها بحد أقصى ثالثين يوم ا من تاريخ ورود
ً
الشكاوى، ويصدر الق ارر إما بالقبول أو بالرفض مسبب ا.
ً
•
أن تخطر اإلدا ارت المختصة (الفحص واالمتثال والتفتيش) بالهيئة بأسباب رفض الشكاوى ، سواء كان الرفض
كلي ا أو جزئي ا لطلبات الشاكين.
ً ً
•
شرح إج ارءات تقديم الشكاوى ، وإذا لم يقبل العمالء بالتسوية التي تم إج ارؤها، فيجب توجيههم إلى اإلدارة
المختصة بالهيئة.
411

• (58)
توفير وحدة لتقديم الشكاوى في مكان معلوم لكافة عمالئها، وإد ارجها على م واقع جهات التمويل
اإللكترونية، وتوفير نسخ من الرد على الشكوى للعمالء في حال رغبتهم في الحصول عليها مكتوبة، ويجب
أن تتضمن م واقع الجهات اإللكترونية بيانات تفصيلية ت وضح اإلج ارءات التي تقوم بها الجهات أو الوسطاء
في حالة وجود شكاوى للعمالء، مع توضيح أحقية العمالء في التقدم للهيئة بالشكاوى حال عدم التوصل لحل
(68)
يرضي أصحاب الشكاوى.
• عند تلقي شكاوى العمالء يتعين القيام بالتالي:
−
اإلق ار رت الكتابية باستالم الشكاوى.
−
تزويد العمالء بم ارجع االتصال لمتابعة الشكاوى المقدمة.
−
إبالغ العمالء بما تم في الشكاوى المقدمة منهم.
−
تسوية الشكاوى بشكل سريع وعادل وخالل مدة ال تتجاوز 03 يوم ا من تاريخ استالمهم للشكاوى.
ً
−
إرسال إشعا ارت للعمالء خطي ا بقبول الشكوى أو رفضها، وتوضيح األسباب الداعية لذلك، وأي تعويضات
ً
معروضة على العمالء، وتوضيح أسباب االختالف في قيم التعويضات المعروضة على العمالء.
ب. التعامل مع الشكاوى خارجي ا
ً
•
بخالف ما تقدم، إذا لم يوافق العمالء على النتائج النهائية التي اتخذتها إدارة الشكاوى بجهات التمويل،
يحق للعمالء اللجوء إلى الهيئة، أو اللجوء لوسائل أخرى مثل: م اركز التحكيم لتسوية الن ازعات المالية، والتي
يجب أن يكون منصوص ا عليها في العقود المبرمة أو في القانون المنظم للنشاط.
ً
•
وفي جميع األحوال واألوقات، للعمالء الحق في اللجوء للقضاء؛ للفصل في أي ن ازع ينشأ بين األط ارف.
(58) فيما يخص جهات التمويل متناهي الصغر، يعد فرع التمويل والمركز الرئيسي لجهة التمويل وحدة تقديم الشكاوى، ويتم إيضاح ذلك للعمالء بشكل واضح فى
الفروع، مع ضمان توفير وسيلة إلكترونية للعمالء مثل البريد اإللكترونى/الفاكس أو خط ساخن وما شابه لتقديم الشكاوى. ويتوجب على الجهة إرسال تقارير
كل 6 أشهر للهيئة متضمنة ما تم اتخاذه بشأنها من إجارءات.
(68) قارر رقم 508 لسنة 6102 بشأن ضوابط المواقع اإللكترونية لشركات ووسطاء التأمين أو إعادة التأمين على شبكة المعلومات الدولية لتقديم خدمات أفضل.
511

المبدأ السادس: سبل الضمانات والتعويضات
أ. في حاالت تعثر أو إفالس العمالء يجب على جهات التمويل:
•
إخطار العمالء مسبًقا وبفترة وافية لتجنب فرط االستدانة والتعثر.
•
تقديم مشورة للعمالء المتعثرين أو على وشك اإلفالس.
• إخطار العمالء المتعثرين كتابي ا وفي الوقت المناسب ودون تأخير، وتعريفهم بالحاالت التي ينطبق عليها
ً
اإلفالس، وما سيتم اتخاذه من إج ارءات في حالة تعثرهم وتبعيات تعثرهم.
• (78)
إتاحة ما يأتي للعمالء المتعثرين :
- تقديم التماس لجهات التمويل عند إعالنهم اإلفالس.
- تقديم طلب اتفاق لجدولة الديون.
- تقديم طلب إفالس.
عا وفًق ا لمتطلبات قانون رقم 11 لسنة 8102، بشأن الموافقة على إعادة
ً
- اختيار إعالن اإلفالس طو
الهيكلة والصلح الواقي واإلفالس.
- استبعاد بعض األصول الالزمة للحياة األساسية الشخصية للعمالء المفلسين من إعالن التفليسة.
- عند إعالن إفالس العمالء المتعثرين، يتم حمايتهم من الج ازءات الجنائية وغير المنطقية (ما لم يكن
هناك عمليات بها احتيال أو غش أو تدليس).
- إنهاء حالة اإلفالس وكافة المتعلقات الخاصة بالديون ، بناء على أسباب منطقية تنهي تلك الحالة وبعد
ً
فترة محددة.
• في حاالت إعالن التفليسة، تخطر الجهة المسئولة عن إدارة ديون المستثمرين/المقترضين المفلسين بخيا ارت
معالجة الديون واإلج ارءات المتبعة إلنهاء حاالت التفليسة.
•
في جميع حاالت تعثر العمالء، يتم اللجوء أوالً إلى الضمانات المرهونة والمشار إليها مسبًق ا.
(78) فيما يخص جهات التمويل متناهي الصغر ال تسرى مواد اإلفالس على عمالء التمويل الجماعى. وعند سريانها على عمالء التمويل الفردي، فإنها تسري فقط
يا، وفًقا للقوانين ذات العالقة بنشاطه، سواء كشخص اعتبارى - دون شركات
ً
بالنسبة للعميل الذي يمارس نشاطه االقتصادي محل التمويل بشكل موثق رسم
المحاصة - أو كشخص طبيعي، شريطة أن تنطبق عليه شروط التاجر، وفًقا للتعريف الوارد فى المادة (01) من قانون التجارة الصادر بالقانون رقم 71
لسنة 9991.
611

ب.الت ازمات هامة تخص عمالء جهات التمويل
•
الصدق عند تقديم المعلومات
تقديم المعلومات الكاملة والدقيقة عند تعبئة أي نماذج تطلبها جهات التمويل، واالمتناع عن تقديم أي معلومات
مضللة أو خاطئة أو غير مكتملة أو عدم اإلفصاح عن المعلومات الهامة أو الجوهرية.
•
القارءة بدقة كافة المعلومات التي تقدمها جهات التمويل
يتم تسليم العمالء التفاصيل الكاملة بشأن االلت ازمات المترتبة عليهم مقابل حصولهم على المنتجات والخدمات
التمويلية، ويجب على العمالء االطالع على تلك االلت ازمات، والتأكد من فهمهم لها بشكل واضح وقدرتهم
على االلت ازم بها.
•
طرح السئلة
في حال عدم وضوح أي بند أو شرط في عق ود التمويل أو أي مستندات أخرى مقدمة من قبل جهات التمويل،
فإنه يحق للعمالء االستفسار عنها وطرح األسئلة على موظفي الجهات؛ ويجب على الموظفين اإلجابة على
تلك األسئلة بأسلوب مهني وواضح يساعد العمالء على اتخاذ الق ار ارت المناسبة.
•
التأكد من بيانات عق ود التمويل
يجب على العمالء التأكد من أن نسخ عقود التمويل تشمل كافة محتويات العق ود، ومن ذلك على سبيل
المثال ال الحصر، البيانات الشخصية ومبالغ التمويل ومعدالت أسعار الفوائد السن وية وعق ود التمويل، وتشمل
كذلك كافة ملحقات العقد كجداول السداد واإلق ارارت المرفقة وغيرها.
• معرفة كيفية تقديم الشكاوى
يجب أن توفر جهات التمويل المعلومات والبيانات الالزمة، بشأن آلية تقديم الشكاوى واإلطار الزمني لموافاة
العمالء بنتائج الشكاوى؛
ويجب على العمالء التأكد من حصولهم على أرقام وعناوين االتصال لتقديم الشكاوى ومتابعاتها؛
ويجب على العمالء استخدام تلك الخدمات ومعرفة كيفية رفع الشكاوى إلى المستويات العليا بجهات التمويل
عند الضرورة.
•
استخدام المنتجات والخدمات التمويلية بموجب الحكام والشروط
يجب أال يستخدم العمالء المنتجات والخدمات التمويلية إال وفًقا لألحكام والشروط المرتبطة بهم، وذلك بعد
التأكد من فهمها بشكل كامل.
711

•
عدم التعرض للمخاطر
تحتوي بعض المنتجات والخدمات التمويلية على مستويات متفاوتة من المخاطر، فيجب على جهات التمويل
شرحها للعمالء بوضوح؛
ويجب أال يقوم العمالء بش ارء أي منتجات وخدمات تمويلية عند الشعور أن مخاطر تلك المنتجات والخدمات
التمويلية ال تتالءم مع وضعهم المالي.
•
تقديم طلبات للحصول على المنتجات والخدمات المالئمة مع احتياجات العمالء
عند تقديم العمالء طلبات الحصول على المنتجات والخدمات التمويلية، يجب عليهم التأكد من مالءمتها
الحتياجاتهم، وأن يتم اإلفصاح عن كافة الت ازماتهم المالية مع كافة الجهات الممولة، وأن يدرك العمالء أن
ق ار ارتهم تعتمد على قدرتهم في الوفاء بااللت ازمات المترتبة بعد الحصول على المنتجات والخدمات التمويلية.
•
إبالغ جهات التمويل في حال وجود أي إجارءات غير نظامية
في حال اكتشاف العمالء وجود أي إج ارءات مخالفة وغير نظامية للقوانين واللوائح تمس المنتجات والخدمات
التمويلية المقدمة لهم، يجب عليهم إبالغ جهات التمويل بذلك على الفور، مع م ارعاة اتخاذ اإلج ارءات السليمة
األخرى، وفي حال عدم تجاوب الجهات، فإنه يحق لهم التقدم بشكا وى إلى الهيئة.
•
استشا رة جهات التمويل في حال مواجهات أي صعوبات مالية
يجب على العمالء التحدث مع جهات التمويل التي يتعاملون معها لطلب االستشارة في حال مواجهة أي
صعوبات مالية، أو عدم قد رتهم على تحمل الت ازمات المنتجات والخدمات التمويلية؛ حتى يستطيعوا مناقشة
الخيا ارت المتاحة بما يتناسب مع وضعهم المالي.
•
تحديث المعلومات
ينبغي على العمالء تحديث بياناتهم الشخصية بما فيها بيانات االتصال، بحيث يتم التحديث بشكل دوري،
وعندما تطلب جهات التمويل ذلك؛
وينبغي أن يدرك العمالء أن عدم تحديث بياناتهم الشخصية وال سيما الجوهرية منها قد يؤدي إلى نشوء
مسئولية عليهم أو ضياع حقوقهم.
•
وسائل االتصال
يجب على العمالء أن يستخدموا عنوان البريد (البريد العادي/ أو البريد اإللكتروني) وأرقام االتصال الخاصة
بهم وتقديمها عندما تطلبها منهم جهات التمويل التي يتعاملون معها، وال يجوز استخدام عناوين أخرى ال
تخصهم مثل األصدقاء أو األقارب، منعا إلفشاء معلوماتهم الشخصية.
