الوكالة العامة
يجب على العمالء أن يكونوا حذ رين عند إصدار التوكيالت العامة ألي أشخاص إلنجاز تعامالتهم المالية،
وأن يعلموا جيدا لمن ت عطى صالحية التصرف في شئونهم المالية ومن يطلع عليها.
ً
•
عدم التوقيع على نماذج (االستماارت) غير المكتملة أو الفا رغة
يجب على العمالء التأكد من اكتمال كافة المواضيع واألرقام المطلوبة في النماذج المقدمة لهم للتوقيع عليها،
وأال يق وموا بالتوقيع على أي نماذج فارغة أو غير مكتملة.
•
مارجعة جميع المعلومات والبيانات
يجب على العمالء مارجعة جميع المعلومات التي سجل وها في النماذج لضمان صحة المعلومات وعدم وجود أي
أخطاء في البيانات المدونة، وأن يعلموا أن التوقيع الخاص بهم على النماذج يعني الموافقة على محت ويات النماذج.
•
عدم اإلفصاح عن معلوماتهم الشخصية أو المالية
يجب على العمالء عدم اإلفصاح عن أي معلومات شخصية أو مالية ألي طرف آخر غير جهات التمويل
وتحت أي ظرف من الظروف.
يتعين على العمالء اإلفصاح لجهات التمويل عن أي معلومات ذات صلة بالمنتجات والخدمات التمويلية
المطلوبة، والمعلومات الضرورية لتحديد احتياجاتهم المالية وتقييم المخاطر التي قد يتعرضون لها.
•
أحقية العمالء في الحصول على نسخ من العقود والمستندات الموقعة
يجب على العمالء التأكد من حصولهم على نسخ من العقود والمستندات الموقعة مع جهات التمويل واالحتفاظ
بها في أماكن آمنة.
